package com.irc;

import org.junit.Test;

import javax.swing.JComboBox;
import javax.swing.JTabbedPane;
import java.lang.reflect.Field;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The nicklist dropdown: a compact action menu left of the buffer dropdown.
 *
 * Index 0 is a "Users (N)" header rather than a selectable user, and picking a real entry opens
 * that user's PM buffer then snaps back to the header - it is a menu, not a persistent selection.
 * The real protection against reentrant repopulation is the {@code index < 1} guard in
 * {@code openQueryFromNickDropdown} - every spurious action event a model mutation can fire
 * arrives at index -1 or 0, which that guard already rejects. The listener detach/reattach in
 * {@code repopulateNickDropdown} is defensive depth kept to match {@code renameBufferDropdownItem}'s
 * precedent, not something this test suite can exercise: {@code initializeGui} is the only place
 * the tab-change listener is installed, and it never runs in a headless test.
 */
public class IrcPanelNickListTest {

    /**
     * Builds a panel through addChannel so channelPanes stays index-aligned with tabbedPane -
     * setFocusedChannel maps a channel to a tab by position, so injecting tabs directly would
     * desync the two and getCurrentChannel() would report the wrong buffer.
     */
    private static IrcPanel panelWith(String... channels) throws Exception {
        IrcPanel panel = new IrcPanel();
        set(panel, "config", stubConfig());
        set(panel, "tabbedPane", new JTabbedPane());

        for (String channel : channels) {
            panel.addChannel(channel);
        }
        panel.setFocusedChannel(channels[0]);
        return panel;
    }

    /** Every IrcConfig method is default except username() and password(). */
    private static IrcConfig stubConfig() {
        return new IrcConfig() {
            @Override
            public String username() {
                return "tester";
            }

            @Override
            public String password() {
                return "";
            }
        };
    }

    private static void set(Object target, String field, Object value) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    @SuppressWarnings("unchecked")
    private static JComboBox<String> nickDropdown(IrcPanel panel) throws Exception {
        Field f = IrcPanel.class.getDeclaredField("nickDropdown");
        f.setAccessible(true);
        return (JComboBox<String>) f.get(panel);
    }

    private static List<ChannelUserList.Entry> roster() {
        return Arrays.asList(
                new ChannelUserList.Entry("bob", "@", 2),
                new ChannelUserList.Entry("dave", "+", 4),
                new ChannelUserList.Entry("erin", "", Integer.MAX_VALUE));
    }

    @Test
    public void headerReportsTheUserCount() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());
        assertEquals("Users (3)", nickDropdown(panel).getItemAt(0));
    }

    @Test
    public void entriesRenderWithTheirPrefix() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());

        JComboBox<String> dropdown = nickDropdown(panel);
        assertEquals(4, dropdown.getItemCount());
        assertEquals("@bob", dropdown.getItemAt(1));
        assertEquals("+dave", dropdown.getItemAt(2));
        assertEquals("erin", dropdown.getItemAt(3));
    }

    @Test
    public void headerIsSelectedAfterPopulating() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());
        assertEquals(0, nickDropdown(panel).getSelectedIndex());
    }

    @Test
    public void selectingANickOpensAndFocusesThatPmBuffer() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());

        nickDropdown(panel).setSelectedIndex(1); // "@bob"

        assertTrue("a PM buffer for bob should exist", panel.isPane("bob"));
        assertEquals("and it should be focused", "bob", panel.getCurrentChannel());
    }

    @Test
    public void selectingANickStripsThePrefixFromTheBufferName() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());

        nickDropdown(panel).setSelectedIndex(1); // "@bob"

        assertTrue(panel.isPane("bob"));
        assertFalse("the prefix is decoration, not part of the nick", panel.isPane("@bob"));
    }

    @Test
    public void selectingANickSnapsBackToTheHeader() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());

        nickDropdown(panel).setSelectedIndex(2); // "+dave"

        assertEquals("action menu, not a persistent selection", 0, nickDropdown(panel).getSelectedIndex());
    }

    @Test
    public void reSelectingTheHeaderAfterAnActionOpensNothingNew() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", roster());

        nickDropdown(panel).setSelectedIndex(1);   // opens "bob", then snaps back to the header
        int buffersAfterPick = panel.getChannelNames().size();

        nickDropdown(panel).setSelectedIndex(0);   // the header is not an action

        assertEquals("header selection must not open a buffer", buffersAfterPick, panel.getChannelNames().size());
    }

    @Test
    public void anUpdateForAnUnfocusedChannelDoesNotRedrawTheDropdown() throws Exception {
        IrcPanel panel = panelWith("#chan", "#other");
        panel.setChannelUsers("#chan", roster());                       // #chan is tab 0, focused
        panel.setChannelUsers("#other", Collections.singletonList(
                new ChannelUserList.Entry("zoe", "", Integer.MAX_VALUE)));

        assertEquals("still showing #chan's roster", "Users (3)", nickDropdown(panel).getItemAt(0));
    }

    @Test
    public void aRosterPushedWithDifferentChannelCasingStillShows() throws Exception {
        // The tab title comes from a JOIN echo; the roster's channel comes from a 366 numeric.
        // A server that canonicalises those differently must not silently break the dropdown.
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#CHAN", roster());
        assertEquals("Users (3)", nickDropdown(panel).getItemAt(0));
    }

    @Test
    public void dropdownIsDisabledOnNonChannelBuffers() throws Exception {
        IrcPanel panel = panelWith("System");
        panel.setChannelUsers("System", Collections.emptyList());
        assertFalse(nickDropdown(panel).isEnabled());
    }

    @Test
    public void dropdownEnablementFollowsTheFocusedBuffer() throws Exception {
        // A fresh JComboBox is enabled by default, so only a transition proves setEnabled runs.
        IrcPanel panel = panelWith("System", "#chan");

        panel.setFocusedChannel("System");
        panel.setChannelUsers("System", Collections.emptyList());
        assertFalse("System is not a channel", nickDropdown(panel).isEnabled());

        panel.setFocusedChannel("#chan");
        panel.setChannelUsers("#chan", roster());
        assertTrue("#chan is a channel", nickDropdown(panel).isEnabled());
    }

    @Test
    @SuppressWarnings("unchecked")
    public void aRosterArrivingBeforeTheGuiExistsIsStoredNotDropped() throws Exception {
        // setChannelUsers can arrive from the IRC thread before initializeGui has run. It must
        // skip the redraw without throwing, and still keep the roster for when the GUI catches up.
        IrcPanel panel = new IrcPanel(); // tabbedPane is still null
        panel.setChannelUsers("#chan", roster());

        Field field = IrcPanel.class.getDeclaredField("channelUserSnapshots");
        field.setAccessible(true);
        Map<String, List<ChannelUserList.Entry>> snapshots =
                (Map<String, List<ChannelUserList.Entry>>) field.get(panel);

        assertEquals("roster kept despite no GUI to draw it on", 3, snapshots.get("#chan").size());
    }

    @Test
    public void anEmptyRosterLeavesOnlyTheHeader() throws Exception {
        IrcPanel panel = panelWith("#chan");
        panel.setChannelUsers("#chan", Collections.emptyList());

        JComboBox<String> dropdown = nickDropdown(panel);
        assertEquals(1, dropdown.getItemCount());
        assertEquals("Users (0)", dropdown.getItemAt(0));
    }

    @Test
    public void switchingToAPmBufferClearsAndDisablesTheDropdown() throws Exception {
        // The tab-change hook is the single path every buffer switch routes through, and
        // initializeGui (its only install site) cannot run headless - so drive it directly.
        IrcPanel panel = panelWith("#chan", "bob");
        panel.setFocusedChannel("#chan");
        panel.setChannelUsers("#chan", roster());
        assertEquals("Users (3)", nickDropdown(panel).getItemAt(0));

        panel.setFocusedChannel("bob");
        panel.onFocusedBufferChanged();

        assertEquals("a PM buffer has no roster", "Users (0)", nickDropdown(panel).getItemAt(0));
        assertEquals(1, nickDropdown(panel).getItemCount());
        assertFalse("and the dropdown is not usable there", nickDropdown(panel).isEnabled());
    }
}

package com.irc;

import org.junit.Test;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The palette nicks are colored from, shared by the chat pane and the nicklist dropdown so a
 * nick looks the same in both.
 *
 * 36 codes: the classic 02-13 plus the extended palette's vivid and pastel rows 64-87. The
 * near-black rows (16-39) and dark grays (88-93) are excluded as unreadable on the dark panel.
 */
public class IrcNickColorTest {

    /** Reflection-free access: the palette is exercised through nickColorId's full range. */
    private static Set<String> allProducedIds() {
        Set<String> ids = new HashSet<>();
        for (int i = 0; i < 5000; i++) {
            ids.add(IrcPanel.ChannelPane.nickColorId("nick" + i));
        }
        return ids;
    }

    @Test
    public void paletteHasThirtySixColors() {
        assertEquals(36, allProducedIds().size());
    }

    @Test
    public void paletteKeepsTheClassicCodesTwoThroughThirteen() {
        Set<String> ids = allProducedIds();
        for (String classic : Arrays.asList("02", "03", "04", "05", "06", "07", "08", "09", "10", "11", "12", "13")) {
            assertTrue("classic code " + classic + " should still be in the palette", ids.contains(classic));
        }
    }

    @Test
    public void paletteIncludesExtendedRowsSixtyFourThroughEightySeven() {
        Set<String> ids = allProducedIds();
        for (int code = 64; code <= 87; code++) {
            assertTrue("extended code " + code + " should be in the palette", ids.contains(String.valueOf(code)));
        }
    }

    @Test
    public void paletteExcludesUnreadableRows() {
        Set<String> ids = allProducedIds();
        assertFalse("00/01 are pure white and black", ids.contains("00") || ids.contains("01"));
        assertFalse("16 is near-black", ids.contains("16"));
        assertFalse("88 is a dark gray", ids.contains("88"));
    }

    @Test
    public void everyPaletteEntryResolvesToARealColor() {
        for (String id : allProducedIds()) {
            String color = IrcPanel.ChannelPane.htmlColorById(id);
            assertTrue("code " + id + " must resolve to a hex color, got: " + color, color.startsWith("#"));
        }
    }

    @Test
    public void nickColorIdIsDeterministic() {
        assertEquals(IrcPanel.ChannelPane.nickColorId("bob"), IrcPanel.ChannelPane.nickColorId("bob"));
    }

    @Test
    public void nickColorIdHandlesTheMinimumHashCodeWithoutCrashing() {
        // Math.abs(Integer.MIN_VALUE) is still Integer.MIN_VALUE, so the old
        // "Math.abs(h) % length" produced a negative index here. Math.floorMod does not.
        assertEquals(Integer.MIN_VALUE, "polygenelubricants".hashCode());
        String id = IrcPanel.ChannelPane.nickColorId("polygenelubricants");
        assertTrue("must return a usable palette code, got: " + id, allProducedIds().contains(id));
    }

    @Test
    public void nickColorIdHandlesAnEmptyNick() {
        assertTrue(allProducedIds().contains(IrcPanel.ChannelPane.nickColorId("")));
    }

    @Test
    public void nickColorIdSpreadsAcrossTheWholePalette() {
        List<String> sampled = Arrays.asList(
                IrcPanel.ChannelPane.nickColorId("alice"),
                IrcPanel.ChannelPane.nickColorId("bob"),
                IrcPanel.ChannelPane.nickColorId("carol"));
        assertEquals("distinct nicks should not all collide", 3, new HashSet<>(sampled).size());
    }
}

package com.irc;

import org.junit.Test;

import java.util.regex.Matcher;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * The URL pattern behind both link surfaces - the side panel (IrcPanel) and the game chatbox
 * (IrcPlugin) share this one Pattern, so a gap in it breaks clickable links in both at once.
 *
 * The failure mode that matters is truncation, not rejection: a character missing from the trailing
 * class does not stop the URL matching, it just ends the match early. A wiki search link would still
 * light up as a link and still be clickable - it would simply go somewhere else. So these tests
 * assert the WHOLE url is captured, never merely that something matched.
 */
public class IrcLinkPatternTest {

    /** The full text the pattern claims, or null when it claims nothing. */
    private static String firstMatch(String text) {
        Matcher matcher = IrcPanel.VALID_LINK.matcher(text);
        return matcher.find() ? matcher.group() : null;
    }

    /** The reported case: the wiki encodes search spaces as '+'. */
    @Test
    public void keepsPlusInAQueryString() {
        String url = "https://oldschool.runescape.wiki/w/Special:Search?search=ocean+encounters";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsSeveralPluses() {
        String url = "https://oldschool.runescape.wiki/w/Special:Search?search=a+b+c+d";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsPlusInAPathSegment() {
        String url = "https://example.com/a+b/c+d";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsPlusAlongsideOtherQuerySyntax() {
        String url = "https://example.com/s?q=ocean+encounters&lang=en-gb&page=2";
        assertEquals(url, firstMatch(url));
    }

    /** A link in the middle of a sentence stops at the space, not before it. */
    @Test
    public void stopsAtWhitespaceNotAtThePlus() {
        String url = "https://oldschool.runescape.wiki/w/Special:Search?search=ocean+encounters";
        assertEquals(url, firstMatch("look at " + url + " for details"));
    }

    // --- fragments ---

    /** Wiki section links are the common case: everything after '#' used to be dropped. */
    @Test
    public void keepsAFragment() {
        String url = "https://oldschool.runescape.wiki/w/Ocean#Locations";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsAFragmentAlongsideAQueryAndPluses() {
        String url = "https://oldschool.runescape.wiki/w/Special:Search?search=ocean+encounters#results";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void keepsAFragmentContainingUnderscoresAndDashes() {
        String url = "https://example.com/page#some_section-two";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void stopsAtWhitespaceAfterAFragment() {
        String url = "https://oldschool.runescape.wiki/w/Ocean#Locations";
        assertEquals(url, firstMatch("see " + url + " for the table"));
    }

    /** A channel name is not a link, and must not become one. */
    @Test
    public void doesNotTreatAHashAsALinkByItself() {
        assertNull(firstMatch("#help"));
        assertNull(firstMatch("join #osrs please"));
        assertEquals("https://example.com/x", firstMatch("#chan https://example.com/x"));
    }

    // --- regressions: everything that worked before must still work ---

    @Test
    public void stillMatchesAPlainUrl() {
        assertEquals("https://example.com", firstMatch("https://example.com"));
        assertEquals("http://example.com/path", firstMatch("http://example.com/path"));
    }

    @Test
    public void stillMatchesTheExistingPunctuationSet() {
        String url = "https://example.com/a-b_c/d.e?f=g&h=i%20j,k;l:m";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void stillMatchesASubdomainedHost() {
        String url = "https://oldschool.runescape.wiki/w/Ocean";
        assertEquals(url, firstMatch(url));
    }

    @Test
    public void stillIgnoresNonUrlText() {
        assertNull(firstMatch("no link here"));
        assertNull(firstMatch("not a url: example"));
    }

    /**
     * A bare '+' must not become a link on its own, and must not extend a match backwards - the
     * plus is only ever valid in the trailing portion, after a host.
     */
    @Test
    public void doesNotTreatAPlusAsALinkByItself() {
        assertNull(firstMatch("1+1=2"));
        assertEquals("https://example.com/x", firstMatch("a+b https://example.com/x"));
    }
}

package com.irc;

import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The server's mode vocabulary, learned from RPL_ISUPPORT (numeric 005).
 *
 * PREFIX=(qaohv)~&@%+ maps membership mode letters to display prefixes positionally, and the
 * position is also the rank (0 = most privileged). CHANMODES=A,B,C,D says which mode letters
 * consume a parameter: A and B always, C only when adding, D never. Membership modes are absent
 * from CHANMODES and always consume one. Knowing this is what keeps "MODE #c +mo bob" from
 * opping the wrong user.
 */
public class ModeSpecTest {

    @Test
    public void defaultsRecognizeTheClassicFivePrefixes() {
        ModeSpec spec = ModeSpec.defaults();
        assertEquals('~', spec.prefixFor('q'));
        assertEquals('&', spec.prefixFor('a'));
        assertEquals('@', spec.prefixFor('o'));
        assertEquals('%', spec.prefixFor('h'));
        assertEquals('+', spec.prefixFor('v'));
    }

    @Test
    public void defaultsRankOwnerAboveVoice() {
        ModeSpec spec = ModeSpec.defaults();
        assertTrue(spec.rankOf('q') < spec.rankOf('o'));
        assertTrue(spec.rankOf('o') < spec.rankOf('v'));
    }

    @Test
    public void unknownModeLetterHasLowestRank() {
        assertEquals(Integer.MAX_VALUE, ModeSpec.defaults().rankOf('Z'));
    }

    @Test
    public void prefixCharMapsBackToItsModeLetter() {
        ModeSpec spec = ModeSpec.defaults();
        assertEquals(Character.valueOf('o'), spec.modeForPrefix('@'));
        assertNull(spec.modeForPrefix('x'));
    }

    @Test
    public void isupportReplacesThePrefixTable() {
        ModeSpec spec = ModeSpec.defaults();
        spec.applyIsupport(Collections.singletonList("PREFIX=(ov)@+"));
        assertEquals(0, spec.rankOf('o'));
        assertFalse("halfop is gone once the server says it has none", spec.isPrefixMode('h'));
    }

    @Test
    public void isupportSkipsTokensThatAreNotKeyValuePairs() {
        ModeSpec spec = ModeSpec.defaults();
        // A real 005 line: leading nick, then tokens, then a trailing description.
        spec.applyIsupport(Arrays.asList("mynick", "PREFIX=(ov)@+", "are supported by this server"));
        assertEquals('@', spec.prefixFor('o'));
        assertFalse(spec.isPrefixMode('h'));
    }

    @Test
    public void unparseablePrefixValueLeavesThePreviousTableIntact() {
        ModeSpec spec = ModeSpec.defaults();
        spec.applyIsupport(Collections.singletonList("PREFIX=garbage"));
        assertEquals('@', spec.prefixFor('o'));
    }

    @Test
    public void prefixModesAlwaysTakeAParameter() {
        ModeSpec spec = ModeSpec.defaults();
        assertTrue(spec.takesParameter('o', true));
        assertTrue(spec.takesParameter('o', false));
        assertTrue(spec.takesParameter('v', false));
    }

    @Test
    public void typeAAndTypeBModesAlwaysTakeAParameter() {
        ModeSpec spec = ModeSpec.defaults();
        assertTrue("b is a list mode", spec.takesParameter('b', true));
        assertTrue(spec.takesParameter('b', false));
        assertTrue("k is a settings mode", spec.takesParameter('k', true));
        assertTrue(spec.takesParameter('k', false));
    }

    @Test
    public void typeCModeTakesAParameterOnlyWhenAdding() {
        ModeSpec spec = ModeSpec.defaults();
        assertTrue(spec.takesParameter('l', true));
        assertFalse(spec.takesParameter('l', false));
    }

    @Test
    public void typeDModeNeverTakesAParameter() {
        ModeSpec spec = ModeSpec.defaults();
        assertFalse(spec.takesParameter('m', true));
        assertFalse(spec.takesParameter('m', false));
    }

    @Test
    public void unknownModeLetterIsAssumedParameterless() {
        // Stated assumption in the spec: type D is the largest class, so it is the safer guess.
        ModeSpec spec = ModeSpec.defaults();
        assertFalse(spec.takesParameter('Z', true));
        assertFalse(spec.takesParameter('Z', false));
    }

    @Test
    public void isupportReplacesTheChanmodesTable() {
        ModeSpec spec = ModeSpec.defaults();
        spec.applyIsupport(Collections.singletonList("CHANMODES=b,k,l,imnpstZ"));
        assertFalse("Z is now a known flag mode", spec.takesParameter('Z', true));
        assertTrue(spec.takesParameter('b', true));
    }

    @Test
    public void malformedChanmodesValueLeavesThePreviousTableIntact() {
        ModeSpec spec = ModeSpec.defaults();
        spec.applyIsupport(Collections.singletonList("CHANMODES=b,k"));
        assertTrue("type C mode l still takes a parameter when adding", spec.takesParameter('l', true));
        assertTrue("type A mode b still takes a parameter", spec.takesParameter('b', true));
    }
}

package com.irc;

import org.junit.Test;

import java.time.Instant;

import static org.junit.Assert.assertEquals;

/** The sender as drawn in chat: the channel prefix goes on the nick, after an action's "* ". */
public class IrcMessageTest {

    private static IrcMessage message(String sender, String prefix) {
        return new IrcMessage("#chan", sender, "hi", IrcMessage.MessageType.CHAT, Instant.now(), prefix);
    }

    @Test
    public void displaySenderIsTheBareNickWithoutAPrefix() {
        assertEquals("bob", message("bob", "").getDisplaySender());
        assertEquals("bob", new IrcMessage("#chan", "bob", "hi", IrcMessage.MessageType.CHAT, Instant.now())
                .getDisplaySender());
    }

    @Test
    public void displaySenderPrefixesTheNick() {
        assertEquals("@bob", message("bob", "@").getDisplaySender());
    }

    @Test
    public void displaySenderKeepsTheActionMarkerFirst() {
        assertEquals("* +bob", message("* bob", "+").getDisplaySender());
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JTabbedPane;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The adapter's LIST plumbing: turning a query into a wire command, and a completed reply into a
 * panel call.
 *
 * A bare /list must send "LIST" with no trailing space - some servers treat "LIST " as a filter
 * argument and return nothing.
 */
public class IrcAdapterListTest {

    /** Captures what the adapter puts on the wire. */
    private static class RecordingClient extends SimpleIrcClient {
        final List<String> sentLines = new ArrayList<>();

        @Override
        public synchronized void sendRawLine(String line) {
            sentLines.add(line);
        }
    }

    private static IrcAdapter adapterWith(RecordingClient client) throws Exception {
        IrcAdapter adapter = new IrcAdapter();
        java.lang.reflect.Field field = IrcAdapter.class.getDeclaredField("client");
        field.setAccessible(true);
        field.set(adapter, client);
        return adapter;
    }

    @Test
    public void bareListSendsNoTrailingSpace() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        adapter.requestChannelList("");

        assertEquals(1, client.sentLines.size());
        assertEquals("LIST", client.sentLines.get(0));
    }

    @Test
    public void nullQueryIsTreatedAsBare() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        adapter.requestChannelList(null);

        assertEquals("LIST", client.sentLines.get(0));
    }

    @Test
    public void argumentsArePassedThroughVerbatim() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        adapter.requestChannelList(">50 *quest*");

        assertEquals("LIST >50 *quest*", client.sentLines.get(0));
    }

    @Test
    public void surroundingWhitespaceIsTrimmed() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        adapter.requestChannelList("   >50   ");

        assertEquals("LIST >50", client.sentLines.get(0));
    }

    @Test
    public void reportsConnectionState() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        assertTrue("a fresh client is not connected", !adapter.isConnected());
    }

    /**
     * Confirmed Task 2 review finding: a LIST run abandoned with no 323, no 263 and no
     * disconnect (the server truncates its reply but the connection survives) used to leave
     * channelListRunActive true, so the next LIST's rows appended onto the stale ones instead of
     * starting fresh. requestChannelList must reset the run before sending.
     *
     * Also covers a Task 6 review finding: the reset must NOT clear channelListSnapshot - the
     * dialog's currently displayed list has to survive until a new run actually completes, or
     * Refresh would blank it mid-flight.
     */
    @Test
    public void secondRequestDoesNotAppendToAnAbandonedRun() throws Exception {
        RecordingClient client = new RecordingClient();
        IrcAdapter adapter = adapterWith(client);

        // A prior LIST completed normally and published a snapshot the dialog is showing now.
        client.processLine(":server 322 me #old 3 :old topic");
        client.processLine(":server 323 me :End of /LIST");
        assertEquals("#old", client.getChannelListSnapshot().get(0).getName());

        // Second run starts but is abandoned - no 323 ever arrives.
        client.processLine(":server 322 me #stale 1 :stale topic");

        adapter.requestChannelList("");

        // Refresh must not blank the dialog mid-flight: the previous snapshot survives the reset,
        // even though the abandoned run's accumulator has just been cleared.
        List<ChannelListEntry> midFlight = client.getChannelListSnapshot();
        assertEquals(1, midFlight.size());
        assertEquals("#old", midFlight.get(0).getName());

        // Third run completes normally and replaces the snapshot; #stale never appears.
        client.processLine(":server 322 me #fresh 2 :fresh topic");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#fresh", entries.get(0).getName());
    }

    private static IrcConfig stubConfig() {
        // IrcConfig only has two abstract methods; everything else is a default.
        return new IrcConfig() {
            @Override
            public String username() {
                return "mynick";
            }

            @Override
            public String password() {
                return "";
            }
        };
    }

    /** Same headless construction approach as IrcPanelChannelListTest. */
    private static IrcPanel headlessPanel() throws Exception {
        IrcPanel panel = new IrcPanel();
        Field configField = IrcPanel.class.getDeclaredField("config");
        configField.setAccessible(true);
        configField.set(panel, stubConfig());
        Field tabbedPaneField = IrcPanel.class.getDeclaredField("tabbedPane");
        tabbedPaneField.setAccessible(true);
        tabbedPaneField.set(panel, new JTabbedPane());
        panel.addChannel("System");
        panel.setFocusedChannel("System");
        return panel;
    }

    /**
     * Confirmed Task 5 review finding: the design invariant is that ANY outcome cancels the
     * pending 30s timeout, but previously only the success path (showChannelList) and the
     * explicit failure path (CHANNEL_LIST_FAILED) did. A disconnect while a timeout was armed
     * still fired a spurious "No channel list response from the server." message 30 seconds
     * later. The DISCONNECT case must cancel it too.
     */
    @Test
    public void disconnectCancelsThePendingChannelListTimeout() throws Exception {
        IrcPanel panel = headlessPanel();

        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> { }, panel, "mynick");
        SimpleIrcClient client = adapter.getClient();
        // Register so disconnect() (which requires `connected`) actually runs.
        client.processLine(":server 001 mynick :Welcome to IRC mynick!runelite@host");

        panel.armChannelListTimeout();

        adapter.disconnect();
        // Drain the EDT so the invokeLater posted by the DISCONNECT case has run before we assert.
        SwingUtilities.invokeAndWait(() -> { });

        Field timeoutField = IrcPanel.class.getDeclaredField("channelListTimeout");
        timeoutField.setAccessible(true);
        Timer timer = (Timer) timeoutField.get(panel);
        assertFalse("disconnect must cancel a pending channel list timeout", timer.isRunning());
    }

    /**
     * Records what the adapter delivers to the panel for a completed or failed LIST, without
     * needing a live Window - showChannelList's real implementation constructs a ChannelListDialog,
     * which throws HeadlessException on a headless machine. Same technique as RecordingClient
     * above: override the one method under test rather than exercise the real implementation.
     */
    private static class RecordingPanel extends IrcPanel {
        volatile List<ChannelListEntry> deliveredEntries;
        volatile String deliveredQuery;
        volatile Boolean deliveredTruncated;
        volatile boolean cancelCalled;

        @Override
        public void showChannelList(List<ChannelListEntry> entries, String query, boolean truncated) {
            deliveredEntries = entries;
            deliveredQuery = query;
            deliveredTruncated = truncated;
        }

        @Override
        public void cancelChannelListTimeout() {
            cancelCalled = true;
        }
    }

    /**
     * Task 6 review finding: the task's headline deliverable - handing a completed LIST reply to
     * the panel - had no coverage. A mutation that disabled the CHANNEL_LIST branch entirely left
     * the full suite green. This pins the whole handoff: the right entries, the query that was in
     * flight, and the truncation flag all have to reach showChannelList.
     */
    @Test
    public void channelListDeliversTheSnapshotToThePanel() throws Exception {
        RecordingPanel panel = new RecordingPanel();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> { }, panel, "mynick");
        SimpleIrcClient client = adapter.getClient();

        adapter.requestChannelList(">50");
        client.processLine(":server 322 me #help 4 :Get help here");
        client.processLine(":server 323 me :End of /LIST");
        // CHANNEL_LIST hands off via invokeLater; drain the EDT before asserting.
        SwingUtilities.invokeAndWait(() -> { });

        assertEquals(1, panel.deliveredEntries.size());
        assertEquals("#help", panel.deliveredEntries.get(0).getName());
        assertEquals(">50", panel.deliveredQuery);
        assertEquals(Boolean.FALSE, panel.deliveredTruncated);
    }

    /**
     * Task 6 review finding, same gap for the failure path: CHANNEL_LIST_FAILED must also cancel
     * the panel's pending timeout, and nothing exercised that call either.
     */
    @Test
    public void channelListFailedCancelsThePendingTimeout() throws Exception {
        RecordingPanel panel = new RecordingPanel();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> { }, panel, "mynick");
        SimpleIrcClient client = adapter.getClient();

        client.processLine(":server 263 me LIST :Server load is too heavy, please try again later");
        SwingUtilities.invokeAndWait(() -> { });

        assertTrue("a failed channel list must cancel the pending timeout", panel.cancelCalled);
    }

    /**
     * Whole-branch review finding: the adapter held the panel forever, so a 323 that arrived while
     * the plugin was shutting down still drove showChannelList and popped the browser for a plugin
     * that no longer exists. shutDown() clears the reference before tearing the panel down.
     */
    @Test
    public void clearPanelStopsALateChannelListFromReachingTheUi() throws Exception {
        RecordingPanel panel = new RecordingPanel();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> { }, panel, "mynick");
        SimpleIrcClient client = adapter.getClient();

        // Sanity: without clearing, this delivery path is live.
        adapter.requestChannelList("");
        client.processLine(":server 322 me #before 4 :still wired up");
        client.processLine(":server 323 me :End of /LIST");
        SwingUtilities.invokeAndWait(() -> { });
        assertEquals(1, panel.deliveredEntries.size());

        adapter.clearPanel();

        adapter.requestChannelList("");
        client.processLine(":server 322 me #after 9 :arrived during shutdown");
        client.processLine(":server 323 me :End of /LIST");
        SwingUtilities.invokeAndWait(() -> { });

        assertEquals("a reply arriving after teardown must not reach the panel",
                "#before", panel.deliveredEntries.get(0).getName());
        assertEquals(1, panel.deliveredEntries.size());
    }

    /** The failure path holds the same reference and must respect the same teardown. */
    @Test
    public void clearPanelStopsALateFailureFromReachingTheUi() throws Exception {
        RecordingPanel panel = new RecordingPanel();
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> { }, panel, "mynick");
        SimpleIrcClient client = adapter.getClient();

        adapter.clearPanel();
        client.processLine(":server 263 me LIST :Server load is too heavy, please try again later");
        SwingUtilities.invokeAndWait(() -> { });

        assertFalse("a 263 arriving after teardown must not touch the panel", panel.cancelCalled);
    }
}

package com.irc;

import org.junit.Before;
import org.junit.Test;

import javax.swing.*;
import java.awt.event.FocusEvent;
import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.*;

public class ChannelNumberKeysTest {
    private final JPanel root = new JPanel();
    private final JTextField input = new JTextField();
    private final JTextField outside = new JTextField();
    private final List<Integer> jumps = new ArrayList<>();
    private ChannelNumberKeys keys;

    @Before
    public void setUp() {
        root.add(input);
        keys = new ChannelNumberKeys(root, jumps::add);
        keys.install();
    }

    @Test
    public void altDigitJumpsAndSwallowsItsTypedCharacter() {
        assertTrue(press(input, KeyEvent.VK_3, KeyEvent.ALT_DOWN_MASK));
        assertTrue(type(input, '3', KeyEvent.ALT_DOWN_MASK));
        assertEquals(Collections.singletonList(3), jumps);

        assertFalse(press(input, KeyEvent.VK_A, 0));
        assertFalse(type(input, 'a', 0));
    }

    @Test
    public void altZeroJumpsToTheTenth() {
        assertTrue(press(input, KeyEvent.VK_0, KeyEvent.ALT_DOWN_MASK));
        assertTrue(type(input, '0', KeyEvent.ALT_DOWN_MASK));
        assertEquals(Collections.singletonList(10), jumps);
    }

    @Test
    public void altJThenTwoDigitsJumpsToThatNumber() {
        assertTrue(press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK));
        assertTrue(type(input, 'j', KeyEvent.ALT_DOWN_MASK));
        assertFalse(press(input, KeyEvent.VK_ALT, 0));
        assertTrue(press(input, KeyEvent.VK_1, 0));
        assertTrue(type(input, '1', 0));
        assertTrue(jumps.isEmpty());
        assertTrue(press(input, KeyEvent.VK_NUMPAD0, 0));
        assertTrue(type(input, '0', 0));
        assertEquals(Collections.singletonList(10), jumps);

        // The jump is over, so digits type normally again.
        assertFalse(press(input, KeyEvent.VK_5, 0));
        assertFalse(type(input, '5', 0));
    }

    @Test
    public void digitsHeldWithAltCountTowardsAPendingJump() {
        press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK);
        press(input, KeyEvent.VK_1, KeyEvent.ALT_DOWN_MASK);
        press(input, KeyEvent.VK_2, KeyEvent.ALT_DOWN_MASK);
        assertEquals(Collections.singletonList(12), jumps);
    }

    @Test
    public void otherKeysCancelAPendingJump() {
        press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK);
        assertTrue(press(input, KeyEvent.VK_ESCAPE, 0));
        assertFalse(press(input, KeyEvent.VK_1, 0));

        press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK);
        press(input, KeyEvent.VK_1, 0);
        assertFalse(press(input, KeyEvent.VK_X, 0));
        assertFalse(type(input, 'x', 0));
        assertFalse(press(input, KeyEvent.VK_2, 0));
        assertTrue(jumps.isEmpty());
    }

    @Test
    public void ignoresKeysOutsideThePanelAndAltGr() {
        assertFalse(press(outside, KeyEvent.VK_1, KeyEvent.ALT_DOWN_MASK));
        assertFalse(press(input, KeyEvent.VK_1, KeyEvent.ALT_DOWN_MASK | KeyEvent.CTRL_DOWN_MASK));
        assertFalse(press(input, KeyEvent.VK_1, KeyEvent.ALT_GRAPH_DOWN_MASK));
        assertTrue(jumps.isEmpty());
    }

    @Test
    public void losingFocusCancelsAPendingJump() {
        press(input, KeyEvent.VK_J, KeyEvent.ALT_DOWN_MASK);
        for (java.awt.event.FocusListener listener : input.getFocusListeners()) {
            listener.focusLost(new FocusEvent(input, FocusEvent.FOCUS_LOST, false, outside));
        }
        assertFalse(press(input, KeyEvent.VK_1, 0));
        assertFalse(press(input, KeyEvent.VK_2, 0));
        assertTrue(jumps.isEmpty());
    }

    @Test
    public void followsComponentsAddedAndRemovedAfterInstall() {
        JPanel tab = new JPanel();
        JTextField later = new JTextField();
        tab.add(later);
        root.add(tab);
        assertTrue(press(later, KeyEvent.VK_2, KeyEvent.ALT_DOWN_MASK));
        assertEquals(Collections.singletonList(2), jumps);

        root.remove(tab);
        assertFalse(press(later, KeyEvent.VK_2, KeyEvent.ALT_DOWN_MASK));
        root.add(tab);
        assertEquals(1, later.getKeyListeners().length);

        keys.uninstall();
        assertFalse(press(input, KeyEvent.VK_3, KeyEvent.ALT_DOWN_MASK));
        assertEquals(Collections.singletonList(2), jumps);
    }

    private boolean press(JComponent source, int code, int mods) {
        return fire(source, new KeyEvent(source, KeyEvent.KEY_PRESSED, 0, mods, code, KeyEvent.CHAR_UNDEFINED));
    }

    private boolean type(JComponent source, char c, int mods) {
        return fire(source, new KeyEvent(source, KeyEvent.KEY_TYPED, 0, mods, KeyEvent.VK_UNDEFINED, c));
    }

    /** Delivers the event to the component's listeners, as Swing would; true when one consumed it. */
    private static boolean fire(JComponent source, KeyEvent e) {
        for (KeyListener listener : source.getKeyListeners()) {
            if (e.getID() == KeyEvent.KEY_PRESSED) listener.keyPressed(e);
            else if (e.getID() == KeyEvent.KEY_TYPED) listener.keyTyped(e);
        }
        return e.isConsumed();
    }
}

