package com.irc;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * Readline-style input history for the side-panel input box. Up walks back through recently
 * sent lines (stashing the unsent draft on the first press), Down walks forward and restores
 * the draft past the newest entry. Capacity-bounded; consecutive duplicates are collapsed.
 */
public class InputHistoryTest {

    @Test
    public void emptyHistoryReturnsNull() {
        InputHistory history = new InputHistory(20);
        assertNull(history.previous(""));
        assertNull(history.next());
    }

    @Test
    public void upFromLiveReturnsNewestEntry() {
        InputHistory history = new InputHistory(20);
        history.add("first");
        history.add("second");
        assertEquals("second", history.previous("draft"));
    }

    @Test
    public void repeatedUpWalksBackAndClampsAtOldest() {
        InputHistory history = new InputHistory(20);
        history.add("a");
        history.add("b");
        history.add("c");
        assertEquals("c", history.previous(""));
        assertEquals("b", history.previous(""));
        assertEquals("a", history.previous(""));
        assertEquals("a", history.previous("")); // clamped at oldest
    }

    @Test
    public void downWalksForwardAndRestoresStashedDraft() {
        InputHistory history = new InputHistory(20);
        history.add("a");
        history.add("b");
        assertEquals("b", history.previous("my draft"));
        assertEquals("a", history.previous("my draft"));
        assertEquals("b", history.next());
        assertEquals("my draft", history.next()); // past newest -> stashed draft restored
        assertNull(history.next());                // now live again
    }

    @Test
    public void downWithoutBrowsingReturnsNull() {
        InputHistory history = new InputHistory(20);
        history.add("a");
        assertNull(history.next());
    }

    @Test
    public void capacityDropsOldest() {
        InputHistory history = new InputHistory(2);
        history.add("a");
        history.add("b");
        history.add("c"); // "a" evicted
        assertEquals("c", history.previous(""));
        assertEquals("b", history.previous(""));
        assertEquals("b", history.previous("")); // "a" gone -> clamp at "b"
    }

    @Test
    public void skipsConsecutiveDuplicate() {
        InputHistory history = new InputHistory(20);
        history.add("same");
        history.add("same"); // collapsed
        assertEquals("same", history.previous(""));
        assertEquals("same", history.previous("")); // only one entry
    }

    @Test
    public void keepsNonConsecutiveDuplicate() {
        InputHistory history = new InputHistory(20);
        history.add("a");
        history.add("b");
        history.add("a"); // not consecutive -> kept
        assertEquals("a", history.previous(""));
        assertEquals("b", history.previous(""));
        assertEquals("a", history.previous(""));
    }

    @Test
    public void addResetsBrowsing() {
        InputHistory history = new InputHistory(20);
        history.add("a");
        history.add("b");
        assertEquals("b", history.previous("draft"));
        history.add("c");                       // sending resets browse state
        assertNull(history.next());             // no longer browsing
        assertEquals("c", history.previous("")); // fresh browse from newest
    }

    @Test
    public void ignoresBlankAndNullLines() {
        InputHistory history = new InputHistory(20);
        history.add("");
        history.add(null);
        assertNull(history.previous(""));
    }
}

package com.irc;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Guards the contract that IrcPlugin relies on for /umode: the nick reported by the
 * adapter must follow the network's confirmed nick, i.e. it is driven by the raw NICK
 * event rather than an optimistic local guess. Previously IrcPlugin kept its own copy
 * of the nick that was set once at connect and never updated, so /nick desynced it from
 * the network.
 */
public class IrcAdapterNickTest {

    private static IrcConfig stubConfig() {
        // IrcConfig only has two abstract methods; everything else is a default.
        return new IrcConfig() {
            @Override
            public String username() {
                return "mynick";
            }

            @Override
            public String password() {
                return "";
            }
        };
    }

    @Test
    public void getNickFollowsRawNickEvent() {
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> {}, null, "mynick");

        assertEquals("mynick", adapter.getNick());

        // The server echoes our own nick change back to us. The adapter must adopt the
        // new nick from this raw NICK line, not from any optimistic local update.
        adapter.getClient().processLine(":mynick!runelite@host NICK newnick");

        assertEquals("newnick", adapter.getNick());
    }

    @Test
    public void getNickIgnoresOtherUsersNickChanges() {
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> {}, null, "mynick");

        // Someone else changing their nick must not move our own nick.
        adapter.getClient().processLine(":someoneelse!u@host NICK othernew");

        assertEquals("mynick", adapter.getNick());
    }

    @Test
    public void nickTakenDuringRegistrationAdoptsServerAssignedNick() {
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> {}, null, "mynick");
        SimpleIrcClient client = adapter.getClient();

        // Server rejects our requested nick (433 ERR_NICKNAMEINUSE) ...
        client.processLine(":server 433 * mynick :Nickname is already in use");
        // ... we retry and the server welcomes us as mynick_ (001 RPL_WELCOME).
        client.processLine(":server 001 mynick_ :Welcome to IRC mynick_!runelite@host");

        assertEquals("mynick_", client.getNick());
        assertEquals("mynick_", adapter.getNick());
    }

    @Test
    public void welcomeNumericIsAuthoritativeForNick() {
        IrcAdapter adapter = new IrcAdapter();
        adapter.initialize(stubConfig(), message -> {}, null, "mynick");
        SimpleIrcClient client = adapter.getClient();

        // The server may register us under a nick that differs from what we asked for;
        // RPL_WELCOME is the network's authoritative statement of our nick.
        client.processLine(":server 001 ServerChosen :Welcome to IRC ServerChosen!runelite@host");

        assertEquals("ServerChosen", client.getNick());
        assertEquals("ServerChosen", adapter.getNick());
    }
}

package com.irc;

import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.util.Text;
import org.junit.Test;

import java.awt.Color;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The in-game chat box colour is opt-in. Off, messages keep RuneLite's own chat colours (the
 * NORMAL colour type, which the Chat Colour plugin controls); on, they get the chosen colour.
 */
public class IrcPluginChatboxColorTest {

    private static IrcConfig config(boolean enabled, Color color) {
        return config(enabled, color, false);
    }

    private static IrcConfig config(boolean enabled, Color color, boolean ircColors) {
        return new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
            @Override public boolean inGameTextColorEnabled() { return enabled; }
            @Override public Color inGameTextColor() { return color; }
            @Override public boolean ircColorsInGame() { return ircColors; }
        };
    }

    private static final IrcConfig IRC_COLORS = config(false, null, true);

    private static ChatMessageBuilder normal() {
        return new ChatMessageBuilder().append(ChatColorType.NORMAL);
    }

    @Test
    public void offByDefault() {
        IrcConfig defaults = new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
        };
        assertFalse(defaults.inGameTextColorEnabled());
    }

    @Test
    public void disabledKeepsRuneLiteChatColours() {
        String expected = new ChatMessageBuilder().append(ChatColorType.NORMAL).append("hello").build();
        assertEquals(expected, IrcPlugin.chatboxMessage("hello", config(false, Color.RED)));
    }

    @Test
    public void enabledUsesTheChosenColour() {
        assertEquals("<col=123456>hello</col>", IrcPlugin.chatboxMessage("hello", config(true, new Color(0x12, 0x34, 0x56))));
    }

    @Test
    public void enabledWithNoColourFallsBackToRuneLiteChatColours() {
        String expected = new ChatMessageBuilder().append(ChatColorType.NORMAL).append("hello").build();
        assertEquals(expected, IrcPlugin.chatboxMessage("hello", config(true, null)));
    }

    @Test
    public void ircColoursOnByDefault() {
        IrcConfig defaults = new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
        };
        assertTrue(defaults.ircColorsInGame());
    }

    @Test
    public void ircColoursOffStripsTheCodes() {
        assertEquals(normal().append("red plain").build(),
                IrcPlugin.chatboxMessage("\u00034red\u000F plain", config(false, null)));
    }

    @Test
    public void ircColourBecomesAColTag() {
        assertEquals(new ChatMessageBuilder().append(new Color(0xFF0000), "red").build(),
                IrcPlugin.chatboxMessage("\u00034red", IRC_COLORS));
    }

    @Test
    public void resetReturnsToTheBaseColour() {
        String expected = new ChatMessageBuilder().append(new Color(0xFF0000), "red")
                .append(ChatColorType.NORMAL).append(" plain").build();
        assertEquals(expected, IrcPlugin.chatboxMessage("\u00034red\u000F plain", IRC_COLORS));
    }

    @Test
    public void bareColourCodeAlsoResets() {
        String expected = normal().append("a ").append(new Color(0x00FF00), "green")
                .append(ChatColorType.NORMAL).append(" b").build();
        assertEquals(expected, IrcPlugin.chatboxMessage("a \u00039green\u0003 b", IRC_COLORS));
    }

    @Test
    public void backgroundIsDroppedBecauseTheChatBoxCannotDrawIt() {
        assertEquals(new ChatMessageBuilder().append(new Color(0xFF0000), "hi").build(),
                IrcPlugin.chatboxMessage("\u00034,8hi", IRC_COLORS));
    }

    @Test
    public void namedPaletteColoursBecomeHex() {
        // The panel palette names 0 and 1 "white" and "black"; the chat box needs hex.
        assertEquals(new ChatMessageBuilder().append(Color.WHITE, "w").append(Color.BLACK, "b").build(),
                IrcPlugin.chatboxMessage("\u00030w\u00031b", IRC_COLORS));
    }

    @Test
    public void extendedPaletteColour() {
        assertEquals(new ChatMessageBuilder().append(new Color(0x470000), "x").build(),
                IrcPlugin.chatboxMessage("\u000316x", IRC_COLORS));
    }

    @Test
    public void defaultColour99IsTheBaseColour() {
        assertEquals(normal().append("x").build(), IrcPlugin.chatboxMessage("\u000399x", IRC_COLORS));
    }

    @Test
    public void otherFormattingIsStripped() {
        assertEquals(normal().append("bold italic under").build(),
                IrcPlugin.chatboxMessage("\u0002bold\u0002 \u001Ditalic\u001D \u001Funder\u001F", IRC_COLORS));
    }

    @Test
    public void baseColourIsTheCustomInGameColourWhenSet() {
        Color custom = new Color(0x123456);
        String expected = new ChatMessageBuilder().append(new Color(0xFF0000), "red")
                .append(custom, " plain").build();
        assertEquals(expected, IrcPlugin.chatboxMessage("\u00034red\u000F plain", config(true, custom, true)));
    }

    /** Game tags from IRC text must be escaped on every path, or anyone can draw a mod crown in chat. */
    @Test
    public void tagsInAnIrcColouredRunAreEscaped() {
        String built = IrcPlugin.chatboxMessage("\u00034<img=1>Jagex <col=00ff00>x", IRC_COLORS);
        assertFalse(built, built.contains("<img=1>"));
        assertFalse(built, built.contains("<col=00ff00>"));
    }

    @Test
    public void tagsWithACustomInGameColourAreEscaped() {
        String built = IrcPlugin.chatboxMessage("<img=1>Jagex", config(true, Color.RED));
        assertFalse(built, built.contains("<img=1>"));
    }

    @Test
    public void escapedTextMatchesTheUncolouredPath() {
        String escaped = Text.escapeJagex("use <b> tags");
        assertEquals(new ChatMessageBuilder().append(new Color(0xFF0000), escaped).build(),
                IrcPlugin.chatboxMessage("\u00034use <b> tags", IRC_COLORS));
    }
}

package com.irc;

import org.junit.Before;
import org.junit.Test;

import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class TabCompleterTest {

    private static final List<String> NICKS = Arrays.asList("bob", "Bobby", "alice");
    private static final List<String> CHANNELS = Arrays.asList("#runescape", "#rs", "#help");

    private TabCompleter completer;

    @Before
    public void setUp() {
        completer = new TabCompleter();
    }

    private String complete(String text, int caret, boolean forward) {
        TabCompleter.Result result = completer.complete(text, caret, NICKS, CHANNELS, forward);
        return result == null ? null : result.text + "|" + result.caret;
    }

    private String complete(String text) {
        return complete(text, text.length(), true);
    }

    @Test
    public void nickAtLineStartGetsAColon() {
        assertEquals("alice: |7", complete("al"));
    }

    @Test
    public void nickMidLineGetsASpace() {
        assertEquals("hi alice |9", complete("hi al"));
    }

    @Test
    public void matchingIsCaseInsensitiveAndKeepsTheNicksCasing() {
        assertEquals("Bobby: |7", complete("BOBB"));
    }

    @Test
    public void channelsCompleteFromHash() {
        assertEquals("join #help |11", complete("join #he"));
    }

    @Test
    public void channelAtLineStartGetsNoColon() {
        assertEquals("#help |6", complete("#he"));
    }

    @Test
    public void repeatedTabCyclesThroughMatchesAndWraps() {
        assertEquals("bob: |5", complete("bo"));
        assertEquals("Bobby: |7", complete("bob: ", 5, true));
        assertEquals("bob: |5", complete("Bobby: ", 7, true));
    }

    @Test
    public void shiftTabCyclesBackwards() {
        assertEquals("Bobby: |7", complete("bo", 2, false));
        assertEquals("bob: |5", complete("Bobby: ", 7, false));
    }

    @Test
    public void anEditStartsAFreshCompletion() {
        assertEquals("bob: |5", complete("bo"));
        assertEquals("bob: alice |11", complete("bob: al"));
    }

    @Test
    public void completesTheWordBeforeTheCaretAndKeepsTheRest() {
        assertEquals("alice: how are you|6", complete("al how are you", 2, true));
        assertEquals("hi alice how are you|8", complete("hi al how are you", 5, true));
    }

    @Test
    public void nothingToCompleteLeavesTheInputAlone() {
        assertNull(complete(""));
        assertNull(complete("hello "));
        assertNull(complete("zed"));
    }

    /** The input box is shared, so Tab after switching buffers must complete from the new buffer's nicks. */
    @Test
    public void cyclingAfterABufferSwitchUsesTheNewBuffersNicks() {
        assertEquals("bob: |5", complete("bo"));
        TabCompleter.Result result = completer.complete("bob: ", 5, Arrays.asList("boris", "alice"), CHANNELS, true);
        assertEquals("boris: |7", result.text + "|" + result.caret);
    }

    @Test
    public void cyclingStopsWhenNoMatchesAreLeft() {
        assertEquals("bob: |5", complete("bo"));
        assertNull(completer.complete("bob: ", 5, Arrays.asList("alice"), CHANNELS, true));
    }

    /** Someone unrelated joining mid-cycle must not restart the cycle. */
    @Test
    public void anUnrelatedRosterChangeKeepsCycling() {
        assertEquals("bob: |5", complete("bo"));
        TabCompleter.Result result = completer.complete("bob: ", 5, Arrays.asList("bob", "Bobby", "alice", "zed"), CHANNELS, true);
        assertEquals("Bobby: |7", result.text + "|" + result.caret);
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JTable;
import java.awt.GraphicsEnvironment;
import java.lang.reflect.Field;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.junit.Assume.assumeFalse;

/**
 * The Topic column's tooltip.
 *
 * The design requires the topic be "rendered with formatting codes stripped, full text in a
 * tooltip since the column truncates" - the column is 440px wide and most real topics are longer,
 * so without the tooltip the tail of a topic is simply unreadable. The column shipped with the
 * default renderer and no tooltip at all.
 *
 * The dialog itself cannot be built headless (it is a Window), but the renderer is an ordinary
 * JLabel subclass, so the tooltip is asserted directly without one.
 */
public class ChannelListDialogTopicRendererTest {

    private static String tooltipFor(Object value) {
        ChannelListDialog.TopicRenderer renderer = new ChannelListDialog.TopicRenderer();
        JTable table = new JTable(new ChannelListTableModel());
        renderer.getTableCellRendererComponent(table, value, false, false, 0, 2);
        return renderer.getToolTipText();
    }

    @Test
    public void tooltipCarriesTheWholeTopic() {
        String longTopic = "Ask about quest help here, and read the pinned guide before posting - "
                + "we answer faster when you say which quest and which step you are stuck on.";
        assertEquals(longTopic, tooltipFor(longTopic));
    }

    @Test
    public void shortTopicsGetATooltipToo() {
        assertEquals("General chatter", tooltipFor("General chatter"));
    }

    /** An empty tooltip still pops an empty box open on hover, so an empty topic gets none. */
    @Test
    public void emptyTopicHasNoTooltip() {
        assertNull(tooltipFor(""));
    }

    @Test
    public void nullValueHasNoTooltip() {
        assertNull(tooltipFor(null));
    }

    /** A row reused for a different channel must not keep the previous row's tooltip. */
    @Test
    public void tooltipIsReplacedWhenTheRendererIsReused() {
        ChannelListDialog.TopicRenderer renderer = new ChannelListDialog.TopicRenderer();
        JTable table = new JTable(new ChannelListTableModel());

        renderer.getTableCellRendererComponent(table, "first topic", false, false, 0, 2);
        renderer.getTableCellRendererComponent(table, "second topic", false, false, 1, 2);
        assertEquals("second topic", renderer.getToolTipText());

        renderer.getTableCellRendererComponent(table, "", false, false, 2, 2);
        assertNull("an empty topic must clear the stale tooltip", renderer.getToolTipText());
    }

    /**
     * A correct renderer nobody installed is worth nothing, and the tests above would not notice.
     *
     * The dialog is a Window, so this can only run where one can be created; JUnit reports it as
     * skipped rather than passed elsewhere, which is the honest outcome - a silent early return
     * would look like coverage that is not there.
     */
    @Test
    public void theTopicColumnIsWiredToTheRenderer() throws Exception {
        assumeFalse("needs a display to construct the dialog", GraphicsEnvironment.isHeadless());

        ChannelListDialog dialog = new ChannelListDialog(null, null, null);
        try {
            Field tableField = ChannelListDialog.class.getDeclaredField("table");
            tableField.setAccessible(true);
            JTable table = (JTable) tableField.get(dialog);

            assertTrue("the Topic column must use the tooltip renderer",
                    table.getColumnModel().getColumn(2).getCellRenderer()
                            instanceof ChannelListDialog.TopicRenderer);
            assertNull("the other columns keep the default renderer",
                    table.getColumnModel().getColumn(0).getCellRenderer());
        } finally {
            dialog.dispose();
        }
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JTabbedPane;
import javax.swing.Timer;
import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The panel's side of the channel browser: firing the request and policing the response window.
 *
 * A LIST that never terminates would otherwise leave the user staring at nothing, so the request
 * arms a timer that must be cancelled by any outcome - success or an explicit failure. A timer
 * left running fires a "no response" message on top of a list that did arrive.
 *
 * The dialog itself is not built here: constructing a Window throws HeadlessException on a
 * headless machine, so showChannelList's dialog handling is covered by the manual smoke test.
 */
public class IrcPanelChannelListTest {

    private static IrcPanel headlessPanel() throws Exception {
        IrcPanel panel = new IrcPanel();
        set(panel, "config", stubConfig());
        set(panel, "tabbedPane", new JTabbedPane());
        panel.addChannel("System");
        panel.setFocusedChannel("System");
        return panel;
    }

    private static void set(Object target, String field, Object value) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        f.set(target, value);
    }

    private static Object get(Object target, String field) throws Exception {
        Field f = IrcPanel.class.getDeclaredField(field);
        f.setAccessible(true);
        return f.get(target);
    }

    /**
     * IrcConfig is an interface whose methods are nearly all defaults, so only the two abstract
     * ones need overriding. Same shape as the stub in IrcPanelNickListTest.
     */
    private static IrcConfig stubConfig() {
        return new IrcConfig() {
            @Override
            public String username() {
                return "tester";
            }

            @Override
            public String password() {
                return "";
            }
        };
    }

    @Test
    public void requestChannelListForwardsTheQuery() throws Exception {
        IrcPanel panel = headlessPanel();
        List<String> requested = new ArrayList<>();
        panel.init(null, null, null, null, requested::add, null);

        panel.requestChannelList(">50");

        assertEquals(1, requested.size());
        assertEquals(">50", requested.get(0));
    }

    @Test
    public void requestChannelListIsSafeWithoutACallback() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.requestChannelList("");  // must not throw
    }

    @Test
    public void requestChannelListCoalescesNullToEmptyString() throws Exception {
        IrcPanel panel = headlessPanel();
        List<String> requested = new ArrayList<>();
        panel.init(null, null, null, null, requested::add, null);

        panel.requestChannelList(null);

        assertEquals(1, requested.size());
        assertEquals("", requested.get(0));
    }

    @Test
    public void armingStartsATimer() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();

        Timer timer = (Timer) get(panel, "channelListTimeout");
        assertNotNull(timer);
        assertTrue(timer.isRunning());
        assertFalse("a one-shot timeout must not repeat", timer.isRepeats());

        panel.cancelChannelListTimeout();
    }

    @Test
    public void cancellingStopsTheTimer() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();
        panel.cancelChannelListTimeout();

        Timer timer = (Timer) get(panel, "channelListTimeout");
        assertFalse(timer.isRunning());
    }

    /** Re-arming must not leave the previous timer running behind the new one. */
    @Test
    public void rearmingReplacesTheRunningTimer() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();
        Timer first = (Timer) get(panel, "channelListTimeout");

        panel.armChannelListTimeout();
        Timer second = (Timer) get(panel, "channelListTimeout");

        assertFalse("the superseded timer must be stopped", first.isRunning());
        assertTrue(second.isRunning());
        panel.cancelChannelListTimeout();
    }

    @Test
    public void cancellingWithoutArmingIsSafe() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.cancelChannelListTimeout();  // must not throw
    }

    /** Fires the armed timer's action now rather than waiting 30 real seconds. */
    private static void fireTimeout(IrcPanel panel) throws Exception {
        Timer timer = (Timer) get(panel, "channelListTimeout");
        for (java.awt.event.ActionListener listener : timer.getActionListeners()) {
            listener.actionPerformed(null);
        }
        panel.cancelChannelListTimeout();
        // Twice: addMessage queues the document edit on a second invokeLater hop, so one drain
        // would leave the "must NOT contain" assertion below passing vacuously.
        javax.swing.SwingUtilities.invokeAndWait(() -> { });
        javax.swing.SwingUtilities.invokeAndWait(() -> { });
    }

    /**
     * Whole-branch review finding: the timeout was the one channel-list message that never reached
     * the game chatbox. "Requesting channel list..." and a 263 refusal both go through the
     * plugin's processMessage, which feeds the chatbox and the panel; the timeout called
     * addMessage directly, so a user with the sidebar collapsed saw the request announced in game
     * chat and never learned it had failed.
     *
     * The fix is that the panel reports the expiry to the plugin instead of writing it itself, so
     * what is pinned here is: the callback fires, and nothing lands in the System pane locally.
     * The second assertion is the one that fails if anyone reinstates the direct write.
     */
    @Test
    public void timeoutReportsThroughTheCallbackRatherThanWritingToThePanel() throws Exception {
        IrcPanel panel = headlessPanel();
        List<String> reported = new ArrayList<>();
        panel.init(null, null, null, null, null, () -> reported.add("timeout"));

        panel.armChannelListTimeout();
        fireTimeout(panel);

        assertEquals("the expiry must be reported exactly once", 1, reported.size());

        Map<String, IrcPanel.ChannelPane> panes = panel.getChannelPanes();
        String text = panes.get("System").getText();
        assertFalse("the panel must not also write the notice itself - the plugin owns emitting it,"
                        + " so a direct write would double up in the panel and still skip the chatbox: "
                        + text,
                text.toLowerCase().contains("no channel list response"));
    }

    /** A panel that was never wired to a plugin must not blow up when its timeout expires. */
    @Test
    public void timeoutWithoutACallbackIsSafe() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();
        fireTimeout(panel);  // must not throw
    }

    /**
     * Whole-branch review finding: the browser survived plugin shutdown as a zombie window.
     * shutDown() removed the nav button, nulled the panel and disconnected, but the JDialog is a
     * top-level Window that nothing disposed - it stayed on screen with Refresh and Join both
     * returning silently, and re-enabling the plugin leaked it (IrcPanel is not a singleton, so
     * the injector hands back a fresh panel and a fresh dialog) along with its sorter and up to
     * 20,000 entries.
     *
     * The dialog half needs a real Window, so it is asserted only where one can be created; the
     * timer half and the field-nulling are asserted unconditionally.
     */
    @Test
    public void shutdownStopsTheTimeoutAndReleasesTheDialog() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();
        Timer armed = (Timer) get(panel, "channelListTimeout");

        ChannelListDialog dialog = null;
        try {
            dialog = new ChannelListDialog(null, null, null);
            set(panel, "channelListDialog", dialog);
        } catch (java.awt.HeadlessException noDisplayAvailable) {
            // Window construction needs a display; the rest of the teardown still has to hold.
        }

        panel.shutdown();

        assertFalse("shutdown must stop a pending timeout", armed.isRunning());
        assertNull("the timer field must be released", get(panel, "channelListTimeout"));
        assertNull("the dialog field must be nulled so a later showChannelList rebuilds cleanly",
                get(panel, "channelListDialog"));
        if (dialog != null) {
            assertFalse("the dialog's native window must be disposed, not merely dereferenced",
                    dialog.isDisplayable());
        }
    }

    /** Teardown runs on plugin shutdown regardless of whether /list was ever used. */
    @Test
    public void shutdownIsSafeWithNothingArmedOrShown() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.shutdown();
        panel.shutdown();  // idempotent - must not throw
        assertNull(get(panel, "channelListDialog"));
    }

    /**
     * A LIST reply that does arrive must disarm the timeout, or the "no response" notice fires on
     * top of a list the user is already looking at. {@code cancelChannelListTimeout()} is the
     * first statement in {@code showChannelList}, before any {@link java.awt.Window} is
     * constructed, so this holds even though the dialog itself can't be built headless: the
     * {@link java.awt.HeadlessException} it throws is caught here and the timer state is asserted
     * regardless of whether that exception was thrown.
     */
    @Test
    public void showingTheChannelListCancelsThePendingTimeout() throws Exception {
        IrcPanel panel = headlessPanel();
        panel.armChannelListTimeout();

        try {
            panel.showChannelList(new ArrayList<>(), "", false);
        } catch (java.awt.HeadlessException expectedOnAHeadlessMachine) {
            // Dialog construction needs a real Window; the cancel already ran before this point.
        }

        Timer timer = (Timer) get(panel, "channelListTimeout");
        assertFalse("showChannelList must cancel the pending timeout", timer.isRunning());
    }
}

package com.irc;

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The protocol layer feeding ChannelUserList and announcing changes.
 *
 * Every membership event must both update the roster and fire USERS_CHANGED for each channel it
 * touched, so the panel redraws exactly the affected buffers. Display events (NAMES, CHANNEL_MODE)
 * must keep firing unchanged so /names and mode messages still print to chat.
 */
public class SimpleIrcClientUsersTest {

    /** Feeds raw lines without a socket and records what came back out. */
    private static class RecordingClient extends SimpleIrcClient {
        final List<String> sentLines = new ArrayList<>();
        final List<IrcEvent> events = new ArrayList<>();

        RecordingClient() {
            addEventListener(events::add);
        }

        @Override
        public synchronized void sendRawLine(String line) {
            sentLines.add(line);
        }

        List<String> usersChangedChannels() {
            List<String> channels = new ArrayList<>();
            for (IrcEvent event : events) {
                if (event.getType() == IrcEvent.Type.USERS_CHANGED) {
                    channels.add(event.getTarget());
                }
            }
            return channels;
        }

        List<String> nicksIn(String channel) {
            List<String> nicks = new ArrayList<>();
            for (ChannelUserList.Entry entry : getChannelUsers(channel)) {
                nicks.add(entry.getPrefix() + entry.getNick());
            }
            return nicks;
        }

        boolean firedType(IrcEvent.Type type) {
            return events.stream().anyMatch(e -> e.getType() == type);
        }
    }

    /** A 353 followed by its 366 terminator, as the server sends them. */
    private static void loadNames(RecordingClient client, String channel, String names) {
        client.processLine(":server 353 me = " + channel + " :" + names);
        client.processLine(":server 366 me " + channel + " :End of /NAMES list");
    }

    @Test
    public void namesReplyPopulatesTheRosterWithPrefixesIntact() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob +dave erin");
        assertEquals(java.util.Arrays.asList("@bob", "+dave", "erin"), client.nicksIn("#chan"));
    }

    @Test
    public void namesReplyStillFiresTheDisplayEventSoSlashNamesKeepsPrinting() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 353 me = #chan :@bob +dave");
        assertTrue(client.firedType(SimpleIrcClient.IrcEvent.Type.NAMES));
    }

    @Test
    public void endOfNamesAnnouncesTheChannel() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob");
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
    }

    @Test
    public void isupportRetunesThePrefixTable() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 005 me PREFIX=(ov)@+ CHANMODES=b,k,l,imnpst :are supported");
        loadNames(client, "#chan", "@bob %carol");
        // With PREFIX=(ov)@+ the server has no halfop, so "%carol" is a nick starting with '%'.
        assertEquals(java.util.Arrays.asList("@bob", "%carol"), client.nicksIn("#chan"));
    }

    @Test
    public void joinAddsTheUserAndAnnounces() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob");
        client.events.clear();

        client.processLine(":erin!user@host JOIN #chan");

        assertEquals(java.util.Arrays.asList("@bob", "erin"), client.nicksIn("#chan"));
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
    }

    @Test
    public void partRemovesTheUserAndAnnounces() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob erin");
        client.events.clear();

        client.processLine(":erin!user@host PART #chan :bye");

        assertEquals(java.util.Collections.singletonList("@bob"), client.nicksIn("#chan"));
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
    }

    @Test
    public void quitAnnouncesEveryChannelTheUserWasIn() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#one", "erin bob");
        loadNames(client, "#two", "erin");
        loadNames(client, "#three", "bob");
        client.events.clear();

        client.processLine(":erin!user@host QUIT :gone");

        List<String> announced = client.usersChangedChannels();
        assertEquals(2, announced.size());
        assertTrue(announced.contains("#one"));
        assertTrue(announced.contains("#two"));
        assertFalse("#three had no erin", announced.contains("#three"));
    }

    @Test
    public void quitStillCarriesTheAffectedChannelsOnTheQuitEvent() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#one", "erin");
        client.events.clear();

        client.processLine(":erin!user@host QUIT :gone");

        SimpleIrcClient.IrcEvent quit = client.events.stream()
                .filter(e -> e.getType() == SimpleIrcClient.IrcEvent.Type.QUIT)
                .findFirst().orElseThrow(AssertionError::new);
        assertEquals("#one", quit.getAdditionalData());
    }

    @Test
    public void nickChangeRenamesInPlaceAndKeepsModes() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob");
        client.events.clear();

        client.processLine(":bob!user@host NICK robert");

        assertEquals(java.util.Collections.singletonList("@robert"), client.nicksIn("#chan"));
        assertEquals(java.util.Collections.singletonList("#chan"), client.usersChangedChannels());
    }

    @Test
    public void kickRemovesTheUserAndAnnounces() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "@bob erin");
        client.events.clear();

        client.processLine(":bob!user@host KICK #chan erin :out");

        assertEquals(java.util.Collections.singletonList("@bob"), client.nicksIn("#chan"));
        assertTrue(client.usersChangedChannels().contains("#chan"));
    }

    @Test
    public void partingOurselvesDropsTheWholeRoster() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 001 me :Welcome"); // registers our own nick as "me"
        loadNames(client, "#chan", "@bob me");
        client.events.clear();

        client.processLine(":me!user@host PART #chan :bye");

        assertTrue("leaving drops the channel, not just us",
                client.nicksIn("#chan").isEmpty());
    }

    @Test
    public void beingKickedDropsTheWholeRoster() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 001 me :Welcome");
        loadNames(client, "#chan", "@bob me");
        client.events.clear();

        client.processLine(":bob!user@host KICK #chan me :out");

        assertTrue("being kicked drops the channel, not just us",
                client.nicksIn("#chan").isEmpty());
    }

    @Test
    public void channelModeIsAppliedToTheRoster() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "bob");
        client.events.clear();

        client.processLine(":op!user@host MODE #chan +o bob");

        assertEquals(java.util.Collections.singletonList("@bob"), client.nicksIn("#chan"));
        assertTrue(client.usersChangedChannels().contains("#chan"));
    }

    @Test
    public void compoundChannelModeAlignsItsParameters() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "bob");
        client.events.clear();

        client.processLine(":op!user@host MODE #chan +mo bob");

        assertEquals(java.util.Collections.singletonList("@bob"), client.nicksIn("#chan"));
    }

    @Test
    public void channelModeStillFiresTheDisplayEvent() {
        RecordingClient client = new RecordingClient();
        loadNames(client, "#chan", "bob");
        client.events.clear();

        client.processLine(":op!user@host MODE #chan +o bob");

        assertTrue(client.firedType(SimpleIrcClient.IrcEvent.Type.CHANNEL_MODE));
    }

    @Test
    public void userModeOnANickIsNotTreatedAsAChannel() {
        RecordingClient client = new RecordingClient();
        client.processLine(":me!user@host MODE me +i");
        assertTrue("no channel changed", client.usersChangedChannels().isEmpty());
    }
}

package com.irc;

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Diagnostics for the two failure modes users actually report: a connection that never comes up,
 * and one that is torn down without explanation.
 *
 * The server almost always says why - in an ERROR line, a KILL, or an error numeric - and the
 * client used to drop all of it on the floor. These tests pin down that the text survives as far
 * as a fired event, because that text is the whole of what a reporting user can give us.
 */
public class SimpleIrcClientDiagnosticsTest {

    /** Feeds raw lines without a socket and records what came back out. */
    private static class RecordingClient extends SimpleIrcClient {
        final List<IrcEvent> events = new ArrayList<>();

        RecordingClient() {
            addEventListener(events::add);
        }

        @Override
        public synchronized void sendRawLine(String line) {
            // no socket in tests
        }

        IrcEvent firstOf(IrcEvent.Type type) {
            return events.stream().filter(e -> e.getType() == type).findFirst().orElse(null);
        }

        IrcEvent lastOf(IrcEvent.Type type) {
            return events.stream().filter(e -> e.getType() == type)
                    .reduce((a, b) -> b).orElse(null);
        }
    }

    @Test
    public void serverErrorLineSurfacesTheServersOwnReason() {
        RecordingClient client = new RecordingClient();

        client.processLine("ERROR :Closing Link: someone[1.2.3.4] (Ping timeout: 240 seconds)");

        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.ERROR);
        assertNotNull("server ERROR must fire an ERROR event", event);
        assertTrue("the server's reason must survive: " + event.getMessage(),
                event.getMessage().contains("Ping timeout: 240 seconds"));
    }

    @Test
    public void killNamesTheOperatorAndTheReason() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "runelite", "me");

        client.processLine(":oper!o@staff.example KILL me :staff.example (spamming)");

        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.ERROR);
        assertNotNull("a KILL against us must fire an ERROR event", event);
        assertTrue("the killing operator must be named: " + event.getMessage(),
                event.getMessage().contains("oper"));
        assertTrue("the kill reason must survive: " + event.getMessage(),
                event.getMessage().contains("spamming"));
    }

    @Test
    public void killAgainstAnotherUserIsNotOurDisconnect() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "runelite", "me");

        client.processLine(":oper!o@staff.example KILL someoneelse :staff.example (spamming)");

        assertNull("another user being killed must not report our own link as dead",
                client.firstOf(SimpleIrcClient.IrcEvent.Type.ERROR));
    }

    @Test
    public void unhandledErrorNumericSurfacesItsText() {
        RecordingClient client = new RecordingClient();

        client.processLine(":server 465 me :You are banned from this server: spamming");

        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.SERVER_ERROR);
        assertNotNull("an error numeric we do not handle explicitly must still be reported", event);
        assertTrue("the server's explanation must survive: " + event.getMessage(),
                event.getMessage().contains("You are banned from this server: spamming"));
    }

    @Test
    public void informationalNumericsAreNotReportedAsErrors() {
        RecordingClient client = new RecordingClient();

        client.processLine(":server 372 me :- welcome to the message of the day");
        client.processLine(":server 251 me :There are 4000 users on the network");

        assertNull("MOTD and stats numerics are not failures and must stay quiet",
                client.firstOf(SimpleIrcClient.IrcEvent.Type.SERVER_ERROR));
    }

    @Test
    public void numericWithItsOwnHandlerIsNotAlsoReportedGenerically() {
        RecordingClient client = new RecordingClient();

        client.processLine(":server 433 me takenNick :Nickname is already in use");

        assertNotNull("433 keeps its dedicated handling",
                client.firstOf(SimpleIrcClient.IrcEvent.Type.NICK_IN_USE));
        assertNull("a numeric we handle explicitly must not be double-reported",
                client.firstOf(SimpleIrcClient.IrcEvent.Type.SERVER_ERROR));
    }

    @Test
    public void unknownHostIsExplainedRatherThanEchoedBack() {
        // UnknownHostException.getMessage() is just the hostname, so surfacing it raw showed the
        // user "Error: irc.swiftirc.net" and nothing else.
        String described = SimpleIrcClient.describeFailure(
                SimpleIrcClient.ConnectPhase.CONNECTING, "irc.swiftirc.net", 6697,
                new java.net.UnknownHostException("irc.swiftirc.net"));

        assertTrue("must say what went wrong, not just echo the host: " + described,
                described.toLowerCase().contains("dns"));
        assertTrue("must still name the host: " + described,
                described.contains("irc.swiftirc.net"));
    }

    @Test
    public void readTimeoutIsExplainedAsALostConnectionWithItsDuration() {
        String described = SimpleIrcClient.describeFailure(
                SimpleIrcClient.ConnectPhase.ESTABLISHED, "irc.swiftirc.net", 6697,
                new java.net.SocketTimeoutException("Read timed out"));

        assertTrue("must explain the silence, not just relay 'Read timed out': " + described,
                described.contains("240"));
    }

    @Test
    public void failureNamesThePhaseAndTheExceptionType() {
        String described = SimpleIrcClient.describeFailure(
                SimpleIrcClient.ConnectPhase.TLS_HANDSHAKE, "irc.swiftirc.net", 6697,
                new javax.net.ssl.SSLHandshakeException("certificate unknown"));

        assertTrue("must name the phase: " + described,
                described.toLowerCase().contains("tls"));
        assertTrue("must name the exception type: " + described,
                described.contains("SSLHandshakeException"));
        assertTrue("must carry the underlying message: " + described,
                described.contains("certificate unknown"));
        assertTrue("must name where we were connecting: " + described,
                described.contains("irc.swiftirc.net:6697"));
    }

    // Raw line logging exists so a user can hand us the log. That makes redaction a correctness
    // requirement, not a nicety: the SASL exchange and NickServ traffic carry the password.

    @Test
    public void saslResponseIsRedactedFromTheLog() {
        String redacted = SimpleIrcClient.redactForLog("AUTHENTICATE AGFjY291bnQAaHVudGVyMg==");

        assertFalse("the SASL PLAIN payload decodes to the password: " + redacted,
                redacted.contains("AGFjY291bnQAaHVudGVyMg=="));
        assertTrue("the exchange must still be visible: " + redacted,
                redacted.startsWith("AUTHENTICATE"));
    }

    @Test
    public void saslMechanismAndContinuationAreKept() {
        // These carry no secret and are exactly what you need to see to debug a stalled CAP/SASL.
        assertEquals("AUTHENTICATE PLAIN", SimpleIrcClient.redactForLog("AUTHENTICATE PLAIN"));
        assertEquals("AUTHENTICATE +", SimpleIrcClient.redactForLog("AUTHENTICATE +"));
    }

    @Test
    public void nickServPasswordIsRedactedFromTheLog() {
        String redacted = SimpleIrcClient.redactForLog("PRIVMSG NickServ :IDENTIFY hunter2");

        assertFalse("the NickServ password must not reach the log: " + redacted,
                redacted.contains("hunter2"));
        assertTrue("the fact that we identified must still be visible: " + redacted,
                redacted.contains("NickServ"));
    }

    @Test
    public void serverPasswordIsRedactedFromTheLog() {
        String redacted = SimpleIrcClient.redactForLog("PASS s3rverp4ss");

        assertFalse("the server password must not reach the log: " + redacted,
                redacted.contains("s3rverp4ss"));
    }

    @Test
    public void ordinaryTrafficIsLoggedVerbatim() {
        String line = ":nick!user@host PRIVMSG #rshelp :hello there";
        assertEquals("redaction must not damage the lines we actually want to read",
                line, SimpleIrcClient.redactForLog(line));
    }

    @Test
    public void disconnectCarriesTheReasonTheServerGave() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "runelite", "me");
        client.processLine(":server 001 me :Welcome to SwiftIRC");
        client.processLine("ERROR :Closing Link: me[1.2.3.4] (Ping timeout: 240 seconds)");

        client.disconnect();

        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.DISCONNECT);
        assertNotNull("disconnecting must still announce itself", event);
        assertNotNull("a disconnect with a known cause must carry it", event.getMessage());
        assertTrue("the cause must reach the disconnect message: " + event.getMessage(),
                event.getMessage().contains("Ping timeout: 240 seconds"));
    }

    @Test
    public void deliberateQuitReportsNoFailureReason() {
        RecordingClient client = new RecordingClient();
        client.credentials("me", "runelite", "me");
        client.processLine(":server 001 me :Welcome to SwiftIRC");

        client.disconnect();

        SimpleIrcClient.IrcEvent event = client.firstOf(SimpleIrcClient.IrcEvent.Type.DISCONNECT);
        assertNotNull(event);
        assertNull("a clean /quit has no failure to report", event.getMessage());
    }

    @Test
    public void serverErrorReportsItsOwnTextNotAnEarlierReason() {
        // The recorded disconnect reason is first-writer-wins, so reporting the field rather than
        // the line's own text made the ERROR event repeat the KILL reason under "closed the link".
        RecordingClient client = new RecordingClient();
        client.credentials("me", "runelite", "me");
        client.processLine(":oper!o@staff.example KILL me :staff.example (spamming)");

        client.processLine("ERROR :Closing Link: me[1.2.3.4] (Killed)");

        SimpleIrcClient.IrcEvent last = client.lastOf(SimpleIrcClient.IrcEvent.Type.ERROR);
        assertTrue("the ERROR line must report its own text: " + last.getMessage(),
                last.getMessage().contains("Closing Link"));
    }

    @Test
    public void tlsSocketIsConfiguredToVerifyTheServerHostname() throws Exception {
        // SSLSocket validates the certificate chain but does NOT check that the certificate
        // belongs to the host we asked for, unless endpoint identification is turned on. Without
        // it, any certificate signed by a trusted CA - for any hostname at all - is accepted.
        javax.net.ssl.SSLSocket socket = (javax.net.ssl.SSLSocket)
                javax.net.ssl.SSLSocketFactory.getDefault().createSocket();

        SimpleIrcClient.applyTlsSettings(socket);

        assertEquals("the socket must verify the hostname against the certificate",
                "HTTPS", socket.getSSLParameters().getEndpointIdentificationAlgorithm());
    }

    @Test
    public void anUnconfiguredTlsSocketWouldNotVerifyTheHostname() throws Exception {
        // Pins the JDK default this guards against, so the test above cannot silently start
        // passing for the wrong reason.
        javax.net.ssl.SSLSocket socket = (javax.net.ssl.SSLSocket)
                javax.net.ssl.SSLSocketFactory.getDefault().createSocket();

        assertNull("JDK default is no hostname verification",
                socket.getSSLParameters().getEndpointIdentificationAlgorithm());
    }

    // Channel keys are passwords too, and they travel in both directions: we send them on JOIN
    // and MODE, and the server hands them back in a MODE change and in RPL_CHANNELMODEIS.

    @Test
    public void joinKeyIsRedactedFromTheLog() {
        String redacted = SimpleIrcClient.redactForLog("JOIN #secret hunter2");

        assertFalse("the channel key must not reach the log: " + redacted,
                redacted.contains("hunter2"));
        assertTrue("which channel we joined must still be visible: " + redacted,
                redacted.contains("#secret"));
    }

    @Test
    public void multipleJoinKeysAreRedacted() {
        String redacted = SimpleIrcClient.redactForLog("JOIN #a,#b key1,key2");

        assertFalse("no key may survive: " + redacted, redacted.contains("key1"));
        assertFalse("no key may survive: " + redacted, redacted.contains("key2"));
    }

    @Test
    public void joinWithoutAKeyIsLoggedVerbatim() {
        assertEquals("an ordinary join must not be damaged",
                "JOIN #rshelp", SimpleIrcClient.redactForLog("JOIN #rshelp"));
    }

    @Test
    public void modeKeyWeSetIsRedacted() {
        String redacted = SimpleIrcClient.redactForLog("MODE #chan +k hunter2");

        assertFalse("the key we set must not reach the log: " + redacted,
                redacted.contains("hunter2"));
        assertTrue("the mode change itself must stay visible: " + redacted,
                redacted.contains("+k"));
    }

    @Test
    public void modeKeyFromAnotherUserIsRedacted() {
        String redacted = SimpleIrcClient.redactForLog(":op!u@host MODE #chan +k hunter2");

        assertFalse("an incoming key must not reach the log either: " + redacted,
                redacted.contains("hunter2"));
    }

    @Test
    public void modeKeyRemovalIsRedacted() {
        // Removing a key names it on most ircds, so -k leaks just as readily as +k.
        String redacted = SimpleIrcClient.redactForLog(":op!u@host MODE #chan -k hunter2");

        assertFalse("the key must not reach the log: " + redacted, redacted.contains("hunter2"));
    }

    @Test
    public void channelModeReplyKeyIsRedacted() {
        // RPL_CHANNELMODEIS: the server volunteers the key when we join a keyed channel.
        String redacted = SimpleIrcClient.redactForLog(":server 324 me #chan +nk hunter2");

        assertFalse("the server's echo of the key must not reach the log: " + redacted,
                redacted.contains("hunter2"));
        assertTrue("the mode string must stay visible: " + redacted, redacted.contains("+nk"));
    }

    @Test
    public void modeChangesWithoutAKeyAreLoggedVerbatim() {
        String line = ":op!u@host MODE #chan +o someone";
        assertEquals("ordinary mode changes must not be damaged",
                line, SimpleIrcClient.redactForLog(line));
    }

    @Test
    public void chanServPasswordIsRedactedFromTheLog() {
        // Reachable today: /cs routes to ChanServ, whose IDENTIFY carries a channel password.
        String redacted = SimpleIrcClient.redactForLog("PRIVMSG ChanServ :IDENTIFY #chan hunter2");

        assertFalse("the channel password must not reach the log: " + redacted,
                redacted.contains("hunter2"));
        assertTrue("the service we talked to must stay visible: " + redacted,
                redacted.contains("ChanServ"));
    }

    @Test
    public void bareServiceAliasPasswordIsRedacted() {
        // Not reachable through the current command set, but the log is only safe to hand over
        // if this holds regardless of how the line was produced.
        assertFalse("bare NS alias must be redacted too",
                SimpleIrcClient.redactForLog("NS IDENTIFY hunter2").contains("hunter2"));
        assertFalse("bare CS alias must be redacted too",
                SimpleIrcClient.redactForLog("CS IDENTIFY #chan hunter2").contains("hunter2"));
    }

    @Test
    public void harmlessServiceCommandsAreLoggedVerbatim() {
        String line = "PRIVMSG ChanServ :INFO #rshelp";
        assertEquals("a service command with no secret must not be damaged",
                line, SimpleIrcClient.redactForLog(line));
    }

    @Test
    public void ordinaryChannelTalkAboutIdentifyingIsNotRedacted() {
        String line = "PRIVMSG #rshelp :you need to identify to nickserv first";
        assertEquals("redaction must not fire on ordinary conversation",
                line, SimpleIrcClient.redactForLog(line));
    }

    @Test
    public void setPasswordIsRedactedForBothServices() {
        // ChanServ puts the channel between the verb and the keyword: SET <chan> PASSWORD <pw>,
        // while NickServ has no middle argument. Both must be caught.
        assertFalse("ChanServ SET PASSWORD must be redacted",
                SimpleIrcClient.redactForLog("PRIVMSG ChanServ :SET #chan PASSWORD hunter2")
                        .contains("hunter2"));
        assertFalse("NickServ SET PASSWORD must be redacted",
                SimpleIrcClient.redactForLog("PRIVMSG NickServ :SET PASSWORD hunter2")
                        .contains("hunter2"));
    }

    @Test
    public void nonPasswordSettingsAreLoggedVerbatim() {
        String line = "PRIVMSG ChanServ :SET #chan SECURE on";
        assertEquals("settings that carry no secret must not be damaged",
                line, SimpleIrcClient.redactForLog(line));
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JTextPane;
import javax.swing.text.AttributeSet;
import javax.swing.text.Document;
import javax.swing.text.Element;
import javax.swing.text.ElementIterator;
import javax.swing.text.html.HTMLDocument;
import java.util.Enumeration;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * IRC color codes are {@code <fg>,<bg>}; the panel now renders the background too.
 * colorSpan builds the HTML run: foreground is always applied (via the 0-98 palette, falling
 * back to black like a normal color), while a background is applied ONLY for a real palette
 * code 0-98 - code 99 ("default background") and anything out of range render with no
 * background so the theme shows through.
 */
public class IrcBackgroundColorTest {

    @Test
    public void foregroundOnlyWhenNoBackground() {
        assertEquals("<span style=\"color:#FF0000\">hi</span>",
                IrcPanel.ChannelPane.colorSpan("4", null, "hi"));
    }

    @Test
    public void foregroundAndBackground() {
        assertEquals("<span style=\"color:#FF0000;background-color:#FFFF00\">hi</span>",
                IrcPanel.ChannelPane.colorSpan("4", "8", "hi"));
    }

    @Test
    public void extendedPaletteBackground() {
        // Foreground 0 is the classic palette's named "white"; background 16 is extended-palette hex.
        assertEquals("<span style=\"color:white;background-color:#470000\">x</span>",
                IrcPanel.ChannelPane.colorSpan("0", "16", "x"));
    }

    @Test
    public void defaultBackground99RendersNoBackground() {
        assertEquals("<span style=\"color:#FF0000\">hi</span>",
                IrcPanel.ChannelPane.colorSpan("4", "99", "hi"));
    }

    @Test
    public void invalidBackgroundRendersNoBackground() {
        assertEquals("<span style=\"color:#FF0000\">hi</span>",
                IrcPanel.ChannelPane.colorSpan("4", "notacode", "hi"));
    }

    @Test
    public void backgroundRunUsesNonBreakingSpacesSoTheyDoNotCollapse() {
        // Swing collapses runs of regular whitespace, so a colored space would lose its block.
        assertEquals("<span style=\"color:#FF0000;background-color:#FFFF00\">a&nbsp;&nbsp;b</span>",
                IrcPanel.ChannelPane.colorSpan("4", "8", "a  b"));
    }

    @Test
    public void foregroundOnlyRunKeepsRegularSpaces() {
        // No background means no colored block to preserve; keep normal spaces so text still wraps.
        assertEquals("<span style=\"color:#FF0000\">a  b</span>",
                IrcPanel.ChannelPane.colorSpan("4", null, "a  b"));
    }

    /**
     * Root-cause evidence: Swing's HTML view collapses consecutive regular spaces but keeps
     * non-breaking spaces - which is exactly why a background-colored space needs {@code &nbsp;}.
     */
    @Test
    public void swingCollapsesRegularSpacesButPreservesNonBreakingSpaces() throws Exception {
        int collapsed = bodyText("<span>a   b</span>").trim().length();
        int preserved = bodyText("<span>a&nbsp;&nbsp;&nbsp;b</span>").trim().length();
        assertTrue("regular spaces should collapse (" + collapsed + " chars)", collapsed < preserved);
        assertEquals("nbsp run keeps a + 3 spaces + b", 5, preserved);
    }

    private static String bodyText(String spanHtml) throws Exception {
        JTextPane pane = new JTextPane();
        pane.setContentType("text/html");
        pane.setText("<html><body>" + spanHtml + "</body></html>");
        Document doc = pane.getDocument();
        return doc.getText(0, doc.getLength());
    }

    /**
     * Proves Swing's HTML renderer actually parses an inline background-color onto the text run
     * (not just that we emit the markup). If this fails, Approach A doesn't render and we'd need
     * to set StyledDocument attributes directly instead.
     */
    @Test
    public void swingHtmlRendererParsesInlineBackground() throws Exception {
        JTextPane pane = new JTextPane();
        pane.setContentType("text/html");
        pane.setText("<html><body>" + IrcPanel.ChannelPane.colorSpan("4", "8", "hi") + "</body></html>");

        Object background = backgroundAttributeFor((HTMLDocument) pane.getDocument(), "hi");
        assertNotNull("Swing must parse background-color onto the run", background);
        assertTrue("background should be the yellow we asked for, was: " + background,
                background.toString().toLowerCase().contains("ffff00"));
    }

    private static Object backgroundAttributeFor(HTMLDocument doc, String text) throws Exception {
        ElementIterator it = new ElementIterator(doc);
        for (Element el = it.next(); el != null; el = it.next()) {
            if (!el.isLeaf()) {
                continue;
            }
            String content = doc.getText(el.getStartOffset(), el.getEndOffset() - el.getStartOffset());
            if (!content.contains(text)) {
                continue;
            }
            AttributeSet attrs = el.getAttributes();
            for (Enumeration<?> names = attrs.getAttributeNames(); names.hasMoreElements(); ) {
                Object key = names.nextElement();
                if ("background-color".equals(key.toString())) {
                    return attrs.getAttribute(key);
                }
            }
        }
        return null;
    }
}

package com.irc;

import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.ClientUI;
import org.junit.Test;

import javax.swing.JTabbedPane;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.Map;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * The plugin's half of the channel browser: the order it arms the response timeout in, how it
 * reports that timeout, and what it releases when it shuts down.
 *
 * IrcPlugin is normally built by Guice. Only three of its injected fields are reached on this path
 * - the RuneLite Client, the config and the panel - so they are set directly, and the Client is a
 * dynamic proxy because the real one is an interface with hundreds of methods of which exactly one
 * is called here.
 */
public class IrcPluginChannelListTest {

    private static IrcConfig stubConfig() {
        // IrcConfig has two abstract methods; everything else is a default.
        return new IrcConfig() {
            @Override
            public String username() {
                return "tester";
            }

            @Override
            public String password() {
                return "";
            }
        };
    }

    /**
     * Stands in for the RuneLite client and counts the one question the plugin asks it.
     *
     * That count is the signal two of these tests lean on: {@code getGameState()} is consulted by
     * {@code IrcPlugin.processMessage} and by nothing else reachable from here, so a non-zero count
     * means a message went through processMessage - the single funnel that feeds the game chatbox
     * as well as the panel - rather than being written straight into the panel.
     *
     * LOGIN_SCREEN keeps the chatbox branch itself out of the way: actually queueing a chat message
     * would need a ChatMessageManager, a RuneLite service with no usable constructor. Reaching the
     * gate is what is being asserted.
     */
    private static final class GameStateProbe implements InvocationHandler {
        final AtomicInteger gameStateQueries = new AtomicInteger();

        @Override
        public Object invoke(Object proxy, Method method, Object[] args) {
            switch (method.getName()) {
                case "getGameState":
                    gameStateQueries.incrementAndGet();
                    return GameState.LOGIN_SCREEN;
                case "hashCode":
                    return System.identityHashCode(proxy);
                case "equals":
                    return proxy == args[0];
                case "toString":
                    return "GameStateProbe";
                default:
                    throw new AssertionError("unexpected call to the RuneLite client: " + method);
            }
        }
    }

    private static Client clientProxy(GameStateProbe probe) {
        return (Client) Proxy.newProxyInstance(
                Client.class.getClassLoader(), new Class<?>[]{Client.class}, probe);
    }

    /** Same headless construction as IrcPanelChannelListTest: no Window, but real panes. */
    private static <T extends IrcPanel> T dressPanel(T panel) throws Exception {
        setField(IrcPanel.class, panel, "config", stubConfig());
        setField(IrcPanel.class, panel, "tabbedPane", new JTabbedPane());
        panel.addChannel("System");
        panel.setFocusedChannel("System");
        return panel;
    }

    private static void setField(Class<?> owner, Object target, String name, Object value) throws Exception {
        Field field = owner.getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }

    private static Object getField(Class<?> owner, Object target, String name) throws Exception {
        Field field = owner.getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }

    /**
     * Drains the EDT twice. A message reaches a pane through two hops of invokeLater - the
     * plugin's processMessage queues panel.addMessage, and ChannelPane.appendMessage queues the
     * document edit - so a single drain runs the first hop and only enqueues the second. Draining
     * once would make every "the pane must NOT contain X" assertion pass vacuously.
     */
    private static void drainEdt() throws Exception {
        SwingUtilities.invokeAndWait(() -> { });
        SwingUtilities.invokeAndWait(() -> { });
    }

    private static Method privateMethod(String name, Class<?>... types) throws Exception {
        Method method = IrcPlugin.class.getDeclaredMethod(name, types);
        method.setAccessible(true);
        return method;
    }

    private static IrcPlugin pluginWith(IrcPanel panel, IrcAdapter adapter, GameStateProbe probe) throws Exception {
        IrcPlugin plugin = new IrcPlugin();
        setField(IrcPlugin.class, plugin, "config", stubConfig());
        setField(IrcPlugin.class, plugin, "client", clientProxy(probe));
        setField(IrcPlugin.class, plugin, "panel", panel);
        setField(IrcPlugin.class, plugin, "ircAdapter", adapter);
        return plugin;
    }

    /** Records that the timeout was armed, without starting a real 30 second Swing Timer. */
    private static class ProbePanel extends IrcPanel {
        volatile boolean armed;
        volatile boolean tornDown;

        @Override
        public void armChannelListTimeout() {
            armed = true;
        }

        @Override
        public void shutdown() {
            tornDown = true;
        }
    }

    /**
     * Answers "was the timeout already armed at the moment the LIST hit the wire?".
     *
     * requestChannelList stands in for the real write-and-flush and drains the EDT before looking,
     * so anything the plugin queued with invokeLater beforehand has already run and anything queued
     * afterwards has not.
     */
    private static class WireProbeAdapter extends IrcAdapter {
        private final ProbePanel probePanel;
        volatile boolean sent;
        volatile boolean armedWhenSent;
        volatile boolean panelCleared;
        volatile boolean connected = true;

        WireProbeAdapter(ProbePanel probePanel) {
            this.probePanel = probePanel;
        }

        @Override
        public boolean isConnected() {
            return connected;
        }

        @Override
        public void requestChannelList(String query) {
            sent = true;
            try {
                SwingUtilities.invokeAndWait(() -> { });
            } catch (Exception e) {
                throw new AssertionError(e);
            }
            armedWhenSent = probePanel.armed;
        }

        @Override
        public void clearPanel() {
            panelCleared = true;
        }

        @Override
        public void disconnect(String reason) {
            // No socket in a unit test.
        }
    }

    /**
     * Whole-branch review finding (arm-after-send inversion): sendRawLine writes and flushes
     * synchronously, so arming afterwards left a window in which a 323 round-trips, queues its
     * cancel first, and the arm then lands on top of it - firing "no response" over a list the
     * user is already reading. Hoisting the arm above the send closes it.
     *
     * Not reachable over a real network (one invokeLater against a round trip), which is exactly
     * why the ordering needs pinning rather than trusting.
     */
    @Test
    public void theTimeoutIsArmedBeforeTheListGoesOnTheWire() throws Exception {
        ProbePanel panel = dressPanel(new ProbePanel());
        WireProbeAdapter adapter = new WireProbeAdapter(panel);
        IrcPlugin plugin = pluginWith(panel, adapter, new GameStateProbe());

        privateMethod("handleChannelListRequest", String.class).invoke(plugin, ">50");
        drainEdt();

        assertTrue("the request must reach the adapter", adapter.sent);
        assertTrue("the timeout must already be armed when the LIST is written",
                adapter.armedWhenSent);
    }

    /** An unconnected /list says so, sends nothing and arms nothing. */
    @Test
    public void anUnconnectedRequestNeitherSendsNorArms() throws Exception {
        ProbePanel panel = dressPanel(new ProbePanel());
        WireProbeAdapter adapter = new WireProbeAdapter(panel);
        adapter.connected = false;
        IrcPlugin plugin = pluginWith(panel, adapter, new GameStateProbe());

        privateMethod("handleChannelListRequest", String.class).invoke(plugin, "");
        drainEdt();

        assertFalse(adapter.sent);
        assertFalse(panel.armed);

        Map<String, IrcPanel.ChannelPane> panes = panel.getChannelPanes();
        assertTrue("the user has to be told why nothing happened",
                panes.get("System").getText().toLowerCase().contains("not connected"));
    }

    /**
     * Whole-branch review finding: the 30 second timeout notice was the only channel-list message
     * that skipped the game chatbox. The request announces itself through processMessage (chatbox
     * and panel) and a 263 refusal does too, but the expiry called panel.addMessage directly - so a
     * user watching game chat with the sidebar collapsed saw the request and never its outcome.
     *
     * The plugin now owns emitting it. Two things are pinned: the notice still reaches the panel,
     * and getGameState() was consulted while producing it - which only happens inside
     * processMessage. Reinstating the direct panel write leaves the first assertion passing and
     * fails the second.
     */
    @Test
    public void theTimeoutNoticeGoesThroughTheSharedMessagePath() throws Exception {
        IrcPanel panel = dressPanel(new IrcPanel());
        GameStateProbe probe = new GameStateProbe();
        IrcPlugin plugin = pluginWith(panel, null, probe);

        // setupPanel wires exactly this callback; it cannot be called here because it also builds
        // the panel's Swing GUI, so the same method reference is bound by hand.
        Method report = privateMethod("reportChannelListTimeout");
        panel.init(null, null, null, null, null, () -> {
            try {
                report.invoke(plugin);
            } catch (Exception e) {
                throw new AssertionError(e);
            }
        });

        panel.armChannelListTimeout();
        probe.gameStateQueries.set(0);

        Timer timer = (Timer) getField(IrcPanel.class, panel, "channelListTimeout");
        for (java.awt.event.ActionListener listener : timer.getActionListeners()) {
            listener.actionPerformed(null);
        }
        panel.cancelChannelListTimeout();
        drainEdt();

        Map<String, IrcPanel.ChannelPane> panes = panel.getChannelPanes();
        String text = panes.get("System").getText();
        assertTrue("the panel must still see the notice, got: " + text,
                text.toLowerCase().contains("no channel list response"));
        assertTrue("the notice must be emitted through processMessage, the same funnel that queues"
                        + " it to the game chatbox",
                probe.gameStateQueries.get() > 0);
    }

    /**
     * Whole-branch review finding: the browser outlived the plugin. shutDown() dropped the panel
     * reference but disposed nothing, so the JDialog stayed on screen with Refresh and Join both
     * returning silently; and the adapter kept its own panel reference, so a 323 arriving during
     * teardown could still pop the browser for a plugin that was already gone.
     */
    @Test
    public void shutdownTearsDownThePanelAndCutsTheAdapterLoose() throws Exception {
        ProbePanel panel = dressPanel(new ProbePanel());
        WireProbeAdapter adapter = new WireProbeAdapter(panel);
        IrcPlugin plugin = pluginWith(panel, adapter, new GameStateProbe());
        setField(IrcPlugin.class, plugin, "clientToolbar", clientToolbar());

        privateMethod("shutDown").invoke(plugin);
        drainEdt();

        assertTrue("the panel must be torn down, not merely dereferenced", panel.tornDown);
        assertTrue("the adapter must lose its panel reference before the panel goes",
                adapter.panelCleared);
        assertNull("and only then is the panel dropped",
                getField(IrcPlugin.class, plugin, "panel"));
        assertNull(getField(IrcPlugin.class, plugin, "ircAdapter"));
    }

    /**
     * ClientToolbar's only constructor is private and takes a ClientUI. shutDown() hands it the
     * panel's navigation button, which is null on a panel that never built its GUI, and the real
     * method marshals that onto the EDT - so an instance with no ClientUI gets through.
     */
    private static ClientToolbar clientToolbar() throws Exception {
        Constructor<ClientToolbar> constructor =
                ClientToolbar.class.getDeclaredConstructor(ClientUI.class);
        constructor.setAccessible(true);
        return constructor.newInstance((ClientUI) null);
    }
}

package com.irc;

import org.junit.Test;
import org.junit.Before;

import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTabbedPane;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import java.awt.BorderLayout;
import java.awt.Rectangle;
import java.awt.event.WindowEvent;
import java.util.concurrent.atomic.AtomicInteger;

import static org.junit.Assert.*;

/** Desktop tests with real Swing windows; no IRC connection or RuneLite login is needed. */
public class IrcPanelWindowTest {
    @Before
    public void requiresDesktop() {
        org.junit.Assume.assumeFalse(java.awt.GraphicsEnvironment.isHeadless());
    }

    @Test
    public void switchingHostsPreservesChatAndResizeFillsWindow() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            JPanel dock = new JPanel(new BorderLayout());
            JPanel content = new JPanel(new BorderLayout());
            JTextField draft = new JTextField("unfinished message");
            JTabbedPane tabs = new JTabbedPane();
            JTextArea history = new JTextArea("older message\nlatest message");
            tabs.addTab("System", new JPanel());
            tabs.addTab("#test", new JScrollPane(history));
            tabs.setSelectedIndex(1);
            content.add(tabs, BorderLayout.CENTER);
            content.add(draft, BorderLayout.SOUTH);
            dock.add(content, BorderLayout.CENTER);
            IrcPanelWindow host = new IrcPanelWindow(dock, content, () -> {}, () -> {}, () -> {});
            try {
                for (int i = 0; i < 3; i++) {
                    host.setDetached(true, false);
                    JFrame frame = (JFrame) SwingUtilities.getWindowAncestor(content);
                    assertTrue(frame.isVisible());
                    assertEquals(0, dock.getComponentCount());
                    frame.setSize(620, 680);
                    frame.validate();
                    assertEquals(frame.getContentPane().getWidth(), content.getWidth());
                    assertEquals(frame.getContentPane().getHeight(), content.getHeight());
                    assertEquals(1, tabs.getSelectedIndex());
                    assertEquals("unfinished message", draft.getText());
                    assertEquals("older message\nlatest message", history.getText());
                    host.setDetached(true, true);
                    assertSame(frame, SwingUtilities.getWindowAncestor(content));
                    assertTrue(frame.isAlwaysOnTop());
                    host.setDetached(false, false);
                    assertSame(dock, content.getParent());
                    assertFalse(frame.isDisplayable());
                }
            } finally {
                host.shutdown();
            }
        });
    }

    @Test
    public void closeRequestsDockAndShutdownRemovesWindowListeners() throws Exception {
        SwingUtilities.invokeAndWait(() -> {
            JFrame main = new JFrame();
            JPanel dock = new JPanel(new BorderLayout());
            JPanel content = new JPanel();
            dock.add(content, BorderLayout.CENTER);
            main.add(dock);
            main.setSize(300, 400);
            main.setVisible(true);
            int focusListeners = main.getWindowFocusListeners().length;
            int componentListeners = main.getComponentListeners().length;
            AtomicInteger dockRequests = new AtomicInteger();
            IrcPanelWindow host = new IrcPanelWindow(dock, content, () -> {}, () -> {},
                    dockRequests::incrementAndGet);
            try {
                assertEquals(focusListeners + 1, main.getWindowFocusListeners().length);
                host.setDetached(true, false);
                JFrame popOut = (JFrame) SwingUtilities.getWindowAncestor(content);
                assertEquals(focusListeners, main.getWindowFocusListeners().length);
                popOut.dispatchEvent(new WindowEvent(popOut, WindowEvent.WINDOW_CLOSING));
                assertEquals(1, dockRequests.get());
                // The config event performs the actual docking, not JFrame's close operation.
                host.setDetached(false, false);
                assertSame(dock, content.getParent());
                host.setDetached(true, false);
                JFrame reopened = (JFrame) SwingUtilities.getWindowAncestor(content);
                Rectangle bounds = reopened.getBounds();
                host.setDetached(false, false);
                host.setDetached(true, false);
                JFrame restored = (JFrame) SwingUtilities.getWindowAncestor(content);
                assertEquals(bounds, restored.getBounds());
                host.shutdown();
                assertFalse(restored.isDisplayable());
                assertEquals(focusListeners, main.getWindowFocusListeners().length);
                assertEquals(componentListeners, main.getComponentListeners().length);
                host.shutdown();
            } finally {
                host.shutdown();
                main.dispose();
            }
        });
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.SwingUtilities;
import javax.swing.text.View;
import javax.swing.text.html.HTMLDocument;
import java.awt.Color;
import java.awt.Font;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

/**
 * The chat background and default text colour are user settings. Plain chat lines carry no
 * colour of their own and inherit the body's, so changing the setting recolours scrollback too.
 */
public class IrcChatColorsTest {

    private static IrcConfig config(Color background, Color text) {
        return new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
            @Override public Color chatBackgroundColor() { return background; }
            @Override public Color chatTextColor() { return text; }
            @Override public boolean colorizedNicks() { return false; }
        };
    }

    private static IrcPanel.ChannelPane renderedPane(IrcConfig config) throws Exception {
        AtomicReference<IrcPanel.ChannelPane> ref = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            IrcPanel.ChannelPane pane = new IrcPanel.ChannelPane(new Font("SansSerif", Font.PLAIN, 12), config, null);
            pane.appendMessage(new IrcMessage("#test", "bob", "hello",
                    IrcMessage.MessageType.CHAT, Instant.now()), config);
            ref.set(pane);
        });
        // appendMessage renders via invokeLater; wait for it.
        SwingUtilities.invokeAndWait(() -> {});
        return ref.get();
    }

    @Test
    public void defaultsMatchTheExistingTheme() {
        IrcConfig defaults = new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
        };
        assertEquals(new Color(30, 30, 30), defaults.chatBackgroundColor());
        assertEquals(new Color(165, 165, 165), defaults.chatTextColor());
    }

    @Test
    public void paneUsesConfiguredBackground() throws Exception {
        IrcPanel.ChannelPane pane = renderedPane(config(new Color(0x10, 0x20, 0x30), Color.WHITE));
        assertEquals(new Color(0x10, 0x20, 0x30), pane.getBackground());
    }

    @Test
    public void bodyUsesConfiguredTextColor() throws Exception {
        IrcPanel.ChannelPane pane = renderedPane(config(Color.BLACK, new Color(0xAB, 0xCD, 0xEF)));
        assertEquals(new Color(0xAB, 0xCD, 0xEF), renderedForeground(pane, "hello"));
    }

    @Test
    public void plainChatLinesInheritTheBodyColor() throws Exception {
        IrcPanel.ChannelPane pane = renderedPane(config(Color.BLACK, new Color(0xAB, 0xCD, 0xEF)));
        // The old hard-coded light gray must not be baked into the line.
        assertFalse(pane.getText().toLowerCase().contains("#a5a5a5"));
    }

    @Test
    public void changingTheSettingRecoloursScrollback() throws Exception {
        AtomicReference<Color> text = new AtomicReference<>(Color.RED);
        AtomicReference<Color> background = new AtomicReference<>(Color.BLACK);
        IrcConfig live = new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
            @Override public Color chatBackgroundColor() { return background.get(); }
            @Override public Color chatTextColor() { return text.get(); }
        };
        IrcPanel.ChannelPane pane = renderedPane(live);
        text.set(new Color(0x12, 0x34, 0x56));
        background.set(new Color(0x65, 0x43, 0x21));
        SwingUtilities.invokeAndWait(pane::applyColors);
        assertEquals(new Color(0x12, 0x34, 0x56), renderedForeground(pane, "hello"));
        assertEquals(new Color(0x65, 0x43, 0x21), pane.getBackground());
    }

    /** The colour Swing will actually paint {@code text} in, with CSS inheritance resolved by the view tree. */
    private static Color renderedForeground(IrcPanel.ChannelPane pane, String text) throws Exception {
        AtomicReference<Color> result = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            pane.setSize(400, 400);
            HTMLDocument doc = (HTMLDocument) pane.getDocument();
            View leaf = findLeaf(pane.getUI().getRootView(pane), doc, text);
            if (leaf != null) {
                result.set(doc.getStyleSheet().getForeground(leaf.getAttributes()));
            }
        });
        return result.get();
    }

    private static View findLeaf(View view, HTMLDocument doc, String text) {
        if (view.getViewCount() == 0) {
            try {
                int start = view.getStartOffset();
                return doc.getText(start, view.getEndOffset() - start).contains(text) ? view : null;
            } catch (Exception e) {
                return null;
            }
        }
        for (int i = 0; i < view.getViewCount(); i++) {
            View found = findLeaf(view.getView(i), doc, text);
            if (found != null) {
                return found;
            }
        }
        return null;
    }
}

