    private static String rowText(JTree tree, String name) {
        TreePath path = path(tree, name);
        JLabel label = (JLabel) tree.getCellRenderer().getTreeCellRendererComponent(
                tree, path.getLastPathComponent(), false, false, true, tree.getRowForPath(path), false);
        return label.getText();
    }

    private static void release(JTree tree, int x, int y) {
        tree.dispatchEvent(new java.awt.event.MouseEvent(tree, java.awt.event.MouseEvent.MOUSE_RELEASED,
                System.currentTimeMillis(), java.awt.event.InputEvent.BUTTON1_DOWN_MASK, x, y, 1, false,
                java.awt.event.MouseEvent.BUTTON1));
    }

    private static Component find(Container parent, String name) {
        for (Component child : parent.getComponents()) {
            if (name.equals(child.getName())) return child;
            if (child instanceof Container) {
                Component found = find((Container) child, name);
                if (found != null) return found;
            }
        }
        return null;
    }

    private static TreePath path(JTree tree, String name) {
        DefaultMutableTreeNode root = (DefaultMutableTreeNode) tree.getModel().getRoot();
        java.util.Enumeration<?> nodes = root.depthFirstEnumeration();
        while (nodes.hasMoreElements()) {
            DefaultMutableTreeNode node = (DefaultMutableTreeNode) nodes.nextElement();
            if (name.equals(node.getUserObject())) return new TreePath(node.getPath());
        }
        return null;
    }

    private static void render(JPanel content) {
        BufferedImage image = new BufferedImage(content.getWidth(), content.getHeight(), BufferedImage.TYPE_INT_RGB);
        Graphics2D graphics = image.createGraphics();
        content.printAll(graphics);
        graphics.dispose();
        try {
            File target = new File("build/previews/irc-desktop.png");
            target.getParentFile().mkdirs();
            ImageIO.write(image, "png", target);
        } catch (java.io.IOException e) { throw new AssertionError(e); }
    }
}

package com.irc;

import org.junit.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * The protocol layer for LIST (numerics 321/322/323, plus 263 when the server throttles us).
 *
 * Replies accumulate on the reader thread and are published as one immutable snapshot at 323, so
 * the EDT never observes a half-filled list. Two rules matter most: a run must not inherit rows
 * from the previous run, and a malformed row must never abort the rest of the list - servers send
 * a lot of channels and one bad line should cost one row, not the whole reply.
 */
public class SimpleIrcClientListTest {

    /** Feeds raw lines without a socket and records what came back out. */
    private static class RecordingClient extends SimpleIrcClient {
        final List<IrcEvent> events = new ArrayList<>();

        RecordingClient() {
            addEventListener(events::add);
        }

        @Override
        public synchronized void sendRawLine(String line) {
            // no socket in tests
        }

        boolean firedType(IrcEvent.Type type) {
            return events.stream().anyMatch(e -> e.getType() == type);
        }

        long countOf(IrcEvent.Type type) {
            return events.stream().filter(e -> e.getType() == type).count();
        }
    }

    private static void listReply(RecordingClient client, String channel, String count, String topic) {
        client.processLine(":server 322 me " + channel + " " + count + " :" + topic);
    }

    @Test
    public void collectsChannelsBetweenStartAndEnd() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 321 me Channel :Users  Name");
        listReply(client, "#help", "412", "Get help here");
        listReply(client, "#chat", "380", "General chat");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(2, entries.size());
        assertEquals("#help", entries.get(0).getName());
        assertEquals(412, entries.get(0).getUserCount());
        assertEquals("Get help here", entries.get(0).getTopic());
        assertEquals("#chat", entries.get(1).getName());
        assertEquals(380, entries.get(1).getUserCount());
        assertTrue(client.firedType(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST));
    }

    /** Some servers never send 321, so 322 has to be able to start a run by itself. */
    @Test
    public void collectsWhenListStartIsNeverSent() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#help", "412", "Get help here");
        client.processLine(":server 323 me :End of /LIST");

        assertEquals(1, client.getChannelListSnapshot().size());
        assertEquals("#help", client.getChannelListSnapshot().get(0).getName());
    }

    @Test
    public void keepsTopicsContainingSpacesAndColons() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#help", "5", "Ask here: we answer 9-5, mostly");
        client.processLine(":server 323 me :End of /LIST");

        assertEquals("Ask here: we answer 9-5, mostly",
                client.getChannelListSnapshot().get(0).getTopic());
    }

    @Test
    public void treatsMissingTopicAsEmpty() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 322 me #notopic 7");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("", entries.get(0).getTopic());
        assertEquals(7, entries.get(0).getUserCount());
    }

    /** One unparseable count costs that row its number, not its place in the list. */
    @Test
    public void treatsUnparseableCountAsZeroAndKeepsTheRow() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#weird", "many", "Odd server");
        listReply(client, "#fine", "12", "Normal");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(2, entries.size());
        assertEquals(0, entries.get(0).getUserCount());
        assertEquals(12, entries.get(1).getUserCount());
    }

    @Test
    public void consecutiveRunsDoNotBleedTogether() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#first", "1", "one");
        client.processLine(":server 323 me :End of /LIST");
        assertEquals(1, client.getChannelListSnapshot().size());

        listReply(client, "#second", "2", "two");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#second", entries.get(0).getName());
        assertEquals(2, client.countOf(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST));
    }

    /** 321 arriving mid-flight resets, so a retried LIST never doubles up. */
    @Test
    public void listStartClearsPartialRun() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#stale", "1", "stale");
        client.processLine(":server 321 me Channel :Users  Name");
        listReply(client, "#fresh", "2", "fresh");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#fresh", entries.get(0).getName());
    }

    @Test
    public void tryAgainReportsFailureWithoutFiringChannelList() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 263 me LIST :Server load is too heavy, please try again later");

        assertTrue(client.firedType(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST_FAILED));
        assertFalse(client.firedType(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST));
    }

    /** 263 must not fire ERROR - IrcAdapter's ERROR case disconnects the client. */
    @Test
    public void tryAgainDoesNotFireError() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 263 me LIST :Try again later");

        assertFalse(client.firedType(SimpleIrcClient.IrcEvent.Type.ERROR));
    }

    @Test
    public void tryAgainDiscardsAPartialRun() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#partial", "3", "partial");
        client.processLine(":server 263 me LIST :Try again later");
        client.processLine(":server 323 me :End of /LIST");

        assertTrue(client.getChannelListSnapshot().isEmpty());
    }

    @Test
    public void rowWithNoChannelNameIsSkipped() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 322 me");
        listReply(client, "#good", "4", "good");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#good", entries.get(0).getName());
    }

    @Test
    public void stopsAccumulatingAtTheCapAndReportsTruncation() {
        RecordingClient client = new RecordingClient();
        for (int i = 0; i < 20005; i++) {
            listReply(client, "#chan" + i, "1", "topic");
        }
        client.processLine(":server 323 me :End of /LIST");

        assertEquals(20000, client.getChannelListSnapshot().size());
        assertTrue(client.isChannelListTruncated());
    }

    /**
     * The second run here deliberately omits 321, since not every server sends it. The flag must
     * still reset on the first 322 of a fresh run - it must not depend on 321 arriving to clear it.
     */
    @Test
    public void truncationFlagIsClearedByAFreshRun() {
        RecordingClient client = new RecordingClient();
        for (int i = 0; i < 20005; i++) {
            listReply(client, "#chan" + i, "1", "topic");
        }
        client.processLine(":server 323 me :End of /LIST");
        assertTrue(client.isChannelListTruncated());

        listReply(client, "#small", "1", "topic");
        client.processLine(":server 323 me :End of /LIST");

        assertFalse(client.isChannelListTruncated());
        assertEquals(1, client.getChannelListSnapshot().size());
    }

    /** A 323 with no preceding 321/322 must not wipe out the last good snapshot or re-fire CHANNEL_LIST. */
    @Test
    public void unpairedListEndDoesNotClobberThePreviousSnapshot() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#good", "4", "good");
        client.processLine(":server 323 me :End of /LIST");
        assertEquals(1, client.countOf(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST));

        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#good", entries.get(0).getName());
        assertEquals(1, client.countOf(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST));
    }

    /** disconnect() must clear a partial run so it can't bleed into the connection's next LIST. */
    @Test
    public void disconnectClearsAPartialRun() {
        RecordingClient client = new RecordingClient();
        client.processLine(":server 001 me :Welcome");
        listReply(client, "#partial", "3", "partial");

        client.disconnect();

        listReply(client, "#fresh", "1", "fresh");
        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#fresh", entries.get(0).getName());
    }

    /** 263 only concerns LIST; a throttled WHO must not touch LIST state or fire CHANNEL_LIST_FAILED. */
    @Test
    public void tryAgainForADifferentCommandLeavesListStateAlone() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#inflight", "1", "still going");

        client.processLine(":server 263 me WHO :Server load is too heavy, please try again later");

        assertFalse(client.firedType(SimpleIrcClient.IrcEvent.Type.CHANNEL_LIST_FAILED));

        client.processLine(":server 323 me :End of /LIST");

        List<ChannelListEntry> entries = client.getChannelListSnapshot();
        assertEquals(1, entries.size());
        assertEquals("#inflight", entries.get(0).getName());
    }

    @Test
    public void snapshotIsImmutable() {
        RecordingClient client = new RecordingClient();
        listReply(client, "#help", "1", "topic");
        client.processLine(":server 323 me :End of /LIST");

        try {
            client.getChannelListSnapshot().add(new ChannelListEntry("#injected", 0, ""));
            org.junit.Assert.fail("snapshot handed to the EDT must not be mutable");
        } catch (UnsupportedOperationException expected) {
            // the EDT holds this list; nothing may mutate it after publication
        }
    }
}

package com.irc;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

/**
 * The shared IRC formatting stripper.
 *
 * The background group must accept one OR two digits. The two constants this class replaced both
 * required exactly two, which left a stray ",5" behind on text coloured foreground 04 on
 * background 5 - while the renderer (IrcPanel.COLORS) parsed that same text as a real background.
 * Stripper and renderer must agree on what counts as a colour code.
 */
public class IrcFormattingTest {

    private static final String BOLD = String.valueOf((char) 0x02);
    private static final String COLOR = String.valueOf((char) 0x03);
    private static final String ITALIC = String.valueOf((char) 0x1D);
    private static final String REVERSE = String.valueOf((char) 0x15);
    private static final String RESET = String.valueOf((char) 0x0F);

    @Test
    public void stripsBoldItalicReverseAndReset() {
        assertEquals("hello", IrcFormatting.stripCodes(BOLD + "hello" + RESET));
        assertEquals("hello", IrcFormatting.stripCodes(ITALIC + "hello" + ITALIC));
        assertEquals("hello", IrcFormatting.stripCodes(REVERSE + "hello" + REVERSE));
    }

    @Test
    public void stripsBareColorCode() {
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "hello"));
    }

    @Test
    public void stripsOneAndTwoDigitForeground() {
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "4hello"));
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "04hello"));
    }

    @Test
    public void stripsTwoDigitBackground() {
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "04,12hello"));
    }

    /** The bug this task fixes: a single-digit background used to leave ",5" behind. */
    @Test
    public void stripsSingleDigitBackground() {
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "04,5hello"));
        assertEquals("hello", IrcFormatting.stripCodes(COLOR + "4,5hello"));
    }

    /** A comma that is not part of a colour code is ordinary text and must survive. */
    @Test
    public void keepsCommasThatAreNotBackgroundCodes() {
        assertEquals("hi, there", IrcFormatting.stripCodes(COLOR + "04hi, there"));
        assertEquals("a,b", IrcFormatting.stripCodes("a,b"));
    }

    @Test
    public void leavesPlainTextUntouched() {
        assertEquals("nothing to strip", IrcFormatting.stripCodes("nothing to strip"));
    }

    @Test
    public void toleratesNullAndEmpty() {
        assertNull(IrcFormatting.stripCodes(null));
        assertEquals("", IrcFormatting.stripCodes(""));
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.JComboBox;
import javax.swing.JPanel;
import javax.swing.JTabbedPane;
import java.lang.reflect.Field;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotEquals;

/**
 * Regression tests for renameChannel keeping every ordered UI structure consistent.
 *
 * Navigation maps a channel to a tab strictly by POSITION: setFocusedChannel computes
 * an index by iterating channelPanes, then calls tabbedPane.setSelectedIndex(index),
 * while getCurrentChannel()/getChannelNames() read the tab titles. That only works if
 * the channelPanes iteration order stays identical to the tabbedPane tab order.
 *
 * renameChannel() renamed the tab in place but did remove()+put() on the LinkedHashMap,
 * which moved the renamed channel to the END of the iteration order - diverging the two
 * orderings and sending navigation to the wrong tab. The bufferDropdown was also left with
 * the stale old label. A NICK change (e.g. a renamed query window) triggers this normally.
 */
public class IrcPanelRenameTest {

    private static JTabbedPane installTabbedPane(IrcPanel panel) throws Exception {
        JTabbedPane tabs = new JTabbedPane();
        Field tabbedPaneField = IrcPanel.class.getDeclaredField("tabbedPane");
        tabbedPaneField.setAccessible(true);
        tabbedPaneField.set(panel, tabs);
        return tabs;
    }

    @SuppressWarnings("unchecked")
    private static JComboBox<String> bufferDropdown(IrcPanel panel) throws Exception {
        Field field = IrcPanel.class.getDeclaredField("bufferDropdown");
        field.setAccessible(true);
        return (JComboBox<String>) field.get(panel);
    }

    private static void addChannel(IrcPanel panel, JTabbedPane tabs, JComboBox<String> dropdown, String name) {
        panel.getChannelPanes().put(name, null);
        panel.unreadMessages.put(name, false);
        tabs.addTab(name, new JPanel());
        if (dropdown != null) {
            dropdown.addItem(name);
        }
    }

    @Test
    public void renameKeepsChannelOrderAlignedWithTabs() throws Exception {
        IrcPanel panel = new IrcPanel();
        JTabbedPane tabs = installTabbedPane(panel);

        addChannel(panel, tabs, null, "System");
        addChannel(panel, tabs, null, "#alpha");
        addChannel(panel, tabs, null, "bob");
        addChannel(panel, tabs, null, "#gamma");

        // A NICK change renames a query window in place: bob -> bob2 (originally at index 2).
        panel.renameChannel("bob", "bob2");

        List<String> channelOrder = panel.getChannelNames();
        assertEquals("tab count and channel count must match", tabs.getTabCount(), channelOrder.size());
        for (int i = 0; i < tabs.getTabCount(); i++) {
            assertEquals("channelPanes order must match tab order at index " + i,
                    tabs.getTitleAt(i), channelOrder.get(i));
        }
        // The renamed channel must keep its position, not jump to the end.
        assertEquals("bob2", channelOrder.get(2));
    }

    @Test
    public void renameUpdatesBufferDropdownLabelInPlace() throws Exception {
        IrcPanel panel = new IrcPanel();
        JTabbedPane tabs = installTabbedPane(panel);
        JComboBox<String> dropdown = bufferDropdown(panel);

        addChannel(panel, tabs, dropdown, "System");
        addChannel(panel, tabs, dropdown, "#alpha");
        addChannel(panel, tabs, dropdown, "bob");
        addChannel(panel, tabs, dropdown, "#gamma");
        dropdown.setSelectedIndex(2); // "bob" is the active buffer

        panel.renameChannel("bob", "bob2");

        // The label is replaced in place: new label at the same index, old label gone.
        assertEquals("bob2", dropdown.getItemAt(2));
        for (int i = 0; i < dropdown.getItemCount(); i++) {
            assertNotEquals("stale old label must be gone", "bob", dropdown.getItemAt(i));
        }
        // Order preserved (matches tabs) and the active selection stays on the renamed buffer.
        for (int i = 0; i < tabs.getTabCount(); i++) {
            assertEquals(tabs.getTitleAt(i), dropdown.getItemAt(i));
        }
        assertEquals(2, dropdown.getSelectedIndex());
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.Action;
import javax.swing.JTextField;
import java.awt.event.ActionEvent;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/**
 * Verifies the input box is actually wired to InputHistory: the VK_UP/VK_DOWN key bindings
 * installed by setupShortcuts must resolve to actions that recall history into inputField.
 * The InputHistory logic itself is covered by {@link InputHistoryTest}; this guards the glue
 * (matching action keys, caret handling) that unit tests can't see.
 */
public class IrcPanelInputHistoryTest {

    private static InputHistory history(IrcPanel panel) throws Exception {
        Field field = IrcPanel.class.getDeclaredField("inputHistory");
        field.setAccessible(true);
        return (InputHistory) field.get(panel);
    }

    private static void fire(JTextField input, String actionKey) {
        Action action = input.getActionMap().get(actionKey);
        assertNotNull("action '" + actionKey + "' must be bound", action);
        action.actionPerformed(new ActionEvent(input, ActionEvent.ACTION_PERFORMED, actionKey));
    }

    @Test
    public void upBindingRecallsLastSentMessageAndDownRestoresDraft() throws Exception {
        IrcPanel panel = new IrcPanel();
        panel.inputField = new JTextField();

        Method setupShortcuts = IrcPanel.class.getDeclaredMethod("setupShortcuts");
        setupShortcuts.setAccessible(true);
        setupShortcuts.invoke(panel);

        InputHistory history = history(panel);
        history.add("hello");
        history.add("world");

        // User has typed an unsent draft, then presses Up.
        panel.inputField.setText("draft");
        fire(panel.inputField, "historyPrevious");
        assertEquals("world", panel.inputField.getText());
        assertEquals("caret at end", "world".length(), panel.inputField.getCaretPosition());

        fire(panel.inputField, "historyPrevious");
        assertEquals("hello", panel.inputField.getText());

        // Down back down past the newest restores the stashed draft.
        fire(panel.inputField, "historyNext");
        assertEquals("world", panel.inputField.getText());
        fire(panel.inputField, "historyNext");
        assertEquals("draft", panel.inputField.getText());
    }
}

package com.irc;

import org.junit.Test;

import javax.swing.*;
import java.awt.*;
import java.time.Instant;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertEquals;

/** A channel that fills up while its tab is hidden should open scrolled to the newest message. */
public class IrcChannelScrollTest {

    @Test
    public void backgroundChannelOpensAtTheBottom() throws Exception {
        org.junit.Assume.assumeFalse(GraphicsEnvironment.isHeadless());
        IrcConfig config = new IrcConfig() {
            @Override public String username() { return "tester"; }
            @Override public String password() { return ""; }
        };
        AtomicReference<JFrame> frame = new AtomicReference<>();
        AtomicReference<JTabbedPane> tabs = new AtomicReference<>();
        AtomicReference<JScrollPane> scroll = new AtomicReference<>();
        try {
            SwingUtilities.invokeAndWait(() -> {
                IrcPanel.ChannelPane system = new IrcPanel.ChannelPane(new Font("SansSerif", Font.PLAIN, 12), config, null);
                IrcPanel.ChannelPane pane = new IrcPanel.ChannelPane(new Font("SansSerif", Font.PLAIN, 12), config, null);
                JTabbedPane tabbedPane = new JTabbedPane();
                tabbedPane.addTab("System", new JScrollPane(system));
                JScrollPane scrollPane = new JScrollPane(pane);
                tabbedPane.addTab("#busy", scrollPane);
                JFrame f = new JFrame();
                f.add(tabbedPane);
                f.setSize(400, 300);
                for (int i = 0; i < 80; i++) {
                    pane.appendMessage(new IrcMessage("#busy", "bob", "message " + i,
                            IrcMessage.MessageType.CHAT, Instant.now()), config);
                }
                frame.set(f);
                tabs.set(tabbedPane);
                scroll.set(scrollPane);
            });
            flush();
            // The chat may not be on screen at all while messages arrive (e.g. another sidebar panel is open).
            SwingUtilities.invokeAndWait(() -> frame.get().setVisible(true));
            flush();
            SwingUtilities.invokeAndWait(() -> tabs.get().setSelectedIndex(1));
            flush();
            SwingUtilities.invokeAndWait(() -> {
                JScrollBar bar = scroll.get().getVerticalScrollBar();
                assertEquals(bar.getMaximum(), bar.getValue() + bar.getVisibleAmount());
            });
        } finally {
            SwingUtilities.invokeAndWait(() -> { if (frame.get() != null) frame.get().dispose(); });
        }
    }

    // Rendering and scrolling are queued with invokeLater, sometimes more than one deep.
    private static void flush() throws Exception {
        for (int i = 0; i < 5; i++) SwingUtilities.invokeAndWait(() -> {});
    }
}

package com.irc;

import com.google.common.cache.Cache;
import okhttp3.OkHttpClient;
import org.junit.Before;
import org.junit.Test;

import javax.imageio.ImageIO;
import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import javax.swing.event.HyperlinkEvent;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.ByteArrayOutputStream;
import java.lang.reflect.Field;
import java.net.URL;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertTrue;

public class IrcPanelPopOutPreviewTest {
    private static final String IMAGE_URL = "https://example.com/preview.png";

    @Before
    public void requiresDesktop() {
        org.junit.Assume.assumeFalse(java.awt.GraphicsEnvironment.isHeadless());
    }

    @Test
    public void previewShowsDocked() throws Exception {
        assertTrue("preview should show docked", previewShown(true, false));
    }

    @Test
    public void previewShowsInPopOutWithSidebarEnabled() throws Exception {
        assertTrue("preview should show in the pop-out", previewShown(true, true));
    }

    @Test
    public void previewShowsInPopOutWithSidebarDisabled() throws Exception {
        assertTrue("preview should show in the pop-out", previewShown(false, true));
    }

    private boolean previewShown(boolean sidebarInWindow, boolean poppedOut) throws Exception {
        AtomicReference<IrcPanel> panelRef = new AtomicReference<>();
        AtomicReference<JFrame> mainRef = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            IrcPanel panel = new IrcPanel();
            panelRef.set(panel);
            setField(IrcPanel.class, panel, "config", new IrcConfig() {
                @Override public String username() { return "tester"; }
                @Override public String password() { return ""; }
                @Override public boolean hoverPreviewImages() { return true; }
            });
            setField(IrcPanel.class, panel, "okHttpClient", new OkHttpClient());
            panel.init((channel, text) -> {}, (channel, password) -> {}, channel -> {},
                    reconnect -> {}, query -> {}, () -> {});
            panel.initializeGui();
            if (sidebarInWindow) {
                JFrame main = new JFrame();
                mainRef.set(main);
                main.add(panel.getWrappedPanel());
                main.setSize(260, 600);
                main.setVisible(true);
            }
            panel.addChannel("#test");
        });
        try {
            SwingUtilities.invokeAndWait(() -> {
                IrcPanel panel = panelRef.get();
                panel.setFocusedChannel("#test");
                if (poppedOut) panel.setDetached(true, false);
            });
            // Let window activation events from opening the frames arrive before hovering.
            Thread.sleep(1000);
            SwingUtilities.invokeAndWait(() -> {
                IrcPanel panel = panelRef.get();
                IrcPanel.ChannelPane pane = panel.getChannelPanes().get("#test");
                seedCache(pane);
                try {
                    MouseEvent move = new MouseEvent(pane, MouseEvent.MOUSE_MOVED,
                            System.currentTimeMillis(), 0, 10, 10, 0, false);
                    pane.fireHyperlinkUpdate(new HyperlinkEvent(pane, HyperlinkEvent.EventType.ENTERED,
                            new URL(IMAGE_URL), null, null, move));
                } catch (Exception e) {
                    throw new AssertionError(e);
                }
            });
            long deadline = System.currentTimeMillis() + 3000;
            AtomicBoolean shown = new AtomicBoolean();
            while (System.currentTimeMillis() < deadline) {
                SwingUtilities.invokeAndWait(() -> shown.set(currentPopup(panelRef.get()) != null));
                if (shown.get()) return true;
                Thread.sleep(50);
            }
            return false;
        } finally {
            SwingUtilities.invokeAndWait(() -> {
                panelRef.get().shutdown();
                if (mainRef.get() != null) mainRef.get().dispose();
            });
        }
    }

    @SuppressWarnings("unchecked")
    private static void seedCache(IrcPanel.ChannelPane pane) {
        try {
            BufferedImage image = new BufferedImage(40, 40, BufferedImage.TYPE_INT_RGB);
            ByteArrayOutputStream bytes = new ByteArrayOutputStream();
            ImageIO.write(image, "png", bytes);
            PreviewManager manager = (PreviewManager) getField(IrcPanel.ChannelPane.class, pane, "previewManager");
            ((Cache<String, byte[]>) getField(PreviewManager.class, manager, "imageCache"))
                    .put(IMAGE_URL, bytes.toByteArray());
        } catch (Exception e) {
            throw new AssertionError(e);
        }
    }

    private static Object currentPopup(IrcPanel panel) {
        IrcPanel.ChannelPane pane = panel.getChannelPanes().get("#test");
        PreviewManager manager = (PreviewManager) getField(IrcPanel.ChannelPane.class, pane, "previewManager");
        return getField(PreviewManager.class, manager, "currentImagePreview");
    }

    private static Object getField(Class<?> type, Object target, String name) {
        try {
            Field field = type.getDeclaredField(name);
            field.setAccessible(true);
            return field.get(target);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }

    private static void setField(Class<?> type, Object target, String name, Object value) {
        try {
            Field field = type.getDeclaredField(name);
            field.setAccessible(true);
            field.set(target, value);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }
}

package com.irc;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Nick sanitising for /nick and its chatbox form ;;nick.
 *
 * Users routinely type a nick with a space in it. A space cannot reach the wire: setNick sends
 * "NICK " + nick as a single raw line, so "foo bar" would go out as NICK with two parameters and
 * the server would silently take only "foo". The old code dodged that by refusing multi-word input
 * outright, which looked to the user like the command did nothing at all.
 *
 * Runs of whitespace collapse to ONE underscore rather than one per character - "foo   bar" becomes
 * "foo_bar", not "foo___bar". A triple underscore is not what anyone typing three spaces meant, and
 * nicks are length-capped by the server.
 */
public class IrcPluginNickTest {

    @Test
    public void replacesASingleSpaceWithAnUnderscore() {
        assertEquals("foo_bar", IrcPlugin.sanitizeNick("foo bar"));
    }

    /** Each separate gap becomes its own underscore. */
    @Test
    public void replacesEverySeparateSpace() {
        assertEquals("a_b_c", IrcPlugin.sanitizeNick("a b c"));
    }

    /** A run of spaces is one gap, so it collapses to one underscore. */
    @Test
    public void collapsesRunsOfSpacesToASingleUnderscore() {
        assertEquals("foo_bar", IrcPlugin.sanitizeNick("foo   bar"));
    }

    /** Surrounding whitespace is not part of the name, so it is trimmed rather than converted. */
    @Test
    public void trimsSurroundingWhitespaceInsteadOfConvertingIt() {
        assertEquals("foo", IrcPlugin.sanitizeNick("  foo  "));
        assertEquals("foo_bar", IrcPlugin.sanitizeNick("  foo bar  "));
    }

    @Test
    public void leavesAValidNickUntouched() {
        assertEquals("Ryan", IrcPlugin.sanitizeNick("Ryan"));
        assertEquals("guthix_", IrcPlugin.sanitizeNick("guthix_"));
        assertEquals("[bot]", IrcPlugin.sanitizeNick("[bot]"));
    }

    /** Tabs are whitespace too and would break the wire format the same way a space does. */
    @Test
    public void convertsNonSpaceWhitespace() {
        assertEquals("foo_bar", IrcPlugin.sanitizeNick("foo\tbar"));
        assertEquals("foo_bar", IrcPlugin.sanitizeNick("foo \t bar"));
    }

    /** Nothing usable in, nothing out - the caller declines to send rather than sending "NICK _". */
    @Test
    public void yieldsEmptyForNothingUsable() {
        assertEquals("", IrcPlugin.sanitizeNick(""));
        assertEquals("", IrcPlugin.sanitizeNick("   "));
        assertEquals("", IrcPlugin.sanitizeNick("\t"));
        assertEquals("", IrcPlugin.sanitizeNick(null));
    }

    /** The result must never contain whitespace - that is the whole point. */
    @Test
    public void resultNeverContainsWhitespace() {
        String[] inputs = {"foo bar", "a b c", "foo   bar", "  x  y  ", "foo\tbar"};
        for (String input : inputs) {
            String result = IrcPlugin.sanitizeNick(input);
            assertEquals("whitespace survived sanitising of \"" + input + "\": \"" + result + "\"",
                    -1, indexOfWhitespace(result));
        }
    }

    private static int indexOfWhitespace(String value) {
        for (int i = 0; i < value.length(); i++) {
            if (Character.isWhitespace(value.charAt(i))) {
                return i;
            }
        }
        return -1;
    }
}

package com.irc;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

/**
 * Guards the mIRC color-code to HTML-color mapping used when rendering messages.
 * Codes 0-15 are the classic palette; 16-98 are the extended palette from the
 * modern IRC formatting spec (https://modern.ircdocs.horse/formatting.html). Code
 * 99 is "default" and anything out of range falls back to black.
 */
public class IrcColorCodeTest {

    @Test
    public void classicPaletteIsUnchanged() {
        assertEquals("white", IrcPanel.ChannelPane.htmlColorById("0"));
        assertEquals("black", IrcPanel.ChannelPane.htmlColorById("1"));
        assertEquals("black", IrcPanel.ChannelPane.htmlColorById("01"));
        assertEquals("#008080", IrcPanel.ChannelPane.htmlColorById("10"));
        assertEquals("#C0C0C0", IrcPanel.ChannelPane.htmlColorById("15"));
    }

    @Test
    public void extendedPaletteBoundariesMapToSpecValues() {
        assertEquals("#470000", IrcPanel.ChannelPane.htmlColorById("16"));
        assertEquals("#FFFFFF", IrcPanel.ChannelPane.htmlColorById("98"));
    }

    @Test
    public void extendedPaletteInteriorValuesMapToSpecValues() {
        assertEquals("#FF0000", IrcPanel.ChannelPane.htmlColorById("52"));
        assertEquals("#000000", IrcPanel.ChannelPane.htmlColorById("88"));
        assertEquals("#B5B500", IrcPanel.ChannelPane.htmlColorById("42"));
    }

    @Test
    public void defaultAndOutOfRangeCodesFallBackToBlack() {
        assertEquals("black", IrcPanel.ChannelPane.htmlColorById("99"));
        assertEquals("black", IrcPanel.ChannelPane.htmlColorById("100"));
        assertEquals("black", IrcPanel.ChannelPane.htmlColorById("notacode"));
    }
}

package com.irc;

import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/**
 * The channel browser's data layer, kept out of the JDialog so it is testable without a Window.
 *
 * The Users column must report Integer.class: that is the single thing that makes TableRowSorter
 * sort it numerically rather than lexically, and lexical order would rank 9 above 412 - the exact
 * question a channel browser exists to answer. Topics arrive with IRC colour codes in them and are
 * stripped for display, so the filter has to match what the user can actually see.
 */
public class ChannelListTableModelTest {

    private static final String COLOR = String.valueOf((char) 0x03);

    private static List<ChannelListEntry> sample() {
        return Arrays.asList(
                new ChannelListEntry("#help", 412, "Get help here"),
                new ChannelListEntry("#chat", 380, "General chatter"),
                new ChannelListEntry("#quest", 9, "Quest guides and help"));
    }

    private static ChannelListTableModel modelWith(List<ChannelListEntry> entries) {
        ChannelListTableModel model = new ChannelListTableModel();
        model.setEntries(entries);
        return model;
    }

    /** The whole reason the browser is usable: 412 must outrank 9. */
    @Test
    public void usersColumnIsIntegerSoItSortsNumerically() {
        ChannelListTableModel model = modelWith(sample());
        assertEquals(Integer.class, model.getColumnClass(1));
        assertEquals(String.class, model.getColumnClass(0));
        assertEquals(String.class, model.getColumnClass(2));
    }

    @Test
    public void exposesThreeColumnsInOrder() {
        ChannelListTableModel model = modelWith(sample());
        assertEquals(3, model.getColumnCount());
        assertEquals("Channel", model.getColumnName(0));
        assertEquals("Users", model.getColumnName(1));
        assertEquals("Topic", model.getColumnName(2));
    }

    @Test
    public void rowsExposeNameCountAndTopic() {
        ChannelListTableModel model = modelWith(sample());
        assertEquals(3, model.getRowCount());
        assertEquals("#help", model.getValueAt(0, 0));
        assertEquals(412, model.getValueAt(0, 1));
        assertEquals("Get help here", model.getValueAt(0, 2));
    }

    @Test
    public void stripsFormattingCodesFromDisplayedTopics() {
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#styled", 3, COLOR + "04,5Bright" + COLOR + " topic")));
        assertEquals("Bright topic", model.getValueAt(0, 2));
    }

    @Test
    public void filterMatchesChannelName() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("quest");
        assertEquals(1, model.getRowCount());
        assertEquals("#quest", model.getValueAt(0, 0));
    }

    @Test
    public void filterMatchesTopicText() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("chatter");
        assertEquals(1, model.getRowCount());
        assertEquals("#chat", model.getValueAt(0, 0));
    }

    @Test
    public void filterIsCaseInsensitive() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("QUEST");
        assertEquals(1, model.getRowCount());
    }

    @Test
    public void emptyFilterShowsEverything() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("quest");
        model.setFilter("");
        assertEquals(3, model.getRowCount());
    }

    /** A filter typed against a styled topic must match the stripped text the user sees. */
    @Test
    public void filterMatchesStrippedTopicNotRawCodes() {
        // The needle straddles the code: "Br" + code + "ight" is not a contiguous "Bright" in the
        // raw text, only in the stripped text. A fixture where the code sits wholly before or
        // after the needle would pass even if the filter searched the raw string.
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#styled", 3, "Br" + COLOR + "04" + "ight topic")));
        model.setFilter("Bright");
        assertEquals(1, model.getRowCount());
    }

    @Test
    public void reportsTotalAndShownCounts() {
        ChannelListTableModel model = modelWith(sample());
        assertEquals(3, model.getTotalCount());
        assertEquals(3, model.getShownCount());

        model.setFilter("quest");
        assertEquals(3, model.getTotalCount());
        assertEquals(1, model.getShownCount());
    }

    /** Joining acts on the entry behind a row, so the mapping must survive filtering. */
    @Test
    public void getEntryAtTracksTheFilteredView() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("quest");
        assertEquals("#quest", model.getEntryAt(0).getName());
    }

    @Test
    public void replacingEntriesReappliesTheActiveFilter() {
        ChannelListTableModel model = modelWith(sample());
        model.setFilter("quest");
        assertEquals(1, model.getRowCount());

        model.setEntries(Arrays.asList(
                new ChannelListEntry("#questing", 5, "more quests"),
                new ChannelListEntry("#other", 5, "unrelated")));
        assertEquals(1, model.getRowCount());
        assertEquals("#questing", model.getValueAt(0, 0));
    }

    @Test
    public void handlesEmptyResults() {
        ChannelListTableModel model = modelWith(Collections.emptyList());
        assertEquals(0, model.getRowCount());
        assertEquals(0, model.getTotalCount());
    }

    @Test
    public void matchesPredicateHandlesNullAndBlankFilters() {
        ChannelListEntry entry = new ChannelListEntry("#help", 1, "topic");
        assertTrue(ChannelListTableModel.matches(entry, null));
        assertTrue(ChannelListTableModel.matches(entry, ""));
        assertTrue(ChannelListTableModel.matches(entry, "   "));
        assertFalse(ChannelListTableModel.matches(entry, "nomatch"));
    }

    @Test
    public void toleratesNullTopics() {
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#notopic", 2, null)));
        assertEquals("", model.getValueAt(0, 2));
        model.setFilter("notopic");
        assertEquals(1, model.getRowCount());
    }

    /**
     * Whole-branch review finding: the class doc claimed topics were stripped "once, up front" and
     * they were not - stripCodes ran on every getValueAt and on every entry inside applyFilter, so
     * a filter keystroke was one regex pass per row. At the 20,000-row cap that is 20,000 regex
     * passes per character typed, on the EDT.
     *
     * Identity is the observable consequence of the fix: stripCodes goes through
     * Matcher.replaceAll, which allocates a new String whenever it actually removes something, so
     * a topic that contains codes can only yield the same instance twice if it was computed once
     * and kept. A topic with no codes would pass either way (replaceAll returns the input), hence
     * the deliberately styled fixture.
     */
    @Test
    public void strippedTopicsAreComputedOncePerEntry() {
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#styled", 3, COLOR + "04Bright" + COLOR + " topic")));

        Object first = model.getValueAt(0, 2);
        assertEquals("Bright topic", first);
        assertSame("repainting a cell must not re-run the stripper", first, model.getValueAt(0, 2));
    }

    /** Filtering must reuse the precomputed rows rather than rebuild them per keystroke. */
    @Test
    public void filteringDoesNotRecomputeStrippedTopics() {
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#styled", 3, COLOR + "04Bright" + COLOR + " topic")));
        Object before = model.getValueAt(0, 2);

        model.setFilter("bright");
        model.setFilter("br");
        model.setFilter("");

        assertEquals(1, model.getRowCount());
        assertSame("each keystroke must reuse the row stripped when the entries were set",
                before, model.getValueAt(0, 2));
    }

    /** Replacing the entries must restrip: the new rows are different objects entirely. */
    @Test
    public void replacingEntriesRestripsTheNewTopics() {
        ChannelListTableModel model = modelWith(Collections.singletonList(
                new ChannelListEntry("#one", 1, COLOR + "04first")));
        assertEquals("first", model.getValueAt(0, 2));

        model.setEntries(Collections.singletonList(
                new ChannelListEntry("#two", 2, COLOR + "04second")));
        assertEquals("second", model.getValueAt(0, 2));
    }
}

package com.irc;

import org.junit.Test;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import static org.junit.Assert.*;

public class SimpleIrcClientTest {

    @Test
    public void historyBatchEventCarriesMessages() {
        SimpleIrcClient.IrcEvent inner = new SimpleIrcClient.IrcEvent(
            SimpleIrcClient.IrcEvent.Type.MESSAGE, "nick", "#chan", "hello", "2024-01-01T12:00:00.000Z"
        );
        List<SimpleIrcClient.IrcEvent> batch = List.of(inner);

        SimpleIrcClient.IrcEvent batchEvent = new SimpleIrcClient.IrcEvent(
            SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH, null, "#chan", null, null, batch
        );

        assertEquals(SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH, batchEvent.getType());
        assertEquals("#chan", batchEvent.getTarget());
        assertNotNull(batchEvent.getHistoryMessages());
        assertEquals(1, batchEvent.getHistoryMessages().size());
        assertEquals("hello", batchEvent.getHistoryMessages().get(0).getMessage());
    }

    @Test
    public void existingFiveArgConstructorSetsHistoryMessagesToNull() {
        SimpleIrcClient.IrcEvent event = new SimpleIrcClient.IrcEvent(
            SimpleIrcClient.IrcEvent.Type.MESSAGE, "nick", "#chan", "hello", null
        );
        assertNull(event.getHistoryMessages());
    }

    @Test
    public void tagParsingExtractsTimeAndBatch() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine("@time=2024-01-01T12:00:00.000Z;batch=ref1 :nick!user@host PRIVMSG #chan :hello");
        assertEquals("2024-01-01T12:00:00.000Z", client.getLastTagTime());
        assertEquals("ref1", client.getLastTagBatch());
    }

    @Test
    public void noTagsLeavesFieldsNull() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":nick!user@host PRIVMSG #chan :hello");
        assertNull(client.getLastTagTime());
        assertNull(client.getLastTagBatch());
    }

    @Test
    public void capLsWithChathistoryRequestsCaps() {
        TestableIrcClient client = new TestableIrcClient();
        // Final LS line (no continuation *): params = [*, LS, cap-list]
        client.processLine(":server CAP * LS :chathistory batch server-time");
        assertTrue(client.sentLines.stream().anyMatch(l -> l.startsWith("CAP REQ")));
        assertTrue(client.sentLines.stream().anyMatch(l -> l.contains("chathistory")));
    }

    @Test
    public void capLsWithCapValueStillRequestsChathistory() {
        TestableIrcClient client = new TestableIrcClient();
        // Server advertises chathistory with a value (e.g. max limit)
        client.processLine(":server CAP * LS :chathistory=50 batch server-time");
        assertTrue(client.sentLines.stream().anyMatch(l -> l.startsWith("CAP REQ")));
        assertTrue(client.sentLines.stream().anyMatch(l -> l.contains("chathistory")));
    }

    @Test
    public void capLsWithoutChathistorySendsCapEnd() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":server CAP * LS :multi-prefix");
        assertTrue(client.sentLines.contains("CAP END"));
        assertFalse(client.isCapHistorySupported());
    }

    @Test
    public void capAckWithChathistorySetsFlag() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":server CAP * LS :chathistory batch server-time");
        client.sentLines.clear();
        client.processLine(":server CAP * ACK :chathistory batch server-time");
        assertTrue(client.isCapHistorySupported());
        assertTrue(client.sentLines.contains("CAP END"));
    }

    @Test
    public void capNakSendsCapEndAndLeavesHistoryUnsupported() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":server CAP * LS :chathistory");
        client.sentLines.clear();
        client.processLine(":server CAP * NAK :chathistory batch server-time");
        assertFalse(client.isCapHistorySupported());
        assertTrue(client.sentLines.contains("CAP END"));
    }

    @Test
    public void capEndSentOnlyOnce() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":server CAP * LS :chathistory");
        client.processLine(":server CAP * ACK :chathistory");
        client.processLine(":server CAP * ACK :batch"); // second ACK line
        long count = client.sentLines.stream().filter("CAP END"::equals).count();
        assertEquals(1, count);
    }

    @Test
    public void multiLineCapLsAccumulatesBeforeSendingReq() {
        TestableIrcClient client = new TestableIrcClient();
        // Continuation line — has * before the cap list
        client.processLine(":server CAP * LS * :batch server-time");
        assertTrue(client.sentLines.isEmpty()); // no CAP REQ yet
        // Final line — no continuation *
        client.processLine(":server CAP * LS :chathistory");
        assertTrue(client.sentLines.stream().anyMatch(l -> l.contains("chathistory")));
    }

    @Test
    public void batchAccumulatesMessagesAndFiresHistoryBatchEvent() {
        TestableIrcClient client = new TestableIrcClient();
        List<SimpleIrcClient.IrcEvent> received = new ArrayList<>();
        client.addEventListener(event -> {
            if (event.getType() == SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH) {
                received.add(event);
            }
        });

        client.processLine(":server BATCH +ref1 chathistory #chan");
        client.processLine("@time=2024-01-01T10:00:00.000Z;batch=ref1 :alice!a@host PRIVMSG #chan :hello");
        client.processLine("@time=2024-01-01T10:01:00.000Z;batch=ref1 :bob!b@host PRIVMSG #chan :world");
        client.processLine(":server BATCH -ref1");

        assertEquals(1, received.size());
        SimpleIrcClient.IrcEvent batch = received.get(0);
        assertEquals("#chan", batch.getTarget());
        assertEquals(2, batch.getHistoryMessages().size());
        assertEquals("hello", batch.getHistoryMessages().get(0).getMessage());
        assertEquals("2024-01-01T10:00:00.000Z", batch.getHistoryMessages().get(0).getAdditionalData());
        assertEquals("world", batch.getHistoryMessages().get(1).getMessage());
    }

    @Test
    public void batchTaggedMessageDoesNotFireNormalMessageEvent() {
        TestableIrcClient client = new TestableIrcClient();
        List<SimpleIrcClient.IrcEvent> messages = new ArrayList<>();
        client.addEventListener(event -> {
            if (event.getType() == SimpleIrcClient.IrcEvent.Type.MESSAGE) {
                messages.add(event);
            }
        });

        client.processLine(":server BATCH +ref1 chathistory #chan");
        client.processLine("@batch=ref1 :alice!a@host PRIVMSG #chan :hello");
        client.processLine(":server BATCH -ref1");

        assertTrue("Batch-tagged PRIVMSG should not fire a normal MESSAGE event", messages.isEmpty());
    }

    @Test
    public void actionInBatchUsesSourceWithoutStarPrefix() {
        TestableIrcClient client = new TestableIrcClient();
        List<SimpleIrcClient.IrcEvent> received = new ArrayList<>();
        client.addEventListener(event -> {
            if (event.getType() == SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH) received.add(event);
        });

        client.processLine(":server BATCH +ref1 chathistory #chan");
        client.processLine("@batch=ref1 :alice!a@host PRIVMSG #chan :\u0001ACTION waves\u0001");
        client.processLine(":server BATCH -ref1");

        SimpleIrcClient.IrcEvent batch = received.get(0);
        assertEquals(SimpleIrcClient.IrcEvent.Type.ACTION, batch.getHistoryMessages().get(0).getType());
        assertEquals("alice", batch.getHistoryMessages().get(0).getSource()); // no "* " prefix
        assertEquals("waves", batch.getHistoryMessages().get(0).getMessage());
    }

    @Test
    public void disconnectClearsBatchState() {
        TestableIrcClient client = new TestableIrcClient();
        client.processLine(":server BATCH +ref1 chathistory #chan");
        client.disconnect();
        List<SimpleIrcClient.IrcEvent> received = new ArrayList<>();
        client.addEventListener(event -> {
            if (event.getType() == SimpleIrcClient.IrcEvent.Type.HISTORY_BATCH) received.add(event);
        });
        client.processLine(":server BATCH +ref1 chathistory #chan");
        client.processLine("@batch=ref1 :alice!a@host PRIVMSG #chan :hello");
        client.processLine(":server BATCH -ref1");
        assertEquals(1, received.size());
    }

    @Test
    public void selfJoinRequestsChatHistoryWhenSupported() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.setCapHistorySupportedForTest(true);
        client.processLine(":TestUser!u@host JOIN #chan");
        assertTrue(client.sentLines.stream().anyMatch(l -> l.equals("CHATHISTORY LATEST #chan * 100")));
    }

    @Test
    public void selfJoinDoesNotRequestHistoryWhenUnsupported() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.processLine(":TestUser!u@host JOIN #chan");
        assertFalse(client.sentLines.stream().anyMatch(l -> l.startsWith("CHATHISTORY")));
    }

    @Test
    public void otherUserJoinDoesNotRequestHistory() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.setCapHistorySupportedForTest(true);
        client.processLine(":OtherUser!u@host JOIN #chan");
        assertFalse(client.sentLines.stream().anyMatch(l -> l.startsWith("CHATHISTORY")));
    }

    @Test
    public void capLsWithSaslRequestsSaslWhenPasswordSet() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("acct", "secret");
        client.processLine(":server CAP * LS :sasl chathistory batch");
        assertTrue(client.sentLines.stream().anyMatch(l -> l.startsWith("CAP REQ") && l.contains("sasl")));
    }

    @Test
    public void capLsDoesNotRequestSaslWhenNoPassword() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        // No sasl() call, so SASL is disabled.
        client.processLine(":server CAP * LS :sasl chathistory");
        assertTrue(client.sentLines.stream().noneMatch(l -> l.contains("sasl")));
    }

    @Test
    public void capAckWithSaslSendsAuthenticatePlainAndDefersCapEnd() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("acct", "secret");
        client.processLine(":server CAP * LS :sasl chathistory");
        client.sentLines.clear();
        client.processLine(":server CAP * ACK :sasl chathistory");
        assertTrue(client.sentLines.contains("AUTHENTICATE PLAIN"));
        assertFalse("CAP END must wait until SASL completes", client.sentLines.contains("CAP END"));
    }

    @Test
    public void authenticatePlusSendsBase64PlainCredentials() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("myaccount", "secret");
        client.processLine("AUTHENTICATE +");

        String authLine = client.sentLines.stream()
                .filter(l -> l.startsWith("AUTHENTICATE ") && !l.equals("AUTHENTICATE PLAIN"))
                .reduce((a, b) -> b).orElse(null);
        assertNotNull("client should send an AUTHENTICATE payload", authLine);

        String decoded = new String(
                Base64.getDecoder().decode(authLine.substring("AUTHENTICATE ".length())),
                StandardCharsets.UTF_8);
        assertEquals("\0myaccount\0secret", decoded);
    }

    @Test
    public void authenticateUsesNickAsAuthcidWhenAccountBlank() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("", "secret");
        client.processLine("AUTHENTICATE +");

        String authLine = client.sentLines.stream()
                .filter(l -> l.startsWith("AUTHENTICATE ") && !l.equals("AUTHENTICATE PLAIN"))
                .reduce((a, b) -> b).orElse(null);
        assertNotNull(authLine);

        String decoded = new String(
                Base64.getDecoder().decode(authLine.substring("AUTHENTICATE ".length())),
                StandardCharsets.UTF_8);
        assertEquals("\0TestUser\0secret", decoded);
    }

    @Test
    public void saslSuccessNumericSendsCapEndAndFiresEvent() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("acct", "secret");
        List<SimpleIrcClient.IrcEvent> events = new ArrayList<>();
        client.addEventListener(e -> {
            if (e.getType() == SimpleIrcClient.IrcEvent.Type.SASL_SUCCESS) events.add(e);
        });
        client.processLine(":server CAP * LS :sasl");
        client.processLine(":server CAP * ACK :sasl");
        client.sentLines.clear();
        client.processLine(":server 903 TestUser :SASL authentication successful");
        assertTrue(client.sentLines.contains("CAP END"));
        assertEquals(1, events.size());
    }

    @Test
    public void saslFailureNumericSendsCapEndAndFiresEvent() {
        TestableIrcClient client = new TestableIrcClient();
        client.credentials("TestUser", "user", "user");
        client.sasl("acct", "secret");
        List<SimpleIrcClient.IrcEvent> events = new ArrayList<>();
        client.addEventListener(e -> {
            if (e.getType() == SimpleIrcClient.IrcEvent.Type.SASL_FAILED) events.add(e);
        });
        client.processLine(":server CAP * LS :sasl");
        client.processLine(":server CAP * ACK :sasl");
        client.sentLines.clear();
        client.processLine(":server 904 TestUser :SASL authentication failed");
        assertTrue("must send CAP END to continue registration even on SASL failure",
                client.sentLines.contains("CAP END"));
        assertEquals(1, events.size());
    }

    /** Test subclass that captures sent lines and exposes internal state. */
    static class TestableIrcClient extends SimpleIrcClient {
        final List<String> sentLines = new ArrayList<>();

        @Override
        public synchronized void sendRawLine(String line) {
            sentLines.add(line);
        }

        String getLastTagTime() { return currentTagTime; }
        String getLastTagBatch() { return currentTagBatch; }
        boolean isCapHistorySupported() { return capHistorySupported; }

        void setCapHistorySupportedForTest(boolean val) {
            capHistorySupported = val;
        }
    }
}

package com.irc;

import org.junit.Before;
import org.junit.Test;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/**
 * Per-channel roster of who is present and what membership modes they hold.
 *
 * Fed by NAMES (353/366), JOIN, PART, QUIT, KICK, NICK and MODE. The interesting cases are
 * parameter alignment in compound MODE strings, NAMES replacing rather than merging, and
 * QUIT/NICK reporting which channels they touched so only those get redrawn.
 */
public class ChannelUserListTest {

    private ChannelUserList users;

    @Before
    public void setUp() {
        users = new ChannelUserList(ModeSpec.defaults());
    }

    /** Loads a roster the way the protocol does: one or more 353 lines, then a 366. */
    private void names(String channel, String... rawEntries) {
        users.addNames(channel, Arrays.asList(rawEntries));
        users.endNames(channel);
    }

    private List<String> nicks(String channel) {
        List<String> result = new java.util.ArrayList<>();
        for (ChannelUserList.Entry entry : users.snapshot(channel)) {
            result.add(entry.getPrefix() + entry.getNick());
        }
        return result;
    }

    @Test
    public void prefixOfReturnsTheHighestPrefixCaseInsensitively() {
        names("#Chan", "@+bob", "+dave", "erin");
        assertEquals("@", users.prefixOf("#chan", "BOB"));
        assertEquals("+", users.prefixOf("#chan", "dave"));
        assertEquals("", users.prefixOf("#chan", "erin"));
    }

    @Test
    public void prefixOfIsEmptyForUnknownNicksAndChannels() {
        names("#chan", "@bob");
        assertEquals("", users.prefixOf("#chan", "nobody"));
        assertEquals("", users.prefixOf("#other", "bob"));
        assertEquals("", users.prefixOf("bob", "bob"));
    }

    @Test
    public void namesPopulatesUsersAndTheirPrefixes() {
        names("#chan", "@bob", "+dave", "erin");
        assertEquals(Arrays.asList("@bob", "+dave", "erin"), nicks("#chan"));
    }

    @Test
    public void namesHandlesMultiplePrefixesAndShowsTheHighest() {
        names("#chan", "@+bob");
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void multiplePrefixesAreAllRetainedSoRevokingOneLeavesTheOther() {
        names("#chan", "@+bob");
        users.applyModeChange("#chan", Arrays.asList("-o", "bob"));
        assertEquals("voice survives losing op", Collections.singletonList("+bob"), nicks("#chan"));
    }

    @Test
    public void namesAcrossMultipleLinesAccumulateBeforeTheCommit() {
        users.addNames("#chan", Arrays.asList("@bob", "+dave"));
        users.addNames("#chan", Collections.singletonList("erin"));
        users.endNames("#chan");
        assertEquals(Arrays.asList("@bob", "+dave", "erin"), nicks("#chan"));
    }

    @Test
    public void aSecondNamesRoundReplacesRatherThanMerges() {
        names("#chan", "@bob", "+dave", "erin");
        names("#chan", "@bob");
        assertEquals("stale users are dropped", Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void endNamesWithoutPendingIsANoOp() {
        names("#chan", "@bob");
        users.endNames("#chan");
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void joinAddsAnUnprivilegedUser() {
        names("#chan", "@bob");
        users.join("#chan", "erin");
        assertEquals(Arrays.asList("@bob", "erin"), nicks("#chan"));
    }

    @Test
    public void partRemovesTheUser() {
        names("#chan", "@bob", "erin");
        users.part("#chan", "erin");
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void kickRemovesTheUser() {
        names("#chan", "@bob", "erin");
        users.kick("#chan", "erin");
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void quitRemovesTheUserFromEveryChannelAndReportsWhich() {
        names("#one", "erin", "bob");
        names("#two", "erin");
        names("#three", "bob");

        List<String> affected = users.quit("erin");

        assertEquals(2, affected.size());
        assertTrue(affected.contains("#one"));
        assertTrue(affected.contains("#two"));
        assertEquals(Collections.singletonList("bob"), nicks("#one"));
        assertEquals(Collections.emptyList(), nicks("#two"));
    }

    @Test
    public void renameKeepsModesAndReportsAffectedChannels() {
        names("#one", "@bob");
        names("#two", "+bob");

        List<String> affected = users.rename("bob", "robert");

        assertEquals(2, affected.size());
        assertEquals(Collections.singletonList("@robert"), nicks("#one"));
        assertEquals(Collections.singletonList("+robert"), nicks("#two"));
    }

    @Test
    public void quitReturnsTheChannelUsingTheServersCasing() {
        // Callers match these against UI state that compares case-sensitively, so the server's
        // casing must survive the lowercased internal key.
        names("#One", "erin");
        assertEquals(Collections.singletonList("#One"), users.quit("erin"));
    }

    @Test
    public void renameReturnsTheChannelUsingTheServersCasing() {
        names("#One", "bob");
        assertEquals(Collections.singletonList("#One"), users.rename("bob", "robert"));
    }

    @Test
    public void channelLookupIsCaseInsensitive() {
        names("#One", "@bob");
        assertEquals(Collections.singletonList("@bob"), nicks("#one"));
    }

    @Test
    public void modeGrantsOp() {
        names("#chan", "bob");
        users.applyModeChange("#chan", Arrays.asList("+o", "bob"));
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void modeRevokesVoice() {
        names("#chan", "+bob");
        users.applyModeChange("#chan", Arrays.asList("-v", "bob"));
        assertEquals(Collections.singletonList("bob"), nicks("#chan"));
    }

    @Test
    public void compoundModeSkipsTheParameterlessLetter() {
        // The regression this whole design exists to prevent: "m" takes no parameter, so "bob"
        // belongs to "o". Getting this wrong ops nobody, or the wrong person.
        names("#chan", "bob");
        users.applyModeChange("#chan", Arrays.asList("+mo", "bob"));
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void mixedSignModeAppliesEachLetterToItsOwnParameter() {
        names("#chan", "bob", "+carol");
        users.applyModeChange("#chan", Arrays.asList("+o-v", "bob", "carol"));
        assertEquals(Arrays.asList("@bob", "carol"), nicks("#chan"));
    }

    @Test
    public void removingATypeCModeConsumesNoParameter() {
        // "l" (limit) takes a parameter when set but not when removed, so the lone parameter
        // "bob" belongs to "+o". An implementation that wrongly consumed one for "-l" would
        // leave "+o" with nothing and fail to op anyone.
        names("#chan", "bob");
        users.applyModeChange("#chan", Arrays.asList("-l+o", "bob"));
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void settingATypeBModeConsumesItsParameter() {
        // "k" (key) always takes a parameter, so "secret" is the key and "bob" belongs to "o".
        names("#chan", "bob");
        users.applyModeChange("#chan", Arrays.asList("+ko", "secret", "bob"));
        assertEquals(Collections.singletonList("@bob"), nicks("#chan"));
    }

    @Test
    public void modeTargetingAnUnknownNickIsIgnored() {
        names("#chan", "bob");
        users.applyModeChange("#chan", Arrays.asList("+o", "nosuchuser"));
        assertEquals(Collections.singletonList("bob"), nicks("#chan"));
    }

    @Test
    public void modeWithMissingParametersDoesNotThrow() {
        names("#chan", "bob");
        users.applyModeChange("#chan", Collections.singletonList("+o"));
        assertEquals(Collections.singletonList("bob"), nicks("#chan"));
    }

    @Test
    public void modeOnAnUnknownChannelIsIgnored() {
        users.applyModeChange("#nosuchchannel", Arrays.asList("+o", "bob"));
        assertEquals(Collections.emptyList(), nicks("#nosuchchannel"));
    }

    @Test
    public void snapshotSortsByRankThenCaseInsensitiveAlphabetically() {
        names("#chan", "zoe", "@Bob", "+dave", "~founder", "Alice", "%carol");
        assertEquals(
                Arrays.asList("~founder", "@Bob", "%carol", "+dave", "Alice", "zoe"),
                nicks("#chan"));
    }

    @Test
    public void nickMatchingIsCaseInsensitiveButDisplayCasingIsKept() {
        names("#chan", "@Bob");
        users.applyModeChange("#chan", Arrays.asList("-o", "bob"));
        assertEquals(Collections.singletonList("Bob"), nicks("#chan"));
    }

    @Test
    public void snapshotIsImmutable() {
        names("#chan", "bob");
        List<ChannelUserList.Entry> snapshot = users.snapshot("#chan");
        try {
            snapshot.add(new ChannelUserList.Entry("evil", "", 0));
            org.junit.Assert.fail("snapshot must not be modifiable");
        } catch (UnsupportedOperationException expected) {
            // the EDT reads this while the socket thread mutates the source
        }
    }

    @Test
    public void snapshotOfAnUnknownChannelIsEmpty() {
        assertEquals(Collections.emptyList(), users.snapshot("#nope"));
    }

    @Test
    public void removeChannelDropsItsRoster() {
        names("#chan", "bob");
        users.removeChannel("#chan");
        assertEquals(Collections.emptyList(), users.snapshot("#chan"));
    }

    @Test
    public void clearDropsEverything() {
        names("#one", "bob");
        names("#two", "erin");
        users.clear();
        assertEquals(Collections.emptyList(), users.snapshot("#one"));
        assertEquals(Collections.emptyList(), users.snapshot("#two"));
    }
}

package com.irc;

import org.junit.Test;
import org.junit.Before;

import javax.swing.JFrame;
import javax.swing.SwingUtilities;
import java.lang.reflect.Field;
import java.time.Instant;
import java.util.Collections;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.*;

public class IrcPanelPopOutTest {
    @Before
    public void requiresDesktop() {
        org.junit.Assume.assumeFalse(java.awt.GraphicsEnvironment.isHeadless());
    }

    @Test
    public void actualChatSendsInBothHostsAndBrowserFollowsItsOwner() throws Exception {
        AtomicReference<IrcPanel> panelRef = new AtomicReference<>();
        AtomicReference<JFrame> mainRef = new AtomicReference<>();
        AtomicReference<String> sent = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> {
            IrcPanel panel = new IrcPanel();
            panelRef.set(panel);
            setField(panel, "config", new IrcConfig() {
                @Override public String username() { return "tester"; }
                @Override public String password() { return ""; }
            });
            panel.init((channel, text) -> sent.set(channel + ":" + text),
                    (channel, password) -> {}, channel -> {}, reconnect -> {}, query -> {}, () -> {});
            panel.initializeGui();
            JFrame main = new JFrame();
            mainRef.set(main);
            main.add(panel.getWrappedPanel());
            main.setSize(260, 600);
            main.setVisible(true);
            panel.addChannel("#test");
            panel.setFocusedChannel("#test");
            panel.addMessage(new IrcMessage("#test", "tester", "test scrollback",
                    IrcMessage.MessageType.CHAT, Instant.now()));
        });
        try {
            SwingUtilities.invokeAndWait(() -> {
                IrcPanel panel = panelRef.get();
                // initializeGui queues the System tab; select after that startup work completes.
                panel.setFocusedChannel("#test");
                IrcPanel.ChannelPane original = panel.getChannelPanes().get("#test");
                assertTrue(original.getText().contains("test scrollback"));
                panel.inputField.setText("my draft");
                panel.showChannelList(Collections.emptyList(), "", false);
                ChannelListDialog dockedBrowser = getBrowser(panel);
                assertSame(mainRef.get(), dockedBrowser.getOwner());

                panel.setDetached(true, false);
                JFrame popOut = (JFrame) SwingUtilities.getWindowAncestor(panel.getChatContent());
                assertNotSame(mainRef.get(), popOut);
                assertTrue(popOut.isVisible());
                assertFalse(dockedBrowser.isDisplayable());
                assertEquals("my draft", panel.inputField.getText());
                assertEquals("#test", panel.getCurrentChannel());
                assertSame(original, panel.getChannelPanes().get("#test"));
                panel.inputField.postActionEvent();
                assertEquals("#test:my draft", sent.get());
                assertEquals("", panel.inputField.getText());

                panel.showChannelList(Collections.emptyList(), "", false);
                ChannelListDialog floatingBrowser = getBrowser(panel);
                assertSame(popOut, floatingBrowser.getOwner());
                panel.setDetached(false, false);
                assertFalse(floatingBrowser.isDisplayable());
                assertFalse(popOut.isDisplayable());
                assertSame(mainRef.get(), SwingUtilities.getWindowAncestor(panel.getChatContent()));
                panel.inputField.setText("docked message");
                panel.inputField.postActionEvent();
                assertEquals("#test:docked message", sent.get());
                assertTrue(original.getText().contains("test scrollback"));
            });
        } finally {
            SwingUtilities.invokeAndWait(() -> {
                panelRef.get().shutdown();
                mainRef.get().dispose();
            });
        }
    }

    private static void setField(IrcPanel panel, String name, Object value) {
        try {
            Field field = IrcPanel.class.getDeclaredField(name);
            field.setAccessible(true);
            field.set(panel, value);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }

    private static ChannelListDialog getBrowser(IrcPanel panel) {
        try {
            Field field = IrcPanel.class.getDeclaredField("channelListDialog");
            field.setAccessible(true);
            return (ChannelListDialog) field.get(panel);
        } catch (ReflectiveOperationException e) {
            throw new AssertionError(e);
        }
    }
}

package com.irc;

import org.junit.Test;

import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;

import static org.junit.Assert.assertNull;

/**
 * Regression test for the data race that produced:
 *
 *   java.lang.ArrayIndexOutOfBoundsException: Index 1 out of bounds for length 1
 *       at java.util.LinkedHashMap.keysToArray
 *       at com.irc.IrcPanel.getChannelNames(IrcPanel.java:67)
 *
 * getChannelNames() snapshots channelPanes.keySet() on the IRC reader thread while
 * the EDT concurrently adds/removes channels. With a non-thread-safe map the snapshot
 * (new ArrayList<>(keySet())) reads size(), allocates an array of that size, then
 * overflows it when another thread inserts mid-copy.
 */
public class IrcPanelConcurrencyTest {

    @Test
    public void getChannelNamesIsSafeUnderConcurrentMutation() throws Exception {
        IrcPanel panel = new IrcPanel();

        final AtomicReference<Throwable> failure = new AtomicReference<>();
        final AtomicBoolean stop = new AtomicBoolean(false);

        // Writer: churns the map the way addChannel()/removeChannel() do.
        Thread writer = new Thread(() -> {
            try {
                for (int round = 0; round < 100_000 && !stop.get(); round++) {
                    for (int i = 0; i < 16; i++) {
                        panel.getChannelPanes().put("#chan" + i, null);
                    }
                    for (int i = 0; i < 16; i++) {
                        panel.getChannelPanes().remove("#chan" + i);
                    }
                }
            } catch (Throwable t) {
                failure.compareAndSet(null, t);
            }
        }, "writer");

        // Reader: snapshots channel names the way processMessage() does on the IRC thread.
        Thread reader = new Thread(() -> {
            try {
                for (int round = 0; round < 100_000 && !stop.get(); round++) {
                    panel.getChannelNames();
                }
            } catch (Throwable t) {
                failure.compareAndSet(null, t);
            }
        }, "reader");

        writer.start();
        reader.start();
        writer.join(30_000);
        reader.join(30_000);
        stop.set(true);
        writer.join();
        reader.join();

        assertNull("getChannelNames() must not throw under concurrent mutation, but got: "
                + failure.get(), failure.get());
    }
}

package com.irc;

import net.runelite.client.util.ImageUtil;

import javax.swing.*;
import javax.swing.tree.DefaultMutableTreeNode;
import javax.swing.tree.DefaultTreeCellRenderer;
import javax.swing.tree.DefaultTreeModel;
import javax.swing.tree.TreePath;
import javax.swing.tree.TreeSelectionModel;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Function;
import java.util.function.Predicate;

/** Expanded navigation around the existing chat components, with no separate IRC state. */
final class IrcDesktopLayout extends JPanel {
    private static final Color BACKGROUND = new Color(30, 33, 38);
    private static final Color HEADER = new Color(40, 44, 50);
    private static final Color TEXT = new Color(218, 222, 229);
    private static final Color MUTED = new Color(155, 163, 176);
    private static final Color ACCENT = new Color(135, 206, 250);
    private final DefaultMutableTreeNode root;
    private final DefaultTreeModel treeModel;
    private final JTree channels;
    private final DefaultListModel<ChannelUserList.Entry> userModel = new DefaultListModel<>();
    private final JList<ChannelUserList.Entry> users = new JList<>(userModel);
    private final JLabel usersHeading = heading("USERS");
    private final JLabel channelHeading = heading("System");
    private final JPanel conversation = new JPanel(new BorderLayout());
    private final JPanel composer = new JPanel(new BorderLayout());
    private final Consumer<String> query;
    private final Consumer<String> whois;
    private List<String> channelNames = Collections.emptyList();
    /** Buffer names as the tree shows them; the numbers Alt+digit and Alt+J jump to. */
    private List<String> channelOrder = Collections.emptyList();
    private final JToggleButton channelsToggle = new JToggleButton("Channel list", true);
    private final JToggleButton usersToggle = new JToggleButton("User list", true);
    private JTextField input;
    private boolean synchronizing;

    IrcDesktopLayout(String server, Predicate<String> unread, Consumer<String> select,
                     Consumer<String> query, Consumer<String> whois, Runnable join,
                     Runnable leave, Runnable browse, Runnable reconnect, Runnable dock,
                     JComboBox<String> fontSelector, JComboBox<Integer> fontSizeSelector,
                     Function<String, Color> nickColor) {
        super(new BorderLayout(0, 1));
        this.query = query;
        this.whois = whois;
        setBackground(HEADER);
        root = new DefaultMutableTreeNode(server);
        treeModel = new DefaultTreeModel(root);
        channels = new JTree(treeModel);
        channels.setName("ircChannels");
        channels.setRowHeight(27);
        channels.setBackground(BACKGROUND);
        channels.setForeground(TEXT);
        channels.setBorder(BorderFactory.createEmptyBorder(8, 4, 8, 4));
        channels.getSelectionModel().setSelectionMode(TreeSelectionModel.SINGLE_TREE_SELECTION);
        channels.setCellRenderer(new DefaultTreeCellRenderer() {
            @Override
            public Component getTreeCellRendererComponent(JTree tree, Object value, boolean selected,
                    boolean expanded, boolean leaf, int row, boolean focused) {
                super.getTreeCellRendererComponent(tree, value, selected, expanded, leaf, row, focused);
                DefaultMutableTreeNode node = (DefaultMutableTreeNode) value;
                String name = node.getUserObject().toString();
                setIcon(null);
                setBackgroundNonSelectionColor(BACKGROUND);
                setBackgroundSelectionColor(new Color(49, 68, 86));
                boolean channel = !node.getAllowsChildren();
                boolean hasUnread = channel && unread.test(name);
                setForeground(hasUnread ? ACCENT : TEXT);
                setFont(tree.getFont().deriveFont(hasUnread ? Font.BOLD : Font.PLAIN));
                if (channel) setText((channelOrder.indexOf(name) + 1) + ". " + name + (hasUnread ? "  •" : ""));
                return this;
            }
        });
        channels.addTreeSelectionListener(e -> {
            DefaultMutableTreeNode node = (DefaultMutableTreeNode) channels.getLastSelectedPathComponent();
            if (!synchronizing && node != null && !node.getAllowsChildren()) {
                select.accept(node.getUserObject().toString());
            }
        });
        // Clicking a channel moves focus to the input so the user can type straight away;
        // keyboard selection leaves focus on the tree so arrowing through channels still works.
        channels.addMouseListener(new MouseAdapter() {
            @Override public void mouseReleased(MouseEvent e) {
                if (!SwingUtilities.isLeftMouseButton(e) || input == null) return;
                int row = channels.getClosestRowForLocation(e.getX(), e.getY());
                Rectangle bounds = channels.getRowBounds(row);
                if (bounds == null || e.getY() < bounds.y || e.getY() >= bounds.y + bounds.height) return;
                DefaultMutableTreeNode node = (DefaultMutableTreeNode) channels.getPathForRow(row).getLastPathComponent();
                if (!node.getAllowsChildren()) input.requestFocusInWindow();
            }
        });

        users.setName("ircUsers");
        users.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
        users.setFixedCellHeight(26);
        users.setBackground(BACKGROUND);
        users.setForeground(TEXT);
        users.setSelectionBackground(new Color(49, 68, 86));
        users.setBorder(BorderFactory.createEmptyBorder(6, 4, 6, 4));
        users.setCellRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList<?> list, Object value, int index,
                    boolean selected, boolean focused) {
                super.getListCellRendererComponent(list, value, index, selected, focused);
                ChannelUserList.Entry entry = (ChannelUserList.Entry) value;
                setText(entry.getPrefix() + entry.getNick());
                // Match the nick's colour in chat; null when colourised nicks are turned off.
                Color color = nickColor.apply(entry.getNick());
                setForeground(color != null ? color : entry.getPrefix().isEmpty() ? TEXT : ACCENT);
                return this;
            }
        });
        users.setToolTipText("Double-click to message. Right-click for user actions.");
        users.addMouseListener(new MouseAdapter() {
            @Override public void mousePressed(MouseEvent e) { showUserMenu(e); }
            @Override public void mouseReleased(MouseEvent e) { showUserMenu(e); }
            @Override public void mouseClicked(MouseEvent e) {
                if (SwingUtilities.isLeftMouseButton(e) && e.getClickCount() == 2 && selectUserAt(e)) {
                    query.accept(users.getSelectedValue().getNick());
                }
            }
        });
        users.getInputMap().put(KeyStroke.getKeyStroke("ENTER"), "query");
        users.getActionMap().put("query", new AbstractAction() {
            @Override public void actionPerformed(java.awt.event.ActionEvent e) {
                if (users.getSelectedValue() != null) query.accept(users.getSelectedValue().getNick());
            }
        });

        JPanel toolbar = new JPanel(new FlowLayout(FlowLayout.LEFT, 6, 6));
        toolbar.setBackground(HEADER);
        JButton reconnectButton = button("", "Reconnect to IRC", reconnect);
        try {
            reconnectButton.setIcon(new ImageIcon(ImageUtil.loadImageResource(IrcDesktopLayout.class, "reload.png")));
        } catch (Exception ignored) {
            reconnectButton.setText("Reconnect");
        }
        toolbar.add(reconnectButton);
        toolbar.add(button("Join…", "Join a channel", join));
        toolbar.add(button("Leave", "Close the selected conversation", leave));
        toolbar.add(button("Channels…", "Browse the server's channel list", browse));
        fontSelector.setToolTipText("Chat font");
        fontSelector.setFocusable(false);
        toolbar.add(fontSelector);
        fontSizeSelector.setToolTipText("Chat font size");
        fontSizeSelector.setFocusable(false);
        toolbar.add(fontSizeSelector);
        JPanel top = new JPanel(new BorderLayout());
        top.setBackground(HEADER);
        top.add(toolbar, BorderLayout.WEST);
