        composer.add(input, BorderLayout.CENTER);
    }

    List<String> channelOrder() {
        return new ArrayList<>(channelOrder);
    }

    void updateChannels(List<String> names, String selected) {
        synchronizing = true;
        try {
            if (!channelNames.equals(names)) {
                channelNames = new ArrayList<>(names);
                root.removeAllChildren();
                DefaultMutableTreeNode rooms = new DefaultMutableTreeNode("Channels");
                DefaultMutableTreeNode privateChats = new DefaultMutableTreeNode("Private chats");
                for (String name : names) {
                    DefaultMutableTreeNode node = new DefaultMutableTreeNode(name, false);
                    if ("System".equals(name)) root.add(node);
                    else if (name.startsWith("#") || name.startsWith("&")) rooms.add(node);
                    else privateChats.add(node);
                }
                root.add(rooms);
                root.add(privateChats);
                List<String> order = new ArrayList<>();
                java.util.Enumeration<?> nodes = root.preorderEnumeration();
                while (nodes.hasMoreElements()) {
                    DefaultMutableTreeNode node = (DefaultMutableTreeNode) nodes.nextElement();
                    if (!node.getAllowsChildren()) order.add(node.getUserObject().toString());
                }
                channelOrder = order;
                treeModel.reload();
                for (int row = 0; row < channels.getRowCount(); row++) channels.expandRow(row);
            }
            java.util.Enumeration<?> nodes = root.depthFirstEnumeration();
            while (nodes.hasMoreElements()) {
                DefaultMutableTreeNode node = (DefaultMutableTreeNode) nodes.nextElement();
                if (!node.getAllowsChildren() && node.getUserObject().equals(selected)) {
                    TreePath path = new TreePath(node.getPath());
                    if (!path.equals(channels.getSelectionPath())) {
                        channels.setSelectionPath(path);
                        channels.scrollPathToVisible(path);
                    }
                    break;
                }
            }
            channelHeading.setText(selected);
            // nodeChanged, not repaint: unread rows render wider (bold + marker), and the tree
            // caches row widths, so a plain repaint clips them.
            java.util.Enumeration<?> leaves = root.depthFirstEnumeration();
            while (leaves.hasMoreElements()) {
                DefaultMutableTreeNode node = (DefaultMutableTreeNode) leaves.nextElement();
                if (!node.getAllowsChildren()) treeModel.nodeChanged(node);
            }
        } finally {
            synchronizing = false;
        }
    }

    void updateUsers(String channel, List<ChannelUserList.Entry> entries) {
        ChannelUserList.Entry selected = users.getSelectedValue();
        userModel.clear();
        for (ChannelUserList.Entry entry : entries) {
            userModel.addElement(entry);
            if (selected != null && entry.getNick().equalsIgnoreCase(selected.getNick())) {
                users.setSelectedIndex(userModel.size() - 1);
            }
        }
        usersHeading.setText(channel.startsWith("#") || channel.startsWith("&")
                ? "USERS (" + entries.size() + ")" : "USERS —");
    }

    private boolean selectUserAt(MouseEvent e) {
        int index = users.locationToIndex(e.getPoint());
        if (index < 0 || !users.getCellBounds(index, index).contains(e.getPoint())) return false;
        users.setSelectedIndex(index);
        return true;
    }

    private void showUserMenu(MouseEvent e) {
        if (!e.isPopupTrigger() || !selectUserAt(e)) return;
        String nick = users.getSelectedValue().getNick();
        JPopupMenu menu = new JPopupMenu();
        JMenuItem message = new JMenuItem("Message " + nick);
        message.addActionListener(event -> query.accept(nick));
        menu.add(message);
        JMenuItem info = new JMenuItem("WHOIS " + nick);
        info.addActionListener(event -> whois.accept(nick));
        menu.add(info);
        menu.show(users, e.getX(), e.getY());
    }

    /**
     * Wires a toggle that hides one side of a split pane. A hidden side collapses the divider
     * and gives its room to the chat; showing it again restores the divider where it was.
     */
    private static void configureToggle(JToggleButton toggle, String name, String tooltip,
                                        JSplitPane split, JComponent side) {
        toggle.setName(name);
        toggle.setToolTipText(tooltip);
        toggle.setFocusable(false);
        int[] divider = {-1};
        toggle.addItemListener(e -> {
            boolean show = toggle.isSelected();
            if (show == side.isVisible()) return;
            if (!show) divider[0] = split.getDividerLocation();
            side.setVisible(show);
            if (show && divider[0] >= 0) split.setDividerLocation(divider[0]);
            split.revalidate();
            split.repaint();
        });
    }

    private static JSplitPane split(Component left, Component right, double weight) {
        JSplitPane split = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, left, right);
        split.setResizeWeight(weight);
        split.setContinuousLayout(true);
        split.setDividerSize(5);
        split.setBorder(BorderFactory.createEmptyBorder());
        return split;
    }

    private static JPanel section(JLabel title, Component content) {
        JPanel panel = new JPanel(new BorderLayout());
        panel.add(title, BorderLayout.NORTH);
        JScrollPane scroll = new JScrollPane(content);
        scroll.setBorder(BorderFactory.createEmptyBorder());
        panel.add(scroll, BorderLayout.CENTER);
        return panel;
    }

    private static JLabel heading(String text) {
        JLabel label = new JLabel(text);
        label.setOpaque(true);
        label.setBackground(HEADER);
        label.setForeground(TEXT);
        label.setBorder(BorderFactory.createEmptyBorder(9, 12, 9, 12));
        return label;
    }

    private static JButton button(String text, String tooltip, Runnable action) {
        JButton button = new JButton(text);
        button.setToolTipText(tooltip);
        button.setFocusable(false);
        button.addActionListener(e -> action.run());
        return button;
    }
}

package com.irc;

import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.input.KeyManager;
import net.runelite.client.input.KeyListener;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.ColorScheme;

import javax.inject.Inject;
import java.awt.*;
import java.awt.event.KeyEvent;

@Slf4j
public class IrcOverlay extends Overlay implements KeyListener {
    private final Client client;
    private final IrcPanel panel;

    final int tabHeight = 12;
    final int tabSpacing = 2; // space between tabs
    final int padding = 8;

    @Setter
    private boolean enabled;
    private final IrcConfig config;
    private final KeyManager keyManager;

    @Inject
    public IrcOverlay(Client client, IrcPanel panel, IrcConfig config, KeyManager keyManager) {
        this.client = client;
        this.panel = panel;
        this.config = config;
        this.enabled = config.overlayEnabled();
        this.keyManager = keyManager;

        updatePosition();

        keyManager.registerKeyListener(this);
    }

    public void shutdown() {
        keyManager.unregisterKeyListener(this);
    }

    private boolean isHidden(int component) {
        Widget w = client.getWidget(component);
        return w == null || w.isSelfHidden();
    }

    boolean isDialogOpen() {
        // Most chat dialogs with numerical input are added without the chatbox or its key listener being removed,
        // so chatboxFocused() is true. The chatbox onkey script uses the following logic to ignore key presses,
        // so we will use it too to not remap F-keys.
        return isHidden(InterfaceID.Chatbox.MES_LAYER_HIDE) || isHidden(InterfaceID.Chatbox.CHATDISPLAY)
                // We want to block F-key remapping in the bank pin interface too, so it does not interfere with the
                // Keyboard Bankpin feature of the Bank plugin
                || !isHidden(InterfaceID.BankpinKeypad.UNIVERSE);
    }

    boolean isOptionsDialogOpen() {
        return client.getWidget(InterfaceID.Chatmenu.OPTIONS) != null;
    }

    private static final int CHATBOX_GROUP = 162;
    private static final int CHATBOX_MESSAGES_CHILD = 0;
    private static final int CHATAREA = InterfaceID.Chatbox.CHATAREA;

    public void updatePosition() {
        if (config.overlayDynamic()) {
            setPosition(OverlayPosition.DYNAMIC);
        } else {
            setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);
        }

        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (!enabled || panel == null || isDialogOpen() || isOptionsDialogOpen())
            return null;

        Widget chatboxMessages = client.getWidget(CHATBOX_GROUP, CHATBOX_MESSAGES_CHILD);
        Widget chatarea = client.getWidget(CHATAREA);
        if (chatboxMessages == null || chatboxMessages.isHidden() || chatarea == null || chatarea.isHidden())
            return null;

        net.runelite.api.Point loc = chatboxMessages.getCanvasLocation();
        int x = loc.getX() + padding;
        int y = loc.getY() + padding;
        int scrollbarWidth = 16;
        int width = chatboxMessages.getWidth() - scrollbarWidth - padding * 2; // additional padding
        if (width > config.overlayMaxWidth()) {
            width = config.overlayMaxWidth();
        }
        int height = tabHeight;

        // background
        graphics.setColor(ColorScheme.DARKER_GRAY_COLOR);
        if (!config.overlayDynamic()) {
            x = 0;
            y = 0;
        }

        graphics.fillRect(x, y, width, height);

        // tabs
        java.util.List<String> channels = panel.getChannelNames();
        int activeTabIndex = Math.max(0, channels.indexOf(panel.getCurrentChannel()));

        int xOffset = 0;
        int yOffset = 0;
        for (int i = 0; i < channels.size(); i++) {
            boolean isActive = i == activeTabIndex;
            String channel = channels.get(i);
            boolean isUnread = panel.unreadMessages.get(channel);

            FontMetrics fm = graphics.getFontMetrics();
            int tabWidth = fm.stringWidth(channel) + padding * 2 - tabSpacing; // 8px padding each side

            // stop drawing if tab exceeds width
            if (xOffset + tabWidth > width) {
                yOffset += height;
                xOffset = 0;
            }

            // tab background
            graphics.setColor(isActive ? ColorScheme.BRAND_ORANGE : ColorScheme.DARKER_GRAY_COLOR.darker());
            graphics.fillRect(x + xOffset, y + yOffset, tabWidth, height);

            // channel name
            graphics.setColor(isActive ? Color.WHITE : isUnread ? ColorScheme.BRAND_ORANGE.brighter() : ColorScheme.BRAND_ORANGE.darker());
            graphics.drawString(channel, x + xOffset + padding, y + yOffset + height);

            xOffset += tabWidth + tabSpacing;
        }

        return new Dimension(width, height);
    }

    @Override
    public void keyPressed(KeyEvent e) {
        if (panel == null || panel.getChannelPanes() == null) return;

        if (e.getKeyCode() == KeyEvent.VK_PAGE_UP && this.config.pageUpDownNavigation()) {
            panel.cycleChannelBackwards();
            e.consume();
        } else if (e.getKeyCode() == KeyEvent.VK_PAGE_DOWN && this.config.pageUpDownNavigation()) {
            panel.cycleChannel();
            e.consume();
        } else if (this.config.backTickNavigation()) {
            if (e.getKeyCode() == KeyEvent.VK_BACK_QUOTE && (e.getModifiersEx() & KeyEvent.SHIFT_DOWN_MASK) != 0) {
                panel.cycleChannelBackwards();
                e.consume();
            } else if (e.getKeyCode() == KeyEvent.VK_BACK_QUOTE) {
                panel.cycleChannel();
                e.consume();
            }
        }
    }

    @Override
    public void keyTyped(KeyEvent e) {
        // Unnecessary
    }

    @Override
    public void keyReleased(KeyEvent e) {
        // Unnecessary
    }

    @Override
    public boolean isEnabledOnLoginScreen()
    {
        return true;
    }

}

package com.irc;

import lombok.AllArgsConstructor;
import lombok.Value;
import java.time.Instant;

@Value
@AllArgsConstructor
public class IrcMessage {
    String channel;
    String sender;
    String content;
    MessageType type;
    Instant timestamp;
    /** The sender's channel prefix ("@", "+", ...) when the message was received; "" when none. */
    String prefix;

    IrcMessage(String channel, String sender, String content, MessageType type, Instant timestamp) {
        this(channel, sender, content, type, timestamp, "");
    }

    /** The sender with its prefix, kept after the "* " that marks an action: "@bob", "* @bob". */
    String getDisplaySender() {
        if (prefix.isEmpty()) return sender;
        if (sender.startsWith("* ")) return "* " + prefix + sender.substring(2);
        return prefix + sender;
    }

    enum MessageType {
        CHAT, SYSTEM, JOIN, PART, QUIT, NICK_CHANGE, PRIVATE, NOTICE, KICK, TOPIC, MODE,
        HISTORY, HISTORY_SEPARATOR
    }
}

package com.irc;

import javax.swing.JFrame;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.Frame;
import java.awt.Rectangle;
import java.awt.Window;
import java.awt.event.ComponentAdapter;
import java.awt.event.ComponentEvent;
import java.awt.event.HierarchyEvent;
import java.awt.event.HierarchyListener;
import java.awt.event.WindowAdapter;
import java.awt.event.WindowEvent;

/** Moves the live chat controls between hosts. All methods run on the Swing EDT. */
final class IrcPanelWindow {
    private final JPanel dockHost;
    private final JPanel content;
    private final Runnable beforeMove;
    private final Runnable hidePreviews;
    private final Runnable dockRequested;
    private JFrame frame;
    private Rectangle bounds;
    private Window observedWindow;
    private final WindowAdapter windowListener = new WindowAdapter() {
        @Override
        public void windowLostFocus(WindowEvent e) { hidePreviews.run(); }

        @Override
        public void windowDeactivated(WindowEvent e) { hidePreviews.run(); }

        @Override
        public void windowIconified(WindowEvent e) { hidePreviews.run(); }
    };
    private final ComponentAdapter componentListener = new ComponentAdapter() {
        @Override
        public void componentMoved(ComponentEvent e) { hidePreviews.run(); }

        @Override
        public void componentResized(ComponentEvent e) { hidePreviews.run(); }
    };
    private final HierarchyListener hierarchyListener = this::hierarchyChanged;

    private void hierarchyChanged(HierarchyEvent e) {
        if ((e.getChangeFlags() & (HierarchyEvent.PARENT_CHANGED | HierarchyEvent.SHOWING_CHANGED)) != 0) {
            observeWindow(SwingUtilities.getWindowAncestor(content));
            if (!content.isShowing()) {
                hidePreviews.run();
            }
        }
    }

    IrcPanelWindow(JPanel dockHost, JPanel content, Runnable beforeMove,
                   Runnable hidePreviews, Runnable dockRequested) {
        this.dockHost = dockHost;
        this.content = content;
        this.beforeMove = beforeMove;
        this.hidePreviews = hidePreviews;
        this.dockRequested = dockRequested;
        content.addHierarchyListener(hierarchyListener);
        observeWindow(SwingUtilities.getWindowAncestor(content));
    }

    void setDetached(boolean detached, boolean alwaysOnTop) {
        assert SwingUtilities.isEventDispatchThread();
        if (detached) {
            if (frame == null) {
                beforeMove.run();
                Window owner = SwingUtilities.getWindowAncestor(content);
                frame = new JFrame("Global Chat (IRC)");
                frame.setDefaultCloseOperation(JFrame.DO_NOTHING_ON_CLOSE);
                frame.setMinimumSize(new Dimension(640, 360));
                frame.setSize(960, 620);
                if (owner != null) {
                    frame.setIconImages(owner.getIconImages());
                }
                frame.setLocationRelativeTo(owner);
                if (bounds != null) {
                    // Reuse geometry within this plugin session, provided its title bar is visible.
                    for (java.awt.GraphicsDevice screen : java.awt.GraphicsEnvironment
                            .getLocalGraphicsEnvironment().getScreenDevices()) {
                        if (screen.getDefaultConfiguration().getBounds()
                                .contains(bounds.x + bounds.width / 2, bounds.y + 10)) {
                            frame.setBounds(bounds);
                            break;
                        }
                    }
                }
                frame.addWindowListener(new WindowAdapter() {
                    @Override
                    public void windowClosing(WindowEvent e) { dockRequested.run(); }
                });
                frame.add(content, BorderLayout.CENTER);
                dockHost.revalidate();
                dockHost.repaint();
                frame.setAlwaysOnTop(alwaysOnTop);
                frame.setVisible(true);
            } else {
                frame.setAlwaysOnTop(alwaysOnTop);
            }
        } else if (frame != null) {
            beforeMove.run();
            bounds = frame.getBounds();
            dockHost.add(content, BorderLayout.CENTER);
            frame.dispose();
            frame = null;
            dockHost.revalidate();
            dockHost.repaint();
        }
    }

    void toFront() {
        assert SwingUtilities.isEventDispatchThread();
        if (frame == null) return;
        if ((frame.getExtendedState() & Frame.ICONIFIED) != 0) {
            frame.setExtendedState(frame.getExtendedState() & ~Frame.ICONIFIED);
        }
        frame.toFront();
        frame.requestFocus();
    }

    private void observeWindow(Window window) {
        if (observedWindow == window) return;
        if (observedWindow != null) {
            observedWindow.removeWindowFocusListener(windowListener);
            observedWindow.removeWindowListener(windowListener);
            observedWindow.removeComponentListener(componentListener);
        }
        observedWindow = window;
        if (window != null) {
            window.addWindowFocusListener(windowListener);
            window.addWindowListener(windowListener);
            window.addComponentListener(componentListener);
        }
    }

    void shutdown() {
        assert SwingUtilities.isEventDispatchThread();
        setDetached(false, false);
        content.removeHierarchyListener(hierarchyListener);
        observeWindow(null);
    }
}

