            log.debug("Initializing emoji data");
            loadEmojis();
            log.debug("Successfully initialized emoji data");
        } catch (Exception e) {
            log.error("Failed to initialize emoji data", e);
            throw new RuntimeException("Failed to initialize emoji data", e);
        }
    }

    private void loadEmojis() throws Exception {
        if (EmojiManager.isInitialized()) {
            return;
        }

        try (InputStream is = EmojiManager.class.getResourceAsStream(EMOJI_JSON_PATH)) {
            if (is == null) {
                throw new RuntimeException("Could not find resource: " + EMOJI_JSON_PATH);
            }

            try (Reader reader = new InputStreamReader(is, StandardCharsets.UTF_8)) {
                JsonArray emojiArray = gson.fromJson(reader, JsonArray.class);

                if (emojiArray == null) {
                    throw new RuntimeException("Failed to parse emoji JSON or file is empty");
                }

                for (int i = 0; i < emojiArray.size(); i++) {
                    JsonObject emojiJson = emojiArray.get(i).getAsJsonObject();
                    if (!emojiJson.has("emoji")) continue;

                    String unicode = emojiJson.get("emoji").getAsString();
                    boolean supportsFitzpatrick = emojiJson.has("supports_fitzpatrick") ?
                            emojiJson.get("supports_fitzpatrick").getAsBoolean() : false;

                    List<String> aliases = new ArrayList<>();
                    if (emojiJson.has("aliases")) {
                        JsonArray aliasesJson = emojiJson.getAsJsonArray("aliases");
                        for (int j = 0; j < aliasesJson.size(); j++) {
                            aliases.add(aliasesJson.get(j).getAsString());
                        }
                    }

                    EmojiManager.register(new Emoji(unicode, aliases, supportsFitzpatrick));
                }
            }
        }

        EmojiManager.finishInitialization();
    }
}

package com.irc.emoji;

import java.util.Collection;
import java.util.HashMap;
import java.util.Map;

public class EmojiTrie {
    private final Node root = new Node();
    final int maxDepth;

    public EmojiTrie(Collection<Emoji> emojis) {
        int maxDepth = 0;
        for (Emoji emoji : emojis) {
            Node tree = root;
            char[] chars = emoji.getUnicode().toCharArray();
            maxDepth = Math.max(maxDepth, chars.length);
            for (char c : chars) {
                if (!tree.hasChild(c)) {
                    tree.addChild(c);
                }
                tree = tree.getChild(c);
            }
            tree.setEmoji(emoji);
        }
        this.maxDepth = maxDepth;
    }

    /**
     * Checks if sequence of chars contain an emoji.
     */
    public Matches isEmoji(char[] sequence) {
        return isEmoji(sequence, 0, sequence.length);
    }

    /**
     * Checks if the sequence of chars within the given bound indices contain an emoji.
     */
    public Matches isEmoji(char[] sequence, int start, int end) {
        if (start < 0 || start > end || end > sequence.length) {
            throw new ArrayIndexOutOfBoundsException(
                    "start " + start + ", end " + end + ", length " + sequence.length);
        }
        if (sequence == null) {
            return Matches.POSSIBLY;
        }
        Node tree = root;
        for (int i = start; i < end; i++) {
            if (!tree.hasChild(sequence[i])) {
                return Matches.IMPOSSIBLE;
            }
            tree = tree.getChild(sequence[i]);
        }
        return tree.isEndOfEmoji() ? Matches.EXACTLY : Matches.POSSIBLY;
    }

    /**
     * Finds Emoji instance from emoji unicode
     */
    public Emoji getEmoji(String unicode) {
        return getEmoji(unicode.toCharArray(), 0, unicode.length());
    }

    /**
     * Finds Emoji instance from emoji unicode chars.
     */
    public Emoji getEmoji(char[] sequence, int start, int end) {
        if (start < 0 || start > end || end > sequence.length) {
            throw new ArrayIndexOutOfBoundsException(
                    "start " + start + ", end " + end + ", length " + sequence.length);
        }
        Node tree = root;
        for (int i = start; i < end; i++) {
            if (!tree.hasChild(sequence[i])) {
                return null;
            }
            tree = tree.getChild(sequence[i]);
        }
        return tree.getEmoji();
    }

    public enum Matches {
        EXACTLY, POSSIBLY, IMPOSSIBLE;

        public boolean exactMatch() {
            return this == EXACTLY;
        }

        public boolean impossibleMatch() {
            return this == IMPOSSIBLE;
        }
    }

    private class Node {
        private Map<Character, Node> children = new HashMap<>();
        private Emoji emoji;

        private void setEmoji(Emoji emoji) {
            this.emoji = emoji;
        }

        private Emoji getEmoji() {
            return emoji;
        }

        private boolean hasChild(char child) {
            return children.containsKey(child);
        }

        private void addChild(char child) {
            children.put(child, new Node());
        }

        private Node getChild(char child) {
            return children.get(child);
        }

        private boolean isEndOfEmoji() {
            return emoji != null;
        }
    }
}

package com.irc.emoji;

import java.util.ArrayList;
import java.util.List;

public class EmojiParser {
    public enum FitzpatrickAction {
        PARSE, REMOVE, IGNORE
    }

    public static String parseToAliases(String input) {
        return parseToAliases(input, FitzpatrickAction.PARSE);
    }

    public static String parseToAliases(String input, FitzpatrickAction fitzpatrickAction) {
        if (input == null || input.isEmpty()) return input;

        int prev = 0;
        StringBuilder sb = new StringBuilder(input.length());
        List<UnicodeCandidate> candidates = getUnicodeCandidates(input);

        for (UnicodeCandidate candidate : candidates) {
            sb.append(input, prev, candidate.getEmojiStartIndex());

            String replacement;
            switch (fitzpatrickAction) {
                case PARSE:
                    if (candidate.hasFitzpatrick()) {
                        replacement = ":" +
                                candidate.getEmoji().getAliases().get(0) +
                                "|" +
                                candidate.getFitzpatrickType() +
                                ":";
                    } else {
                        replacement = ":" + candidate.getEmoji().getAliases().get(0) + ":";
                    }
                    break;
                case REMOVE:
                    replacement = ":" + candidate.getEmoji().getAliases().get(0) + ":";
                    break;
                case IGNORE:
                default:
                    replacement = ":" +
                            candidate.getEmoji().getAliases().get(0) +
                            ":" +
                            candidate.getFitzpatrickUnicode();
                    break;
            }

            sb.append(replacement);
            prev = candidate.getFitzpatrickEndIndex();
        }

        return sb.append(input.substring(prev)).toString();
    }

    /**
     * Generates a list of UnicodeCandidate found in the input string.
     */
    protected static List<UnicodeCandidate> getUnicodeCandidates(String input) {
        char[] inputCharArray = input.toCharArray();
        List<UnicodeCandidate> candidates = new ArrayList<>();
        UnicodeCandidate next;

        for (int i = 0; (next = getNextUnicodeCandidate(inputCharArray, i)) != null;
             i = next.getFitzpatrickEndIndex()) {
            candidates.add(next);
        }

        return candidates;
    }

    /**
     * Finds the next UnicodeCandidate after a given starting index
     */
    protected static UnicodeCandidate getNextUnicodeCandidate(char[] chars, int start) {
        for (int i = start; i < chars.length; i++) {
            int emojiEnd = EmojiManager.getEmojiEndPos(chars, i);

            if (emojiEnd != -1) {
                Emoji emoji = EmojiManager.getByUnicode(new String(chars, i, emojiEnd - i));
                String fitzpatrickString = (emojiEnd + 2 <= chars.length) ?
                        new String(chars, emojiEnd, 2) :
                        null;
                return new UnicodeCandidate(emoji, fitzpatrickString, i);
            }
        }

        return null;
    }

    public static class UnicodeCandidate {
        private final Emoji emoji;
        private final Fitzpatrick fitzpatrick;
        private final int startIndex;

        private UnicodeCandidate(Emoji emoji, String fitzpatrick, int startIndex) {
            this.emoji = emoji;
            this.fitzpatrick = Fitzpatrick.fromUnicode(fitzpatrick);
            this.startIndex = startIndex;
        }

        public Emoji getEmoji() {
            return emoji;
        }

        public boolean hasFitzpatrick() {
            return getFitzpatrick() != null;
        }

        public Fitzpatrick getFitzpatrick() {
            return fitzpatrick;
        }

        public String getFitzpatrickType() {
            return hasFitzpatrick() ? fitzpatrick.name().toLowerCase() : "";
        }

        public String getFitzpatrickUnicode() {
            return hasFitzpatrick() ? fitzpatrick.unicode : "";
        }

        public int getEmojiStartIndex() {
            return startIndex;
        }

        public int getEmojiEndIndex() {
            return startIndex + emoji.getUnicode().length();
        }

        public int getFitzpatrickEndIndex() {
            return getEmojiEndIndex() + (fitzpatrick != null ? 2 : 0);
        }
    }
}

package com.irc.emoji;

public enum Fitzpatrick {
    TYPE_1_2("\uD83C\uDFFB"),
    TYPE_3("\uD83C\uDFFC"),
    TYPE_4("\uD83C\uDFFD"),
    TYPE_5("\uD83C\uDFFE"),
    TYPE_6("\uD83C\uDFFF");

    public final String unicode;

    Fitzpatrick(String unicode) {
        this.unicode = unicode;
    }

    public static Fitzpatrick fromUnicode(String unicode) {
        if (unicode == null) return null;
        for (Fitzpatrick f : values()) {
            if (f.unicode.equals(unicode)) {
                return f;
            }
        }
        return null;
    }
}

package com.irc;

import javax.swing.table.AbstractTableModel;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;

/**
 * The channel browser's data layer: the full LIST result, the filtered view of it, and the
 * mapping from a table row back to its entry.
 *
 * This is deliberately separate from {@link ChannelListDialog} so it can be unit-tested without
 * constructing a Window, which throws HeadlessException on a headless machine.
 *
 * Topics are stripped of IRC formatting codes once, up front - when the entries are set, not when
 * a cell is painted or a filter is applied. The filter then matches the same stripped text the
 * user is looking at, rather than raw codes they cannot see, without re-running the stripper per
 * row per keystroke: at the 20,000-row cap that would be 20,000 regex passes for every character
 * typed into the filter box, all of it on the EDT.
 */
public class ChannelListTableModel extends AbstractTableModel {
    private static final String[] COLUMNS = {"Channel", "Users", "Topic"};

    private List<Row> allRows = Collections.emptyList();
    private List<Row> shownRows = Collections.emptyList();
    private String filter = "";

    /**
     * An entry plus everything derived from it that the table and the filter would otherwise
     * recompute on every repaint and every keystroke.
     *
     * The precomputation lives here rather than on {@link ChannelListEntry} because that class is
     * immutable and shared with the client's LIST snapshot, which has no interest in display
     * concerns.
     */
    private static final class Row {
        private final ChannelListEntry entry;
        private final String topic;
        private final String nameLower;
        private final String topicLower;

        private Row(ChannelListEntry entry) {
            this.entry = entry;
            this.topic = displayTopic(entry);
            String name = entry.getName() != null ? entry.getName() : "";
            this.nameLower = name.toLowerCase(Locale.ROOT);
            this.topicLower = this.topic.toLowerCase(Locale.ROOT);
        }

        /** {@code needle} must already be trimmed, lower-cased and non-empty. */
        private boolean matches(String needle) {
            return nameLower.contains(needle) || topicLower.contains(needle);
        }
    }

    /** Replaces the backing data and reapplies the active filter. */
    public void setEntries(List<ChannelListEntry> entries) {
        List<Row> rows = new ArrayList<>(entries != null ? entries.size() : 0);
        if (entries != null) {
            for (ChannelListEntry entry : entries) {
                rows.add(new Row(entry));
            }
        }
        allRows = rows;
        applyFilter();
    }

    /** Narrows the view. A null or blank filter shows everything. */
    public void setFilter(String filter) {
        this.filter = filter != null ? filter : "";
        applyFilter();
    }

    private void applyFilter() {
        String needle = needle(filter);
        if (needle.isEmpty()) {
            shownRows = allRows;
        } else {
            List<Row> matched = new ArrayList<>();
            for (Row row : allRows) {
                if (row.matches(needle)) {
                    matched.add(row);
                }
            }
            shownRows = matched;
        }
        fireTableDataChanged();
    }

    /** The comparable form of a filter string. Empty means "match everything". */
    private static String needle(String filter) {
        return filter == null ? "" : filter.trim().toLowerCase(Locale.ROOT);
    }

    /**
     * Case-insensitive substring match against the channel name and the stripped topic.
     *
     * Off the hot path - the model filters against precomputed rows - but kept as the single
     * definition of the rule, and testable without a table.
     */
    public static boolean matches(ChannelListEntry entry, String filter) {
        String needle = needle(filter);
        return needle.isEmpty() || new Row(entry).matches(needle);
    }

    /** The topic as the user sees it: formatting codes removed, never null. */
    static String displayTopic(ChannelListEntry entry) {
        String topic = entry.getTopic();
        if (topic == null) {
            return "";
        }
        String stripped = IrcFormatting.stripCodes(topic);
        return stripped != null ? stripped : "";
    }

    /** The entry behind a model row. Callers must convert view rows first. */
    public ChannelListEntry getEntryAt(int rowIndex) {
        return shownRows.get(rowIndex).entry;
    }

    public int getTotalCount() {
        return allRows.size();
    }

    public int getShownCount() {
        return shownRows.size();
    }

    @Override
    public int getRowCount() {
        return shownRows.size();
    }

    @Override
    public int getColumnCount() {
        return COLUMNS.length;
    }

    @Override
    public String getColumnName(int column) {
        return COLUMNS[column];
    }

    /**
     * Users is Integer so TableRowSorter sorts it numerically. As String, 9 would outrank 412.
     */
    @Override
    public Class<?> getColumnClass(int columnIndex) {
        return columnIndex == 1 ? Integer.class : String.class;
    }

    @Override
    public Object getValueAt(int rowIndex, int columnIndex) {
        Row row = shownRows.get(rowIndex);
        switch (columnIndex) {
            case 0:
                return row.entry.getName();
            case 1:
                return row.entry.getUserCount();
            case 2:
                return row.topic;
            default:
                return "";
        }
    }

    @Override
    public boolean isCellEditable(int rowIndex, int columnIndex) {
        return false;
    }
}

package com.irc;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import javax.swing.*;
import java.awt.*;
import java.time.Instant;
import java.util.List;
import java.util.Objects;
import java.util.function.Consumer;

/**
 * Adapter class to bridge between SimpleIrcClient
 */
@Slf4j
public class IrcAdapter {
    @Getter
    private SimpleIrcClient client;
    private String currentNick;
    private Consumer<IrcMessage> messageConsumer;
    private IrcConfig config;
    private IrcPanel panel;
    /**
     * The query behind the in-flight LIST, replayed by the dialog's Refresh button. Written on
     * the caller's thread ({@link #requestChannelList}) and read on the IRC reader thread when
     * {@code CHANNEL_LIST} fires - volatile so that handoff doesn't depend on the incidental
     * happens-before edge created by both sides passing through the same monitor.
     */
    private volatile String lastChannelListQuery = "";

    public IrcAdapter() {
        client = new SimpleIrcClient();
    }

    /**
     * Initialize the client with the provided config
     */
    public void initialize(IrcConfig config, Consumer<IrcMessage> messageConsumer, IrcPanel panel, String currentNick) {
        this.messageConsumer = messageConsumer;
        this.currentNick = currentNick;
        this.config = config;
        this.panel = panel;

        client = new SimpleIrcClient()
                .server(config.server().getHostname(), 6697, true)
                .credentials(currentNick, "runelite", currentNick);

        if (config.password() != null && !config.password().isEmpty()) {
            client.sasl(config.accountName(), config.password());
        }

        client.setRawLogging(config.logRawLines());

        setupEventHandlers();
    }

    /**
     * Connect to the IRC server
     */
    public void connect() {
        client.connect();
    }

    /**
     * Disconnect from the IRC server
     */
    public void disconnect(String reason) {
        client.disconnect(reason);
    }
    public void disconnect() {
        client.disconnect();
    }

    /**
     * Join a channel
     */
    public void joinChannel(String channel, String password) {
        client.executeWhenRegistered(() -> client.joinChannel(channel, password));
    }

    /**
     * Leave a channel
     */
    public void leaveChannel(String channel) {
        client.leaveChannel(channel);
    }

    /**
     * Leave a channel with a reason
     */
    public void leaveChannel(String channel, String reason) {
        client.leaveChannel(channel, reason);
    }

    /**
     * Send a message to a target (channel or user)
     */
    public void sendMessage(String target, String message) {
        client.sendMessage(target, message);
        processMessage(new IrcMessage(
                target,
                currentNick,
                message,
                IrcMessage.MessageType.PRIVATE,
                Instant.now(),
                client.getChannelPrefix(target, currentNick)
        ));
    }

    /**
     * Send an action (/me) to a target
     */
    public void sendAction(String target, String action) {
        client.sendAction(target, action);
        processMessage(new IrcMessage(
                target,
                "* " + currentNick,
                action,
                IrcMessage.MessageType.PRIVATE,
                Instant.now(),
                client.getChannelPrefix(target, currentNick)
        ));
    }

    /**
     * Send a notice to a target
     */
    public void sendNotice(String target, String message) {
        client.sendNotice(target, message);
        processMessage(new IrcMessage(
                "System",
                currentNick,
                "Notice to " + target + ": " + message,
                IrcMessage.MessageType.SYSTEM,
                Instant.now()
        ));
    }

    /**
     * Change nickname
     */
    public void setNick(String nick) {
        client.setNick(nick);
    }

    /**
     * Send a raw IRC command
     */
    public void sendRawLine(String command) {
        client.sendRawLine(command);
    }

    /**
     * Asks the server for its channel list. {@code query} is passed through verbatim so server
     * filters such as ">50" or "*quest*" work as the user typed them.
     */
    public void requestChannelList(String query) {
        String trimmed = query != null ? query.trim() : "";
        lastChannelListQuery = trimmed;
        // A run abandoned by an earlier request (server truncated its reply, no 323, connection
        // survives) must not have this request's rows appended onto its stale leftovers.
        client.resetChannelListRun();
        // No trailing space on a bare LIST: some servers read "LIST " as an empty filter.
        client.sendRawLine(trimmed.isEmpty() ? "LIST" : "LIST " + trimmed);
    }

    /**
     * True once the socket is up and the registration handshake has been written - NOT that the
     * server has accepted it. A command sent in the window between the handshake and RPL_WELCOME
     * (longer with SASL) will reach the server but may be answered with 451 ERR_NOTREGISTERED
     * rather than doing anything. Do not read this as "ready for commands".
     */
    /** Applies the raw-logging setting to a live connection, so it can be turned on mid-problem. */
    public void setRawLogging(boolean enabled) {
        if (client != null) {
            client.setRawLogging(enabled);
        }
    }

    public boolean isConnected() {
        return client.isConnected();
    }

    /**
     * Drops the reference to the panel, so an in-flight reply cannot drive a UI that is being
     * torn down. Without it a 323 arriving during shutdown still pops the channel browser for a
     * plugin that no longer exists.
     */
    public void clearPanel() {
        this.panel = null;
    }

    /**
     * Get the current nickname
     */
    public String getNick() {
        return currentNick;
    }

    /**
     * Process and forward incoming messages to the plugin
     */
    private void processMessage(IrcMessage message) {
        if (messageConsumer != null) {
            messageConsumer.accept(message);
        }
    }

    /**
     * Set up event handlers for the SimpleIrcClient
     */
    private void setupEventHandlers() {
        client.addEventListener(event -> {
            String target = event.getTarget();
            String source = event.getSource();

            switch (event.getType()) {
                case CONNECT:
                    processMessage(new IrcMessage("System", "System", "Connected to IRC server, registering...", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case REGISTERED:
                    currentNick = client.getNick();
                    processMessage(new IrcMessage("System", "System", "Registration complete - ready for commands", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    processMessage(new IrcMessage("System", "System", "Welcome to IRC! To chat in the current channel, use '" + config.prefix() + "' followed by your message in the game chatbox.", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    processMessage(new IrcMessage("System", "System", "For a list of commands, type '/help' in the side panel input box.", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case SASL_SUCCESS:
                    processMessage(new IrcMessage("System", "System", "Authenticated via SASL.", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case SASL_FAILED:
                    processMessage(new IrcMessage("System", "System", "SASL authentication failed: " + event.getMessage() + " (continuing unauthenticated).", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case DISCONNECT:
                    // The client records why the link went down; without it this line is
                    // indistinguishable from the user's own /quit.
                    String disconnectText = event.getMessage() != null && !event.getMessage().isEmpty()
                            ? "Disconnected from IRC (" + event.getMessage() + ")"
                            : "Disconnected from IRC";
                    processMessage(new IrcMessage("System", "System", disconnectText, IrcMessage.MessageType.SYSTEM, Instant.now()));
                    for (String channel : client.getChannels()) {
                        processMessage(new IrcMessage(channel, "System", disconnectText, IrcMessage.MessageType.SYSTEM, Instant.now()));
                    }
                    // Any outcome must cancel a pending LIST timeout, not just success - otherwise
                    // a disconnect while one is armed fires a spurious "no response" 30s later.
                    if (panel != null) {
                        SwingUtilities.invokeLater(panel::cancelChannelListTimeout);
                    }
                    break;

                case MESSAGE:
                    if (Objects.equals(target, source)) {
                        switch (config.filterPMs()) {
                            case Current:
                                source = "[PM] " + source;
                                target = panel != null ? panel.getCurrentChannel() : "System";
                                break;
                            case Status:
                                source = "[PM] " + source;
                                target = "System";
                                break;
                            case Private:
                                target = event.getSource();
                                break;
                        }
                    }
                    // Looked up by the original target: PMs have no channel, so they get no prefix.
                    processMessage(new IrcMessage(target, source, event.getMessage(), IrcMessage.MessageType.CHAT, Instant.now(),
                            client.getChannelPrefix(event.getTarget(), event.getSource())));
                    break;

                case ACTION:
                    processMessage(new IrcMessage(event.getTarget(), "* " + event.getSource(), event.getMessage(), IrcMessage.MessageType.CHAT, Instant.now(),
                            client.getChannelPrefix(event.getTarget(), event.getSource())));
                    break;

                case JOIN:
                    if (!config.hideConnectionMessages()) {
                        processMessage(new IrcMessage(
                                event.getTarget(),
                                "*",
                                event.getSource() + " has joined.",
                                IrcMessage.MessageType.JOIN,
                                Instant.now()
                        ));
                    }
                    break;

                case PART:
                    if (!config.hideConnectionMessages()) {
                        processMessage(new IrcMessage(event.getTarget(), event.getSource() + " parted", (event.getMessage() != null ? event.getMessage() : " "), IrcMessage.MessageType.PART, Instant.now()));
                    }
                    break;

                case QUIT:
                    if (!config.hideConnectionMessages() && event.getAdditionalData() != null && !event.getAdditionalData().isEmpty()) {
                        String[] channels = event.getAdditionalData().split(",");
                        for (String channel : channels) {
                            processMessage(new IrcMessage(channel, event.getSource() + " quit", event.getMessage() != null ? event.getMessage() : " ", IrcMessage.MessageType.QUIT, Instant.now()));
                        }
                    }
                    break;

                case NICK_CHANGE:
                    String oldNick = event.getSource();
                    String newNick = event.getMessage();

                    if (oldNick.equals(currentNick)) {
                        currentNick = newNick;
                    }

                    if (panel != null && panel.isPane(oldNick)) {
                        SwingUtilities.invokeLater(() -> panel.renameChannel(oldNick, newNick));
                    }

                    if (event.getAdditionalData() != null) {
                        String[] channels = event.getAdditionalData().split(",");
                        for (String channel : channels) {
                            if (channel != null && !channel.isEmpty()) {
                                processMessage(new IrcMessage(channel, oldNick + " is now known as", newNick, IrcMessage.MessageType.NICK_CHANGE, Instant.now()));
                            }
                        }
                    }
                    break;

                case KICK:
                    if (!config.hideConnectionMessages()) {
                        String[] kickParts = event.getMessage().split(" ", 2);
                        String kickedUser = kickParts[0];
                        String kickReason = kickParts.length > 1 ? kickParts[1] : "";
                        processMessage(new IrcMessage(event.getTarget(), event.getSource() + " kicked " + kickedUser, kickReason, IrcMessage.MessageType.KICK, Instant.now()));
                    }
                    break;

                case SERVER_NOTICE:
                case NOTICE:
                    if (source != null && source.endsWith(".SwiftIRC.net")) {
                        if (!config.filterServerNotices()) {
                            target = "System";
                        } else {
                            target = source;
                        }
                    } else {
                        source = "[N] " + source;
                        switch (config.filterNotices()) {
                            case Current:
                                target = panel != null ? panel.getCurrentChannel() : "System";
                                break;
                            case Status:
                                target = "System";
                                break;
                            case Private:
                                target = source;
                                break;
                        }
                    }
                    processMessage(new IrcMessage(target, source, event.getMessage(), IrcMessage.MessageType.NOTICE, Instant.now()));
                    break;

                case CHANNEL_MODE:
                    processMessage(new IrcMessage(event.getTarget(), event.getSource(), event.getMessage(), IrcMessage.MessageType.MODE, Instant.now()));
                    break;

                case USER_MODE:
                    processMessage(new IrcMessage("System", currentNick, event.getMessage(), IrcMessage.MessageType.MODE, Instant.now()));
                    break;

                case TOPIC:
                    processMessage(new IrcMessage(event.getTarget(), "* Topic", event.getMessage(), IrcMessage.MessageType.TOPIC, Instant.now()));
                    break;

                case NAMES:
                    processMessage(new IrcMessage(event.getTarget(), "Users", event.getMessage(), IrcMessage.MessageType.JOIN, Instant.now()));
                    break;

                case USERS_CHANGED:
                    if (panel != null) {
                        String usersChannel = event.getTarget();
                        // Snapshot on the IRC thread; it is immutable, so the EDT can hold it.
                        List<ChannelUserList.Entry> users = client.getChannelUsers(usersChannel);
                        SwingUtilities.invokeLater(() -> panel.setChannelUsers(usersChannel, users));
                    }
                    break;

                case CHANNEL_LIST:
                    if (panel != null) {
                        // Snapshot on the IRC thread; it is immutable, so the EDT can hold it.
                        List<ChannelListEntry> channelList = client.getChannelListSnapshot();
                        boolean truncated = client.isChannelListTruncated();
                        String listQuery = lastChannelListQuery;
                        SwingUtilities.invokeLater(
                                () -> panel.showChannelList(channelList, listQuery, truncated));
                    }
                    break;

                case CHANNEL_LIST_FAILED:
                    processMessage(new IrcMessage("System", "System",
                            "Channel list unavailable: " + event.getMessage(),
                            IrcMessage.MessageType.SYSTEM, Instant.now()));
                    if (panel != null) {
                        SwingUtilities.invokeLater(panel::cancelChannelListTimeout);
                    }
                    break;

                case NICK_IN_USE:
                    currentNick += "_";
                    processMessage(new IrcMessage("System", "System", "Nickname is already in use. Trying: " + currentNick, IrcMessage.MessageType.SYSTEM, Instant.now()));
                    sendRawLine("NICK " + currentNick);
                    break;

                case BAD_CHANNEL_KEY:
                    String badChannel = event.getTarget();
                    processMessage(new IrcMessage("System", "System", "Cannot join " + badChannel + ": " + event.getMessage(), IrcMessage.MessageType.SYSTEM, Instant.now()));
                    SwingUtilities.invokeLater(() -> {
                        Component parent = panel != null ? panel : null;
                        String password = JOptionPane.showInputDialog(parent, "Enter password for " + badChannel + ":", "Channel Key Required", JOptionPane.QUESTION_MESSAGE);
                        if (password != null && !password.isEmpty()) {
                            joinChannel(badChannel, password);
                        }
                    });
                    break;

                case WHOIS_REPLY:
                    processMessage(new IrcMessage("System", "WHOIS", event.getMessage(), IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case SERVER_ERROR:
                    // Reported, but never disconnects: most error numerics (no such nick, not a
                    // channel operator) leave a perfectly healthy connection in place.
                    processMessage(new IrcMessage("System", "Error", event.getMessage(), IrcMessage.MessageType.SYSTEM, Instant.now()));
                    break;

                case ERROR:
                    processMessage(new IrcMessage("System", "Error", event.getMessage() != null ? event.getMessage() : "Unknown error", IrcMessage.MessageType.SYSTEM, Instant.now()));
                    disconnect();
                    break;

                case TOPIC_INFO:
                    processMessage(new IrcMessage(event.getTarget(), event.getSource(), event.getMessage(), IrcMessage.MessageType.TOPIC, Instant.now()));
                    break;

                case HISTORY_BATCH:
                    if (event.getHistoryMessages() != null && !event.getHistoryMessages().isEmpty()) {
                        for (SimpleIrcClient.IrcEvent accEvent : event.getHistoryMessages()) {
                            Instant timestamp;
                            try {
                                String timeStr = accEvent.getAdditionalData();
                                timestamp = (timeStr != null && !timeStr.isEmpty())
                                    ? Instant.parse(timeStr)
                                    : Instant.now();
                            } catch (Exception e) {
                                timestamp = Instant.now();
                            }
                            String sender = accEvent.getSource() != null ? accEvent.getSource() : "";
                            if (accEvent.getType() == SimpleIrcClient.IrcEvent.Type.ACTION) {
                                sender = "* " + sender;
                            }
                            processMessage(new IrcMessage(
                                event.getTarget(), sender, accEvent.getMessage(),
                                IrcMessage.MessageType.HISTORY, timestamp
                            ));
                        }
                        processMessage(new IrcMessage(
                            event.getTarget(), "*", "--- Begin of chat ---",
                            IrcMessage.MessageType.HISTORY_SEPARATOR, Instant.now()
                        ));
                    }
                    break;
            }
        });
    }
}

package com.irc;

import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

@Slf4j
public class PreviewManager {
    private final OkHttpClient okHttpClient;
    private static final int MAX_PREVIEW_WIDTH = 500;
    private static final int MAX_PREVIEW_HEIGHT = 500;
    private Popup currentImagePreview;
    private CompletableFuture<?> imagePreviewFuture;
    private final Timer debounceTimer;
    private Point pendingPoint;
    private String pendingUrl;
    private final IrcPanel.ChannelPane channelPane;
    private static final Pattern IMAGE_URL_PATTERN = Pattern.compile("\\.(png|jpe?g|bmp)(\\?.*)?$", Pattern.CASE_INSENSITIVE);
    private final Cache<String, byte[]> imageCache;

    public PreviewManager(IrcPanel.ChannelPane channelPane, OkHttpClient okHttpClient) {
        this.channelPane = channelPane;
        this.debounceTimer = new Timer(100, e -> queueShowPreview());
        this.debounceTimer.setRepeats(false);
        this.imageCache = CacheBuilder.newBuilder()
                .maximumSize(50)
                .expireAfterWrite(5, TimeUnit.MINUTES)
                .build();
        this.okHttpClient = okHttpClient;
    }

    public void requestShow(Point mousePoint, String url) {
        cancelPreview();
        this.pendingPoint = mousePoint;
        this.pendingUrl = url;
        debounceTimer.restart();
    }

    private void queueShowPreview() {
        if (pendingPoint != null && pendingUrl != null && channelPane.isShowing()) {
            showImagePreview(this.pendingPoint, this.pendingUrl);
        }
    }

    public void cancelPreview() {
        debounceTimer.stop();
        pendingPoint = null;
        pendingUrl = null;
        hideImagePreview();
    }

    public boolean isImageUrl(String url) {
        return IMAGE_URL_PATTERN.matcher(url).find();
    }

    public void showImagePreview(Point mousePoint, String imageUrl) {
        cancelPreviewManager();
        this.pendingPoint = mousePoint;

        if (imagePreviewFuture != null && !imagePreviewFuture.isDone()) {
            imagePreviewFuture.cancel(true);
        }

        imagePreviewFuture = CompletableFuture.runAsync(() -> {
            try {
                handleStaticImagePreview(imageUrl);
            } catch (Exception e) {
                log.warn("Failed to create image preview for {}", imageUrl, e);
            }
        });
    }

    private void handleStaticImagePreview(String imageUrl) throws IOException {
        if (okHttpClient == null) {
            log.warn("No OkHttp connection available");
            return;
        }

        byte[] imageBytes = imageCache.getIfPresent(imageUrl);

        if (imageBytes == null || imageBytes.length == 0) {
            log.debug("Cache miss for {}, fetching from network.", imageUrl);

            String encodedUrl = URLEncoder.encode(imageUrl, StandardCharsets.UTF_8);

            // CloudFlare worker to protect users from IP grabbers
            String url = "https://image-proxy.cold-pine-9570.workers.dev/?url=" + encodedUrl;
            // Discord doesn't support CloudFlare workers :(
            if (imageUrl.startsWith("https://cdn.discordapp.com/")) {
                url = imageUrl;
            }

            Request request = new Request.Builder().url(url).build();
            okHttpClient.newCall(request).enqueue(new Callback() {
                @Override
                public void onFailure(Call call, IOException e) {
                    log.warn("Failed to fetch image preview for {}", imageUrl, e);
                }

                @Override
                public void onResponse(Call call, Response response) throws IOException {
                    if (!response.isSuccessful()) {
                        log.warn("Failed to fetch image preview for {}", imageUrl);
                        return;
                    }

                    if (response.code() != 200) {
                        log.warn("Failed to fetch image: {} returned status {}", imageUrl, response.code());
                        return;
                    }

                    String contentType = response.header("Content-Type");
                    if (contentType == null || !contentType.toLowerCase().startsWith("image/")) {
                        log.warn("Invalid content-type for {}: {}", imageUrl, contentType);
                        return;
                    }

                    if (response.body() == null) {
                        log.warn("Empty body for: {}", imageUrl);
                        return;
                    }

                    try (InputStream in = response.body().byteStream();
                         ByteArrayOutputStream baos = new ByteArrayOutputStream()) {

                        byte[] buffer = new byte[4096];
                        int n;
                        while ((n = in.read(buffer)) != -1) {
                            baos.write(buffer, 0, n);
                        }
                        byte[] imageBytes = baos.toByteArray();
                        imageCache.put(imageUrl, imageBytes);
                        response.close();

                        showPreview(imageUrl, imageBytes);
                    }
                }
            });
        } else {
            log.debug("Cache hit for {}", imageUrl);
            showPreview(imageUrl, imageBytes);
        }
    }

    private void showPreview(String imageUrl, byte[] imageBytes) throws IOException {
        if (imageBytes != null) {
            BufferedImage originalImage = ImageIO.read(new ByteArrayInputStream(imageBytes));
            if (originalImage == null) {
                log.warn("Could not decode image from URL: {}", imageUrl);
                imageCache.invalidate(imageUrl);
                return;
            }

            ImageIcon imageIcon = new ImageIcon(scaleImage(originalImage));

            JLabel preview = new JLabel(imageIcon);
            preview.addMouseListener(new MouseAdapter() {
                @Override
                public void mouseExited(MouseEvent e) {
                    cancelPreviewManager();
                }
            });
            SwingUtilities.invokeLater(() -> displayPopup(this.pendingPoint, preview));
        }
    }

    private BufferedImage scaleImage(BufferedImage originalImage) {
        double scale = Math.min(1.0, Math.min(
                (double) MAX_PREVIEW_WIDTH / originalImage.getWidth(),
                (double) MAX_PREVIEW_HEIGHT / originalImage.getHeight()
        ));

        int scaledWidth = (int) (originalImage.getWidth() * scale);
        int scaledHeight = (int) (originalImage.getHeight() * scale);

        BufferedImage scaledImage = new BufferedImage(scaledWidth, scaledHeight, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g2d = scaledImage.createGraphics();
        g2d.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g2d.drawImage(originalImage, 0, 0, scaledWidth, scaledHeight, null);
        g2d.dispose();
        return scaledImage;
    }

    private void displayPopup(Point location, JComponent content) {
        try {
            cancelPreviewManager();
            if (!channelPane.isShowing()) {
                return;
            }

            Window topLevelWindow = SwingUtilities.getWindowAncestor(channelPane);
            if (topLevelWindow == null) return;

            if (location == null) {
                log.warn("Mouse location is null");
                return;
            }
            SwingUtilities.convertPointToScreen(location, channelPane);

            Dimension contentSize = content.getPreferredSize();
            Rectangle screenBounds = topLevelWindow.getGraphicsConfiguration().getBounds();

            // Adjust Y coordinate
            if (location.y + contentSize.height > screenBounds.y + screenBounds.height) {
                Point componentOnScreen = channelPane.getLocationOnScreen();
                int yAbove = componentOnScreen.y + location.y - contentSize.height;

                if (yAbove >= screenBounds.y) {
                    location.y = yAbove;
                } else {
                    location.y = screenBounds.y + screenBounds.height - contentSize.height;
                }
            }

            if (location.x + contentSize.width > screenBounds.x + screenBounds.width) {
                location.x = screenBounds.x + screenBounds.width - contentSize.width;
            }

            if (location.y < screenBounds.y) {
                location.y = screenBounds.y;
            }
            if (location.x < screenBounds.x) {
                location.x = screenBounds.x;
            }

            content.setBorder(BorderFactory.createLineBorder(Color.DARK_GRAY));
            content.setOpaque(true);

            currentImagePreview = PopupFactory.getSharedInstance().getPopup(channelPane, content, location.x, location.y);
            currentImagePreview.show();
        } catch (Exception e) {
            log.warn("Could not display popup", e);
        }
    }

    void hideImagePreview() {
        if (imagePreviewFuture != null && !imagePreviewFuture.isDone()) {
            imagePreviewFuture.cancel(true);
            imagePreviewFuture = null;
        }
        if (currentImagePreview != null) {
            currentImagePreview.hide();
            currentImagePreview = null;
        }
    }

    void cancelPreviewManager() {
        cancelPreview();
    }
}

package com.irc;

import java.util.ArrayList;
import java.util.List;

/**
 * Readline-style history for the side-panel input box, shared across channels.
 *
 * Entries are ordered oldest-first. {@code cursor == entries.size()} means "live" (not
 * browsing); {@code 0 <= cursor < size} points at the entry currently shown. When browsing
 * begins, the unsent text is stashed as {@link #draft} so stepping past the newest entry can
 * restore it.
 */
class InputHistory {

    private final int capacity;
    private final List<String> entries = new ArrayList<>();
    private int cursor;
    private String draft = "";

    InputHistory(int capacity) {
        this.capacity = capacity;
    }

    /** Records a sent line and resets browsing. Ignores blank lines and consecutive duplicates. */
    void add(String line) {
        if (line == null || line.isEmpty()) {
            return;
        }
        if (entries.isEmpty() || !entries.get(entries.size() - 1).equals(line)) {
            entries.add(line);
            if (entries.size() > capacity) {
                entries.remove(0);
            }
        }
        cursor = entries.size();
        draft = "";
    }

    /**
     * Up: returns the previous (older) entry. On the first press from "live" it stashes
     * {@code currentText} as the draft and returns the newest entry; further presses walk
     * older and clamp at the oldest. Returns {@code null} when there is no history.
     */
    String previous(String currentText) {
        if (entries.isEmpty()) {
            return null;
        }
        if (cursor == entries.size()) {
            draft = currentText == null ? "" : currentText;
            cursor = entries.size() - 1;
        } else if (cursor > 0) {
            cursor--;
        }
        return entries.get(cursor);
    }

    /**
     * Down: returns the next (newer) entry. Stepping past the newest exits browsing and returns
     * the stashed draft. Returns {@code null} when not currently browsing.
     */
    String next() {
        if (cursor >= entries.size()) {
            return null;
        }
        if (cursor < entries.size() - 1) {
            cursor++;
            return entries.get(cursor);
        }
        cursor = entries.size();
        return draft;
    }
}

package com.irc;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The server's mode vocabulary, learned from RPL_ISUPPORT (numeric 005).
 *
 * Two tokens matter. {@code PREFIX=(qaohv)~&@%+} positionally pairs membership mode letters with
 * their display prefixes, and the position doubles as the rank (0 = most privileged).
 * {@code CHANMODES=A,B,C,D} says which mode letters consume a parameter, which is what makes
 * {@code MODE #chan +mo bob} apply "o" to "bob" rather than to whatever came next.
 *
 * Falls back to the widely-supported defaults below when a server sends no 005, or sends one
 * that omits or mangles a token. Mode letters absent from both tables are assumed parameterless.
 */
class ModeSpec {

    private static final String DEFAULT_PREFIX = "(qaohv)~&@%+";
    private static final String DEFAULT_CHANMODES = "beI,k,l,imnpst";

    private final Map<Character, Character> prefixByMode = new HashMap<>();
    private final Map<Character, Character> modeByPrefix = new HashMap<>();
    private final Map<Character, Integer> rankByMode = new HashMap<>();

    private String typeA = "";
    private String typeB = "";
    private String typeC = "";

    static ModeSpec defaults() {
        ModeSpec spec = new ModeSpec();
        spec.parsePrefix(DEFAULT_PREFIX);
        spec.parseChanmodes(DEFAULT_CHANMODES);
        return spec;
    }

    /**
     * Applies the token list from a 005 line. The leading nick and the trailing human-readable
     * description are not {@code KEY=VALUE} pairs and are skipped, as is any token we do not use.
     */
    void applyIsupport(List<String> tokens) {
        if (tokens == null) {
            return;
        }
        for (String token : tokens) {
            if (token == null) {
                continue;
            }
            int equals = token.indexOf('=');
            if (equals <= 0) {
                continue;
            }
            String key = token.substring(0, equals);
            String value = token.substring(equals + 1);
            if ("PREFIX".equals(key)) {
                parsePrefix(value);
            } else if ("CHANMODES".equals(key)) {
                parseChanmodes(value);
            }
        }
    }

    /** Parses {@code (modes)prefixes}; leaves the current table untouched if it does not parse. */
    private void parsePrefix(String value) {
        int close = value.indexOf(')');
        if (!value.startsWith("(") || close < 0) {
            return;
        }
        String modes = value.substring(1, close);
        String prefixes = value.substring(close + 1);
        if (modes.length() != prefixes.length() || modes.isEmpty()) {
            return;
        }

        prefixByMode.clear();
        modeByPrefix.clear();
        rankByMode.clear();
        for (int i = 0; i < modes.length(); i++) {
            prefixByMode.put(modes.charAt(i), prefixes.charAt(i));
            modeByPrefix.put(prefixes.charAt(i), modes.charAt(i));
            rankByMode.put(modes.charAt(i), i);
        }
    }

    /** Parses {@code A,B,C,D}. Type D is not stored - it is the "no parameter" default. Leaves the current table untouched if it does not parse. */
    private void parseChanmodes(String value) {
        String[] groups = value.split(",", -1);
        if (groups.length < 4) {
            return;
        }
        typeA = groups[0];
        typeB = groups[1];
        typeC = groups[2];
    }

    boolean isPrefixMode(char modeLetter) {
        return prefixByMode.containsKey(modeLetter);
    }

    char prefixFor(char modeLetter) {
        Character prefix = prefixByMode.get(modeLetter);
        return prefix == null ? '\0' : prefix;
    }

    Character modeForPrefix(char prefixChar) {
        return modeByPrefix.get(prefixChar);
    }

    int rankOf(char modeLetter) {
        Integer rank = rankByMode.get(modeLetter);
        return rank == null ? Integer.MAX_VALUE : rank;
    }

    boolean takesParameter(char modeLetter, boolean adding) {
        if (isPrefixMode(modeLetter)) {
            return true;
        }
        if (typeA.indexOf(modeLetter) >= 0 || typeB.indexOf(modeLetter) >= 0) {
            return true;
        }
        if (typeC.indexOf(modeLetter) >= 0) {
            return adding;
        }
        return false;
    }
}

package com.irc;

import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Locale;

/**
 * Tab completion for the input box: the word before the caret is completed from the nicks in
 * the focused buffer, or from the joined channels when it starts with '#'.
 *
 * Pressing Tab again straight away cycles through the other matches. That is detected by the
 * input still being exactly what the last completion produced; any edit, history recall or
 * caret move in between starts a fresh completion instead.
 */
class TabCompleter {

    /** The input box contents after a completion. */
    static final class Result {
        final String text;
        final int caret;

        Result(String text, int caret) {
            this.text = text;
            this.caret = caret;
        }
    }

    private List<String> matches = new ArrayList<>();
    private int index;
    /** The word the user typed before the first Tab. */
    private String word = "";
    private String head = "";
    private String tail = "";
    private boolean lineStart;
    private String lastText;
    private int lastCaret = -1;

    /**
     * Completes or cycles. Returns null when there is nothing to complete, leaving the input as it is.
     *
     * @param forward false steps backwards through the matches (Shift+Tab)
     */
    Result complete(String text, int caret, Collection<String> nicks, Collection<String> channels, boolean forward) {
        if (text.equals(lastText) && caret == lastCaret && !matches.isEmpty()) {
            // The input box is shared across buffers, so the candidates may have changed since the
            // last Tab. If the matches for the original word differ, start over with the new ones.
            List<String> current = findMatches(word, word.startsWith("#") ? channels : nicks);
            if (current.equals(matches)) {
                index = Math.floorMod(index + (forward ? 1 : -1), matches.size());
            } else if (current.isEmpty()) {
                matches = current;
                lastText = null;
                return null;
            } else {
                matches = current;
                index = forward ? 0 : matches.size() - 1;
            }
        } else {
            int wordStart = caret;
            while (wordStart > 0 && !Character.isWhitespace(text.charAt(wordStart - 1))) {
                wordStart--;
            }
            word = text.substring(wordStart, caret);
            if (word.isEmpty()) {
                return null;
            }
            matches = findMatches(word, word.startsWith("#") ? channels : nicks);
            if (matches.isEmpty()) {
                lastText = null;
                return null;
            }
            head = text.substring(0, wordStart);
            tail = text.substring(caret);
            lineStart = head.trim().isEmpty();
            index = forward ? 0 : matches.size() - 1;
        }

        String match = matches.get(index);
        // "bob: " addresses someone at the start of a line; elsewhere, and for channels, just a space.
        String suffix = lineStart && !match.startsWith("#") ? ": " : " ";
        if (tail.startsWith(" ")) {
            suffix = suffix.substring(0, suffix.length() - 1);
        }
        String completed = head + match + suffix;
        lastText = completed + tail;
        lastCaret = completed.length();
        return new Result(lastText, lastCaret);
    }

    private static List<String> findMatches(String word, Collection<String> candidates) {
        String lowerWord = word.toLowerCase(Locale.ROOT);
        List<String> found = new ArrayList<>();
        for (String candidate : candidates) {
            if (candidate.toLowerCase(Locale.ROOT).startsWith(lowerWord) && !found.contains(candidate)) {
                found.add(candidate);
            }
        }
        found.sort(String.CASE_INSENSITIVE_ORDER);
        return found;
    }
}

package com.irc;

import java.awt.Component;
import java.awt.Container;
import java.awt.event.ContainerEvent;
import java.awt.event.ContainerListener;
import java.awt.event.FocusAdapter;
import java.awt.event.FocusEvent;
import java.awt.event.FocusListener;
import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;
import java.util.function.IntConsumer;

/**
 * WeeChat-style buffer number keys, active while focus is inside {@code root}: Alt+1 to Alt+9 jump
 * straight to that buffer and Alt+0 to the tenth, and Alt+J followed by two digits jumps to any
 * buffer (Alt+J 1 1 for the eleventh).
 *
 * A key listener on every component under {@code root} rather than key bindings, because the
 * KEY_TYPED that follows a handled key press must be swallowed too: otherwise the digits after
 * Alt+J land in the input box, as does the character macOS produces for Option+digit. Consuming
 * the event in a listener stops Swing's key bindings, text entry included.
 */
final class ChannelNumberKeys implements KeyListener, ContainerListener {
    private final Component root;
    /** A pending Alt+J doesn't survive focus moving elsewhere. */
    private final FocusListener focusListener = new FocusAdapter() {
        @Override
        public void focusLost(FocusEvent e) { reset(); }
    };
    private final IntConsumer jump;
    /** Digits typed since Alt+J; null when no jump is pending. */
    private String digits;
    private boolean swallowTyped;

    ChannelNumberKeys(Component root, IntConsumer jump) {
        this.root = root;
        this.jump = jump;
    }

    void install() {
        attach(root);
    }

    void uninstall() {
        detach(root);
        reset();
    }

    @Override
    public void keyPressed(KeyEvent e) {
        if (handle(e)) e.consume();
    }

    @Override
    public void keyTyped(KeyEvent e) {
        if (handle(e)) e.consume();
    }

    @Override
    public void keyReleased(KeyEvent e) {}

    @Override
    public void componentAdded(ContainerEvent e) { attach(e.getChild()); }

    @Override
    public void componentRemoved(ContainerEvent e) { detach(e.getChild()); }

    private void attach(Component component) {
        // Removing first keeps a component that is re-added from getting a second listener.
        detach(component);
        component.addKeyListener(this);
        component.addFocusListener(focusListener);
        if (component instanceof Container) {
            Container container = (Container) component;
            container.addContainerListener(this);
            for (Component child : container.getComponents()) attach(child);
        }
    }

    private void detach(Component component) {
        component.removeKeyListener(this);
        component.removeFocusListener(focusListener);
        if (component instanceof Container) {
            Container container = (Container) component;
            container.removeContainerListener(this);
            for (Component child : container.getComponents()) detach(child);
        }
    }

    private void reset() {
        digits = null;
        swallowTyped = false;
    }

    /** Returns true when the event belongs to a channel jump and must not reach the component. */
    boolean handle(KeyEvent e) {
        if (e.getID() == KeyEvent.KEY_TYPED) return swallowTyped;
        if (e.getID() != KeyEvent.KEY_PRESSED) return false;

        swallowTyped = false;
        int code = e.getKeyCode();
        int digit = digitOf(code);
        if (digits != null) {
            if (isModifier(code)) return false;
            if (digit >= 0) {
                digits += digit;
                swallowTyped = true;
                if (digits.length() == 2) {
                    int number = Integer.parseInt(digits);
                    digits = null;
                    jump.accept(number);
                }
                return true;
            }
            digits = null;
            if (code == KeyEvent.VK_ESCAPE) return true;
        }
        if (!isPlainAlt(e)) return false;
        if (digit >= 0) {
            swallowTyped = true;
            jump.accept(digit == 0 ? 10 : digit);
            return true;
        }
        if (code == KeyEvent.VK_J) {
            digits = "";
            swallowTyped = true;
            return true;
        }
        return false;
    }

    private static int digitOf(int code) {
        if (code >= KeyEvent.VK_0 && code <= KeyEvent.VK_9) return code - KeyEvent.VK_0;
        if (code >= KeyEvent.VK_NUMPAD0 && code <= KeyEvent.VK_NUMPAD9) return code - KeyEvent.VK_NUMPAD0;
        return -1;
    }

    private static boolean isModifier(int code) {
        return code == KeyEvent.VK_ALT || code == KeyEvent.VK_SHIFT || code == KeyEvent.VK_CONTROL
                || code == KeyEvent.VK_META || code == KeyEvent.VK_ALT_GRAPH;
    }

    /** Alt alone: AltGr arrives as Ctrl+Alt on Windows and types characters, so it must not match. */
    private static boolean isPlainAlt(KeyEvent e) {
        int mods = e.getModifiersEx();
        int others = KeyEvent.CTRL_DOWN_MASK | KeyEvent.META_DOWN_MASK | KeyEvent.ALT_GRAPH_DOWN_MASK;
        return (mods & KeyEvent.ALT_DOWN_MASK) != 0 && (mods & others) == 0;
    }
}

